 - gW/2, eyeY + mYOff - gH/2, gW, gH); } else if (state.playerStunTimer > 0) { ctx.beginPath(); ctx.strokeStyle = 'black'; ctx.lineWidth = 2; for (let i = -10; i <= 10; i++) { const mx = cX + i, my = eyeY + mYOff + Math.sin(i * 0.5 + state.frame * 0.2) * 3; if (i === -10) ctx.moveTo(mx, my); else ctx.lineTo(mx, my); } ctx.stroke(); } else { ctx.beginPath(); ctx.strokeStyle = 'black'; ctx.lineWidth = 3; ctx.moveTo(cX - 8, eyeY + mYOff); ctx.lineTo(cX + 8, eyeY + mYOff); ctx.stroke(); }
    ctx.restore(); const gX = p.facing === 1 ? dX + dW - 10 : dX - 14, gY = p.isDucking ? dY + 10 : dY + 25;
    if (!isF) { 
