    pickups.forEach(p => { if (p.type.includes('health')) { ctx.fillStyle = 'red'; const thick = p.type === 'large_health' ? 10 : 5; ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height); ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick); } else { ctx.fillStyle = 'yellow'; const thick = p.type === 'large_ammo' ? 12 : 6; ctx.fillRect(p.pos.x + p.width/2 - thick/2, p.pos.y, thick, p.height); ctx.fillRect(p.pos.x, p.pos.y + p.height/2 - thick/2, p.width, thick); } });

    const dale = enemies.find(e => e.id === 'boss' && stageId === 'Drug Trade Dale');
    if (dale && dale.truckActive) {
      ctx.save();
      const tx = dale.truckX!, ty = 400, tw = 350, th = 150;
      ctx.fillStyle = '#333'; ctx.fillRect(tx, ty, tw, th);
      ctx.fillStyle = '#555'; ctx.fillRect(tx + tw - 80, ty + 20, 70, th - 40);
      ctx.fillStyle = '#ADFF2F'; ctx.fillRect(tx + 40, ty + 10, tw - 150, 40);
      ctx.fillStyle = '#000'; ctx.beginPath(); ctx.arc(tx + 60, ty + th, 30, 0, Math.PI*2); ctx.fill();
      ctx.beginPath(); ctx.arc(tx + tw - 60, ty + th, 30, 0, Math.PI*2); ctx.fill();
      ctx.restore();
    }

    state.bossVolcanoTelegraphs.forEach(t => { ctx.save(); ctx.fillStyle = 'red'; ctx.font = 'bold 40px "Press Start 2P"'; ctx.textAlign = 'center'; ctx.fillText("!", t.pos.x + (t.type === 'wall' ? (t.pos.x < 7600 ? 40 : -40) : 0), t.pos.y - (t.type === 'ground' ? 60 : 0)); ctx.restore(); });
    state.bossPoopTelegraphs.forEach(t => { ctx.save(); ctx.fillStyle = 'red'; ctx.font = 'bold 30px "Press Start 2P"'; ctx.textAlign = 'center'; ctx.fillText("!", t.spawnX === BOSS_DOOR_X ? BOSS_DOOR_X + 40 : 8000 - 40, t.pos.y); ctx.restore(); });
    state.bossVolcanoes.forEach(v => { ctx.save(); ctx.fillStyle = '#FF4500'; if (v.type === 'ground') { ctx.beginPath(); ctx.moveTo(v.pos.x - 40, v.pos.y); ctx.lineTo(v.pos.x, v.pos.y - 60); ctx.lineTo(v.pos.x + 40, v.pos.y); ctx.fill(); } else { const side = v.pos.x < 7600 ? 1 : -1; ctx.beginPath(); ctx.moveTo(v.pos.x, v.pos.y - 40); ctx.lineTo(v.pos.x + 60 * side, v.pos.y); ctx.lineTo(v.pos.x, v.pos.y + 40); ctx.fill(); } ctx.restore(); });

    enemies.forEach(e => { if (e.health <= 0 && !e.isBlownAway) return; ctx.save(); if (e.isTased && player.isTasing && player.taserTargetId === e.id) ctx.translate((Math.random()-0.5)*10, (Math.random()-0.5)*10); if (e.isBlownAway) { ctx.translate(e.pos.x + e.width / 2, e.pos.y + e.height / 2); ctx.rotate(e.rotation || 0); ctx.translate(-(e.pos.x + e.width / 2), -(e.pos.y + e.height / 2)); } else if (e.type === 'boss' && state.arenaLocked && e.hitCooldown && e.hitCooldown > 0 && Math.floor(state.frame / 5) % 2 === 0) ctx.globalAlpha = 0.4; if (e.needleCount && e.needleCount > 0) ctx.filter = `hue-rotate(${(state.frame * e.needleCount * 5) % 360}deg) saturate(2)`; if (e.type === 'boss') { if (state.bossExplosionTimer <= 0) BossLogic.drawBoss(ctx, e, stageId, state.frame); const curT = (status === GameStatus.BOSS_INTRO && bossTauntText) ? bossTauntText : (state.bossVulgarityTimer > 0 ? state.bossLastVulgarity : null); if (curT && state.bossExplosionTimer <= 0) { ctx.save(); ctx.font = 'bold 12px "Press Start 2P"'; ctx.fillStyle = 'white'; ctx.shadowColor = 'black'; ctx.shadowBlur = 6; ctx.textAlign = 'center'; ctx.fillText(curT, e.pos.x + e.width / 2, e.pos.y - 30); ctx.restore(); } BossLogic.drawDaleDrugs(ctx, e); } else { if (e.enemyType === 'shield') { ctx.fillStyle = '#444'; ctx.fillRect(e.pos.x + 10, e.pos.y, e.width - 10, e.height); if (e.isShieldActive) { ctx.fillStyle = '#2C3E50'; ctx.fillRect(e.pos.x, e.pos.y - 5, 15, e.height + 10); ctx.strokeStyle = '#00FFFF'; ctx.lineWidth = 2; ctx.strokeRect(e.pos.x, e.pos.y - 5, 15, e.height + 10); } else { ctx.fillStyle = '#7F8C8D'; ctx.fillRect(e.pos.x + 5, e.pos.y + 10, 10, e.height - 20); } } else if (e.id.startsWith('rusher')) ctx.fillStyle = '#9B59B6'; else if (e.enemyType === 'flyer' && e.width > 60) ctx.fillStyle = '#34495E'; else ctx.fillStyle = e.enemyType === 'flyer' ? COLORS.ENEMY_FLYER : (e.enemyType === 'drone' ? COLORS.ENEMY_DRONE : COLORS.ENEMY_TANK); if (!(e.enemyType === 'shield')) ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); } if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); } if (e.isTased && player.isTasing && player.taserTargetId === e.id) { ctx.fillStyle = 'rgba(0, 229, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); ctx.strokeStyle = '#FFFFFF'; ctx.lineWidth = 2; for(let j=0; j<4; j++){ ctx.beginPath(); const sx = e.width/2, sy = e.height/2; ctx.moveTo(sx, sy); ctx.lineTo(sx + (Math.random()-0.5)*100, sy + (Math.random()-0.5)*100); ctx.stroke(); } } if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); } ctx.restore(); });
    if (status !== GameStatus.LEVEL_INTRO || state.introTimer >= 80) { drawPlayer(ctx, player); if (state.playerLastVulgarity && state.playerVulgarityTimer > 0 && state.bossExplosionTimer <= 0) { ctx.save(); ctx.font = 'bold 10px "Press Start 2P"'; ctx.fillStyle = 'white'; ctx.shadowColor = 'black'; ctx.shadowBlur = 4; ctx.textAlign = 'center'; ctx.fillText(state.playerLastVulgarity, player.pos.x + player.width / 2, player.pos.y - 20); ctx.restore(); } }
    if (player.isTasing && player.currentWeapon === 'TASER') { const target = (enemies.find(en => en.id === player.taserTargetId) || projectiles.find(pr => pr.id === player.taserTargetId)) as (Enemy | Projectile | undefined); if (target) { ctx.save(); ctx.strokeStyle = COLORS.TASER_BOLT; ctx.lineWidth = 3; ctx.shadowBlur = 10; ctx.shadowColor = COLORS.TASER_BOLT; const startX = player.pos.x + (player.facing === 1 ? player.width : 0); const startY = player.pos.y + 25; const endX = target.pos.x + target.width/2; const endY = target.pos.y + target.height/2; ctx.beginPath(); ctx.moveTo(startX, startY); const segments = 8; for (let i = 1; i < segments; i++) { const t = i / segments; const px = startX + (endX - startX) * t + (Math.random() - 0.5) * 40; const py = startY + (endY - startY) * t + (Math.random() - 0.5) * 40; ctx.lineTo(px, py); } ctx.lineTo(endX, endY); ctx.stroke(); ctx.strokeStyle = 'white'; ctx.lineWidth = 1; ctx.stroke(); ctx.restore(); } }
    state.projectiles.forEach(p => { ctx.save(); if (p.isBoulder) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); ctx.fillStyle = p.owner === 'player' ? '#8B4513' : '#4E342E'; ctx.beginPath(); const seg = 10, bR = p.width / 2; for (let i = 0; i < seg; i++) { const a = (i / seg) * Math.PI * 2, v = 0.85 + Math.abs(Math.sin(i * 3 + (p.id.length % 5))) * 0.3, r = bR * v, x = Math.cos(a) * r, y = Math.sin(a) * r; if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y); } ctx.closePath(); ctx.fill(); ctx.strokeStyle = 'black'; ctx.lineWidth = 2; ctx.stroke(); ctx.restore(); } else if (p.isSludge) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); if (p.isLingering) { ctx.fillStyle = '#1B5E20'; ctx.beginPath(); const segs = 14; const rx = p.width / 2; const ry = p.height / 2; const seed = (p.id.length * 123) % 1000; for (let i = 0; i < segs; i++) { const ang = (i / segs) * Math.PI * 2; const jitter = 0.65 + (Math.abs(Math.sin(i * 3 + seed)) * 0.45); const tx = Math.cos(ang) * rx * jitter; const ty = Math.sin(ang) * ry * jitter; if (i === 0) ctx.moveTo(tx, ty); else ctx.lineTo(tx, ty); } ctx.closePath(); ctx.fill(); ctx.strokeStyle = '#ADFF2F'; ctx.lineWidth = 2; ctx.stroke(); ctx.fillStyle = '#ADFF2F'; for (let i = 0; i < 3; i++) { const bpx = Math.sin(state.frame * 0.12 + i) * rx * 0.4; const bpy = Math.cos(state.frame * 0.12 + i) * ry * 0.4; ctx.beginPath(); ctx.arc(bpx, bpy, 3, 0, Math.PI * 2); ctx.fill(); } } else { ctx.rotate(state.frame * 0.3 + p.id.length); ctx.fillStyle = '#1B5E20'; ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height); ctx.strokeStyle = '#ADFF2F'; ctx.lineWidth = 2; ctx.strokeRect(-p.width/2, -p.height/2, p.width, p.height); } ctx.restore(); } else if (p.isCocaine) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(state.frame * 0.1); ctx.fillStyle = '#fff'; ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height); ctx.strokeStyle = '#ccc'; ctx.strokeRect(-p.width/2, -p.height/2, p.width, p.height); ctx.restore(); } else if (p.isMethBarrel) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.rotation || 0); ctx.fillStyle = '#111'; ctx.strokeStyle = '#FFD700'; ctx.lineWidth = 2; ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height); ctx.strokeRect(-p.width/2, -p.height/2, p.width, p.height); ctx.fillStyle = '#FFD700'; ctx.font = 'bold 8px "Press Start 2P"'; ctx.textAlign = 'center'; ctx.fillText("METH", 0, 5); ctx.restore(); } else if (p.isDart) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(-p.width/2 + (p.vel.x > 0 ? 5 : 0), -p.height/2, p.width - 5, p.height); ctx.fillStyle = 'red'; ctx.fillRect(p.vel.x > 0 ? -p.width/2 : p.width/2 - 5, -p.height/2 - 1, 6, p.height + 2); ctx.restore(); } else { ctx.fillStyle = (p.isIce) ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); } ctx.restore(); });
    particles.forEach(p => { ctx.save(); if (!p.isStuck) ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; else ctx.globalAlpha = 0.85; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); ctx.restore(); });
    damageNumbers.forEach(d => { ctx.save(); ctx.globalAlpha = d.life / d.maxLife; ctx.font = `bold ${d.isCritical ? '24px' : '16px'} "Press Start 2P"`; ctx.fillStyle = d.isCritical ? '#FFD700' : (d.value > 50 ? '#FF4500' : '#FFFFFF'); ctx.textAlign = 'center'; ctx.fillText(d.value.toString(), d.pos.x, d.pos.y); ctx.restore(); });
    ctx.restore();
    if (state.victoryString && (status === GameStatus.PLAYING || status === GameStatus.VICTORY)) { ctx.save(); ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.textAlign = 'center'; ctx.strokeStyle = 'black'; ctx.lineWidth = 4; ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore(); }
    if (state.deathTimer > 0) { ctx.save(); ctx.font = 'bold 60px "Press Start 2P"'; ctx.fillStyle = '#FF0000'; ctx.textAlign = 'center'; ctx.fillText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore(); }
  }, [status, stageId, bossTauntText]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) { if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) { gameStateRef.current.victoryString = ""; gameStateRef.current.postVictoryTimer = 0; gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.introTimer = 0; gameStateRef.current.particles = []; gameStateRef.current.projectiles = []; gameStateRef.current.pickups = []; gameStateRef.current.enemies = []; gameStateRef.current.damageNumbers = []; gameStateRef.current.camera = { x: 0, y: 0 }; gameStateRef.current.player.health = INITIAL_PLAYER_HEALTH; createLevel(); gameStateRef.current.frame = 1; } frameId = window.requestAnimationFrame(loop); } else { const s = gameStateRef.current; s.victoryString = ""; s.postVictoryTimer = 0; s.bossExplosionTimer = 0; s.introTimer = 0; s.enemies = []; s.particles = []; s.projectiles = []; s.blocks = []; s.camera = { x: 0, y: 0 }; s.frame = 0; draw(); }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel, initialAmmo, jumpToBossEnabled]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

