    } else if (p.isCocaine) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(state.frame * 0.1); ctx.fillStyle = '#fff'; ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height); ctx.strokeStyle = '#ccc'; ctx.strokeRect(-p.width/2, -p.height/2, p.width, p.height); ctx.restore(); } else if (p.isMethBarrel) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.rotation || 0); ctx.fillStyle = '#111'; ctx.strokeStyle = '#FFD700'; ctx.lineWidth = 2; ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height); ctx.strokeRect(-p.width/2, -p.height/2, p.width, p.height); ctx.fillStyle = '#FFD700'; ctx.font = 'bold 8px "Press Start 2P"'; ctx.textAlign = 'center'; ctx.fillText("METH", 0, 5); ctx.restore(); } else if (p.isDart) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(-p.width/2 + (p.vel.x > 0 ? 5 : 0), -p.height/2, p.width - 5, p.height); ctx.fillStyle = 'red'; ctx.fillRect(p.vel.x > 0 ? -p.width/2 : p.width/2 - 5, -p.height/2 - 1, 6, p.height + 2); ctx.restore(); } else { ctx.fillStyle = (p.isIce) ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); } ctx.restore(); });
    particles.forEach(p => { ctx.save(); if (!p.isStuck) ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; else ctx.globalAlpha = 0.85; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); ctx.restore(); });
    damageNumbers.forEach(d => { ctx.save(); ctx.globalAlpha = d.life / d.maxLife; ctx.font = `bold ${d.isCritical ? '24px' : '16px'} "Press Start 2P"`; ctx.fillStyle = d.isCritical ? '#FFD700' : (d.value > 50 ? '#FF4500' : '#FFFFFF'); ctx.textAlign = 'center'; ctx.fillText(d.value.toString(), d.pos.x, d.pos.y); ctx.restore(); });
    ctx.restore();
    if (state.victoryString && (status === GameStatus.PLAYING || status === GameStatus.VICTORY)) { ctx.save(); ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.textAlign = 'center'; ctx.strokeStyle = 'black'; ctx.lineWidth = 4; ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore(); }
    if (state.deathTimer > 0) { ctx.save(); ctx.font = 'bold 60px "Press Start 2P"'; ctx.fillStyle = '#FF0000'; ctx.textAlign = 'center'; ctx.fillText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore(); }
  }, [status, stageId, bossTauntText]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) { if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) { gameStateRef.current.victoryString = ""; gameStateRef.current.postVictoryTimer = 0; gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.introTimer = 0; gameStateRef.current.particles = []; gameStateRef.current.projectiles = []; gameStateRef.current.pickups = []; gameStateRef.current.enemies = []; gameStateRef.current.damageNumbers = []; gameStateRef.current.camera = { x: 0, y: 0 }; gameStateRef.current.player.health = INITIAL_PLAYER_HEALTH; createLevel(); gameStateRef.current.frame = 1; } frameId = window.requestAnimationFrame(loop); } else { const s = gameStateRef.current; s.victoryString = ""; s.postVictoryTimer = 0; s.bossExplosionTimer = 0; s.introTimer = 0; s.enemies = []; s.particles = []; s.projectiles = []; s.blocks = []; s.camera = { x: 0, y: 0 }; s.frame = 0; draw(); }
