const handleVictorAI = (boss: Enemy, player: Player, healthPct: number, state: any, helpers: BossHelpers) => {
  const victorMidX = boss.pos.x + boss.width / 2;
  if (boss.bossState === 'attacking') { boss.vel.x = 0; if (state.bossVolcanoes.length === 0 && boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; } } else if (boss.bossState === 'telegraphing') { boss.vel.x = 0; if (boss.stateTimer! <= 0) { boss.bossState = 'attacking'; boss.stateTimer = 180; state.bossVolcanoTelegraphs.forEach((t: Volcano) => helpers.addVolcano({ pos: t.pos, life: 180, type: t.type })); helpers.clearVolcanoTelegraphs(); } } else if (boss.bossState === 'jumping') { if (boss.isGroundedBoss) { boss.bossState = 'telegraphing'; boss.stateTimer = 60; helpers.clearVolcanoTelegraphs(); const newSide = (state.victorWallSide + 1) % 2; helpers.setVictorWallSide(newSide); helpers.addVolcanoTelegraph({ pos: { x: newSide === 0 ? BOSS_DOOR_X : 8000, y: 250 + Math.random() * 200 }, life: 60, type: 'wall' }); const groundCount = healthPct > 50 ? 1 : 2; const groundXs: number[] = []; for(let i=0; i<groundCount; i++) { let tx = 0, attempts = 0, valid = false; while(!valid && attempts < 20) { tx = BOSS_DOOR_X + 150 + Math.random() * 500; valid = Math.abs(tx - victorMidX) > 150; if (valid) for (const existingX of groundXs) if (Math.abs(tx - existingX) < 100) { valid = false; break; } attempts++; } groundXs.push(tx); helpers.addVolcanoTelegraph({ pos: { x: Math.max(BOSS_DOOR_X + 50, Math.min(7900, tx)), y: 550 }, life: 60, type: 'ground' }); } } } else if (boss.stateTimer! <= 0) { boss.vel.y = -20 - Math.random() * 5; const platforms = state.blocks.filter((b: any) => b.type === 'platform' && b.x > BOSS_DOOR_X); if (platforms.length > 0) { const targetPlate = platforms[Math.floor(Math.random() * platforms.length)]; boss.vel.x = (targetPlate.x + targetPlate.w / 2 - victorMidX) * 0.04; } else { boss.vel.x = (player.pos.x < boss.pos.x ? -1 : 1) * 4 + (Math.random()-0.5)*2; } boss.bossState = 'jumping'; boss.stateTimer = 60; } if (boss.isGroundedBoss) boss.vel.x *= 0.95;
};

export const drawBoss = (ctx: CanvasRenderingContext2D, e: Enemy, id: string | null, frame: number) => {
  const { pos, width, height } = e; ctx.save(); ctx.translate(pos.x, pos.y);

  const shouldSpin = e.rotation && !(id === 'Hector Hurricane' && e.bossState === 'hurricane');
  if (shouldSpin) { 
    ctx.translate(width / 2, height / 2); ctx.rotate(e.rotation!); ctx.translate(-width / 2, -height / 2); 
  }

  if (id === 'Drug Trade Dale' && e.bossState === 'speed_dash') ctx.filter = `hue-rotate(${frame * 10}deg) saturate(3)`;
  switch (id) {
    case 'Artie Avalanche': ctx.fillStyle = '#AED6F1'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.fillStyle = '#FF8A80'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); ctx.fillStyle = '#2E86C1'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, Math.PI, 0); ctx.fill(); ctx.stroke(); break;
    case 'Victor Volcano': ctx.fillStyle = '#BA4A00'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); const lOff = (e.bossState === 'attacking' || e.bossState === 'telegraphing') ? Math.sin(frame * 0.5) * 6 : 0; ctx.fillStyle = '#C62828'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3 + lOff, width * 0.3, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); ctx.fillStyle = '#FF4500'; ctx.fillRect(width * 0.2, height * 0.2 + lOff, width * 0.6, height * 0.1); break;
    case 'Ernie Earthquake': ctx.fillStyle = '#6E2C00'; ctx.fillRect(0, height * 0.3, width, height * 0.7); ctx.strokeRect(0, height * 0.3, width, height * 0.7); ctx.fillStyle = '#FF5252'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); break;
    case 'Hector Hurricane': 
      if (e.bossState === 'hurricane') {
         ctx.save(); ctx.lineWidth = 3; ctx.shadowBlur = 15; ctx.shadowColor = '#00E5FF';
         for(let i=0; i<3; i++) {
           if ((frame + i * 20) % 30 < 5) {
             ctx.strokeStyle = i % 2 === 0 ? '#FFFFFF' : '#00E5FF'; ctx.beginPath(); ctx.moveTo(width/2, height/2); let curX = width/2, curY = height/2;
             for(let j=0; j<6; j++) { curX += (Math.random()-0.5) * 80; curY += (Math.random()-0.5) * 80; ctx.lineTo(curX, curY); }
             ctx.stroke();
           }
         }
         ctx.globalAlpha = 0.5; ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
         for(let i=0; i<8; i++){
            const arcR = width * (1.2 + Math.sin(frame * 0.1 + i) * 0.3); const startA = frame * 0.15 + i * (Math.PI/4);
            ctx.beginPath(); ctx.arc(width/2, height/2, arcR, startA, startA + 0.6); ctx.stroke();
         }
         ctx.restore();
      }
      ctx.fillStyle = '#16A085'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.strokeRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.fillStyle = '#FF8A80'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); break;
    case 'Drug Trade Dale': ctx.fillStyle = '#2C3E50'; ctx.fillRect(0, 0, width, height); ctx.strokeRect(0, 0, width, height); ctx.fillStyle = '#8E44AD'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); ctx.fillStyle = 'gold'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.25, width * 0.2, 0, Math.PI * 2); ctx.fill(); if (e.bossState === 'using_shipment') { ctx.fillStyle = '#fff'; ctx.fillRect(width * 0.1, -20, width * 0.8, 20); } if (e.bossState === 'speed_dash') { ctx.save(); ctx.translate(width * 0.2, height * 0.3); ctx.rotate(-0.5); ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(0, -2, 16, 4); ctx.fillStyle = 'red'; ctx.fillRect(16, -4, 6, 8); ctx.restore(); } break;
    case 'Toxic Tommy': ctx.fillStyle = '#27AE60'; ctx.fillRect(0, 0, width, height); ctx.strokeRect(0, 0, width, height); ctx.fillStyle = '#ADFF2F'; ctx.fillRect(width * 0.1, height * 0.1, width * 0.8, height * 0.3); ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(width * 0.3, height * 0.25, 4, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(width * 0.7, height * 0.25, 4, 0, Math.PI * 2); ctx.fill(); break;
    default: ctx.fillStyle = 'yellow'; ctx.fillRect(0, 0, width, height); break;
  }
  ctx.restore();
};

export const drawDaleDrugs = (ctx: CanvasRenderingContext2D, e: Enemy) => {
  if (e.bossState === 'using_shipment' && e.shipmentCount! > 0) { const stackX = e.pos.x - 60, groundY = 550; ctx.save(); for (let i = 0; i < e.shipmentCount!; i++) { const row = Math.floor(i / 2), col = i % 2; if (e.shipmentType === 'cocaine') { ctx.fillStyle = '#fff'; ctx.strokeStyle = '#ccc'; ctx.lineWidth = 1; const bx = stackX + (col * 20) + (row * 3), by = groundY - (row * 15) - 20; ctx.fillRect(bx, by, 18, 18); ctx.strokeRect(bx, by, 18, 18); } else if (e.shipmentType === 'meth') { ctx.fillStyle = '#111'; ctx.strokeStyle = '#FFD700'; ctx.lineWidth = 2; const bx = stackX + (col * 30) - 10, by = groundY - (row * 35) - 40; ctx.fillRect(bx, by, 30, 40); ctx.strokeRect(bx, by, 30, 40); ctx.fillStyle = '#FFD700'; ctx.font = '8px "Press Start 2P"'; ctx.textAlign = 'center'; ctx.fillText("METH", bx + 15, by + 25); } else if (e.shipmentType === 'speed' && e.stateTimer! > 0) { const bx = stackX, by = groundY - 20; ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(bx + 5, by, 15, 4); ctx.fillStyle = 'red'; ctx.fillRect(bx, by - 2, 6, 8); } } ctx.restore(); }
};

