        setCurrentWeapon('GUN'); 
        setStatus(GameStatus.STAGE_SELECT);
      } else {
        setDefeatedStages([]); 
        const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS_CHEAT : (progressionRank === 1 ? SET0_WEAPONS : ['GUN']); 
        setAvailableWeapons(weaponsToStart); 
        setCurrentWeapon('GUN'); 
        setWeaponAmmo({ 'GUN': Infinity, 'BOULDER': MAX_AMMO['BOULDER'], 'SHOTGUN': MAX_AMMO['SHOTGUN'], 'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'], 'TSUNAMI': MAX_AMMO['TSUNAMI'], 'NEEDLES': MAX_AMMO['NEEDLES'], 'TASER': MAX_AMMO['TASER'], 'SLUDGE': MAX_AMMO['SLUDGE'] }); 
        setSelectedIndex(0); 
        setIsVictoryPhase(false); 
        setStatus(GameStatus.START);
      }
    } else if (status === GameStatus.START) {
      const weaponsToStart: WeaponType[] = (cheatEnabled && SHOW_CHEATS) ? ALL_WEAPONS_CHEAT : (progressionRank === 1 ? SET0_WEAPONS : ['GUN']); 
      setAvailableWeapons(weaponsToStart); 
      setCurrentWeapon('GUN'); 
      setWeaponAmmo({ 'GUN': Infinity, 'BOULDER': MAX_AMMO['BOULDER'], 'SHOTGUN': MAX_AMMO['SHOTGUN'], 'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'], 'TSUNAMI': MAX_AMMO['TSUNAMI'], 'NEEDLES': MAX_AMMO['NEEDLES'], 'TASER': MAX_AMMO['TASER'], 'SLUDGE': MAX_AMMO['SLUDGE'] }); 
      setStatus(GameStatus.STAGE_SELECT);
    } else if (status === GameStatus.BOSS_INTRO) {
      setStatus(GameStatus.PLAYING);
    } else if (status === GameStatus.BOSS_VICTORY_SPEECH) {
      setIsVictoryPhase(false);
      if (defeatedStages.length >= 4) { setStatus(GameStatus.VICTORY); } 
      else { 
        setStatus(GameStatus.STAGE_SELECT); 
        setSelectedStage(null); 
        setSelectedIndex(0); 
        setCurrentWeapon('GUN'); 
        setWeaponAmmo({ 'GUN': Infinity, 'BOULDER': MAX_AMMO['BOULDER'], 'SHOTGUN': MAX_AMMO['SHOTGUN'], 'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'], 'TSUNAMI': MAX_AMMO['TSUNAMI'], 'NEEDLES': MAX_AMMO['NEEDLES'], 'TASER': MAX_AMMO['TASER'], 'SLUDGE': MAX_AMMO['SLUDGE'] }); 
      }
    }
  }, [status, defeatedStages, overlayActiveTime, cheatEnabled, progressionRank]);

  const handleResume = useCallback(() => { setStatus(GameStatus.PLAYING); }, []);

  const handleBossSelect = useCallback(() => {
    setSelectedStage(null); setSelectedIndex(0); setIsVictoryPhase(false); setCurrentWeapon('GUN'); setStatus(GameStatus.STAGE_SELECT); setWeaponAmmo({ 'GUN': Infinity, 'BOULDER': MAX_AMMO['BOULDER'], 'SHOTGUN': MAX_AMMO['SHOTGUN'], 'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'], 'TSUNAMI': MAX_AMMO['TSUNAMI'], 'NEEDLES': MAX_AMMO['NEEDLES'], 'TASER': MAX_AMMO['TASER'], 'SLUDGE': MAX_AMMO['SLUDGE'] });
  }, []);

  const handleQuitToMenu = useCallback(() => { setSelectedStage(null); setSelectedIndex(0); setIsVictoryPhase(false); setDefeatedStages([]); setCurrentWeapon('GUN'); setProgressionRank(0); setStatus(GameStatus.START); }, []);

  const handleSelectStage = useCallback((stage: string) => {
    if (defeatedStages.includes(stage)) { speakRebuke(); return; }
    setSelectedStage(stage); setHealth(INITIAL_PLAYER_HEALTH); setSpecialCharges(2); setSpecialChargeTimer(0); setCurrentWeapon('GUN'); setWeaponAmmo({ 'GUN': Infinity, 'BOULDER': MAX_AMMO['BOULDER'], 'SHOTGUN': MAX_AMMO['SHOTGUN'], 'FLAMETHROWER': MAX_AMMO['FLAMETHROWER'], 'TSUNAMI': MAX_AMMO['TSUNAMI'], 'NEEDLES': MAX_AMMO['NEEDLES'], 'TASER': MAX_AMMO['TASER'], 'SLUDGE': MAX_AMMO['SLUDGE'] }); setIsVictoryPhase(false); setStatus(GameStatus.LEVEL_INTRO);
  }, [defeatedStages, speakRebuke]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const key = e.key.toLowerCase();
      if (key === 'escape') togglePause();

      if (status === GameStatus.PAUSED || status === GameStatus.STAGE_SELECT) {
        const numW = availableWeapons.length;

        if (key === 'arrowup' || key === 'w') { 
          if (status === GameStatus.PAUSED) {
            setSelectedIndex(p => {
              if (p >= numW) return p - 1; 
              if (p >= 4) return p - 4; 
              return p;
            });
          }
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p - 2 + 4) % 4); 
        } 
        else if (key === 'arrowdown' || key === 's') { 
          if (status === GameStatus.PAUSED) {
            setSelectedIndex(p => {
              if (p < numW && p + 4 < numW) return p + 4; 
              if (p < numW) return numW; 
              if (p < numW + 2) return p + 1; 
              return p;
            });
          }
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p + 2) % 4); 
        } 
        else if (key === 'arrowleft' || key === 'a') { 
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
          if (status === GameStatus.PAUSED && selectedIndex < numW) {
            setSelectedIndex(p => p > 0 ? p - 1 : p);
          }
        } 
        else if (key === 'arrowright' || key === 'd') { 
          if (status === GameStatus.STAGE_SELECT) setSelectedIndex(p => (p % 2 === 0 ? p + 1 : p - 1));
          if (status === GameStatus.PAUSED && selectedIndex < numW) {
            setSelectedIndex(p => p < numW - 1 ? p + 1 : p);
          }
        } 
        else if (key === 'enter' || key === ' ') { 
          if (status === GameStatus.PAUSED) {
            if (selectedIndex < numW) {
              selectWeaponByIndex(selectedIndex);
            } else if (selectedIndex === numW) {
              handleResume();
            } else if (selectedIndex === numW + 1) {
              handleBossSelect();
            } else if (selectedIndex === numW + 2) {
              handleQuitToMenu();
            }
          } else if (status === GameStatus.STAGE_SELECT) { handleSelectStage(STAGES(progressionRank)[selectedIndex].id); } 
        }
      } else if (status === GameStatus.PLAYING) { 
