      } 
      else if (status === GameStatus.START || status === GameStatus.BOSS_INTRO || status === GameStatus.BOSS_VICTORY_SPEECH || status === GameStatus.VICTORY) { if (key === 'enter' || key === ' ') handleStart(); }
    };
