    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) { if (gameStateRef.current.frame === 0 && status === GameStatus.LEVEL_INTRO) { gameStateRef.current.victoryString = ""; gameStateRef.current.postVictoryTimer = 0; gameStateRef.current.bossExplosionTimer = 0; gameStateRef.current.introTimer = 0; gameStateRef.current.particles = []; gameStateRef.current.projectiles = []; gameStateRef.current.pickups = []; gameStateRef.current.enemies = []; gameStateRef.current.damageNumbers = []; gameStateRef.current.camera = { x: 0, y: 0 }; gameStateRef.current.player.health = INITIAL_PLAYER_HEALTH; createLevel(); gameStateRef.current.frame = 1; } frameId = window.requestAnimationFrame(loop); } else { const s = gameStateRef.current; s.victoryString = ""; s.postVictoryTimer = 0; s.bossExplosionTimer = 0; s.introTimer = 0; s.enemies = []; s.particles = []; s.projectiles = []; s.blocks = []; s.camera = { x: 0, y: 0 }; s.frame = 0; draw(); }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel, initialAmmo, jumpToBossEnabled]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

