      else { const side = v.pos.x < 7600 ? 1 : -1, baseH = 100, topH = 40, w = 70; ctx.fillStyle = '#4E342E'; ctx.beginPath(); ctx.moveTo(v.pos.x, v.pos.y - baseH/2); ctx.lineTo(v.pos.x + w * side, v.pos.y - topH/2); ctx.lineTo(v.pos.x + w * side, v.pos.y + topH/2); ctx.lineTo(v.pos.x, v.pos.y + baseH/2); ctx.closePath(); ctx.fill(); ctx.strokeStyle = '#212121'; ctx.lineWidth = 3; ctx.stroke(); ctx.fillStyle = '#FF4500'; ctx.beginPath(); ctx.ellipse(v.pos.x + w * side, v.pos.y, topH/4, topH/2, 0, 0, Math.PI * 2); ctx.fill(); } ctx.restore(); 
