, e.pos.y, e.width, e.height); } if (e.frozenTimer && e.frozenTimer > 0) { ctx.fillStyle = 'rgba(0, 255, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); } if (e.isTased && player.isTasing && player.taserTargetId === e.id) { ctx.fillStyle = 'rgba(0, 229, 255, 0.4)'; ctx.fillRect(e.pos.x - 5, e.pos.y - 5, e.width + 10, e.height + 10); ctx.strokeStyle = '#FFFFFF'; ctx.lineWidth = 2; for(let j=0; j<4; j++){ ctx.beginPath(); const sx = e.width/2, sy = e.height/2; ctx.moveTo(sx, sy); ctx.lineTo(sx + (Math.random()-0.5)*100, sy + (Math.random()-0.5)*100); ctx.stroke(); } } if (!e.isBlownAway) { ctx.fillStyle = '#00FF00'; ctx.fillRect(e.pos.x, e.pos.y - 10, (e.health / e.maxHealth) * e.width, 5); } ctx.restore(); });
    if (status !== GameStatus.LEVEL_INTRO || state.introTimer >= 20) { drawPlayer(ctx, player); if (state.playerLastVulgarity && state.playerVulgarityTimer > 0 && state.bossExplosionTimer <= 0) { ctx.save(); ctx.font = 'bold 10px "Press Start 2P"'; ctx.fillStyle = 'white'; ctx.shadowColor = 'black'; ctx.shadowBlur = 4; ctx.textAlign = 'center'; ctx.fillText(state.playerLastVulgarity, player.pos.x + player.width / 2, player.pos.y - 20); ctx.restore(); } }
    if (player.isTasing && player.currentWeapon === 'TASER') { const target = (enemies.find(en => en.id === player.taserTargetId) || projectiles.find(pr => pr.id === player.taserTargetId)) as (Enemy | Projectile | undefined); if (target) { ctx.save(); ctx.strokeStyle = COLORS.TASER_BOLT; ctx.lineWidth = 3; ctx.shadowBlur = 10; ctx.shadowColor = COLORS.TASER_BOLT; const startX = player.pos.x + (player.facing === 1 ? player.width : 0), startY = player.pos.y + 25, endX = target.pos.x + target.width/2, endY = target.pos.y + target.height/2; ctx.beginPath(); ctx.moveTo(startX, startY); const segments = 8; for (let i = 1; i < segments; i++) { const t = i / segments, px = startX + (endX - startX) * t + (Math.random() - 0.5) * 40, py = startY + (endY - startY) * t + (Math.random() - 0.5) * 40; ctx.lineTo(px, py); } ctx.lineTo(endX, endY); ctx.stroke(); ctx.strokeStyle = 'white'; ctx.lineWidth = 1; ctx.stroke(); ctx.restore(); } }
    state.projectiles.forEach(p => { ctx.save(); if (p.isBoulder) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.pos.x * 0.05); ctx.fillStyle = p.owner === 'player' ? '#8B4513' : '#4E342E'; ctx.beginPath(); const seg = 10, bR = p.width / 2; for (let i = 0; i < seg; i++) { const a = (i / seg) * Math.PI * 2, v = 0.85 + Math.abs(Math.sin(i * 3 + (p.id.length % 5))) * 0.3, r = bR * v, x = Math.cos(a) * r, y = Math.sin(a) * r; if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y); } ctx.closePath(); ctx.fill(); ctx.strokeStyle = 'black'; ctx.lineWidth = 2; ctx.stroke(); ctx.restore(); } else if (p.isSludge) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); if (p.isLingering) { ctx.fillStyle = '#1B5E20'; ctx.beginPath(); const segs = 14, rx = p.width / 2, ry = p.height / 2, seed = (p.id.length * 123) % 1000; for (let i = 0; i < segs; i++) { const ang = (i / segs) * Math.PI * 2, jitter = 0.65 + (Math.abs(Math.sin(i * 3 + seed)) * 0.45), tx = Math.cos(ang) * rx * jitter, ty = Math.sin(ang) * ry * jitter; if (i === 0) ctx.moveTo(tx, ty); else ctx.lineTo(tx, ty); } ctx.closePath(); ctx.fill(); ctx.strokeStyle = '#ADFF2F'; ctx.lineWidth = 2; ctx.stroke(); ctx.fillStyle = '#ADFF2F'; for (let i = 0; i < 3; i++) { const bpx = Math.sin(state.frame * 0.12 + i) * rx * 0.4, bpy = Math.cos(state.frame * 0.12 + i) * ry * 0.4; ctx.beginPath(); ctx.arc(bpx, bpy, 1.5, 0, Math.PI * 2); ctx.fill(); } } else { ctx.rotate(state.frame * 0.3 + p.id.length); ctx.fillStyle = '#1B5E20'; ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height); ctx.strokeStyle = '#ADFF2F'; ctx.lineWidth = 2; ctx.strokeRect(-p.width/2, -p.height/2, p.width, p.height); } ctx.restore(); } else if (p.isPoop) {
      ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(Math.atan2(p.vel.y, p.vel.x)); ctx.fillStyle = '#5D4037'; ctx.beginPath(); const tw = p.width, th = p.height; (ctx as any).roundRect(-tw/2, -th/2, tw, th, 10); ctx.fill(); ctx.strokeStyle = '#3E2723'; ctx.lineWidth = 2; ctx.stroke();
