export const speakAsBoss = (bossId: string, text: string, helpers: BossHelpers) => {
  if ('speechSynthesis' in window) {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    switch (bossId) {
      case 'Artie Avalanche': utterance.pitch = 1.6; utterance.rate = 0.85; break;
      case 'Victor Volcano': utterance.pitch = 0.7; utterance.rate = 0.85; break;
      case 'Ernie Earthquake': utterance.pitch = 0.1; utterance.rate = 0.55; break;
      case 'Hector Hurricane': utterance.pitch = 1.2; utterance.rate = 1.5; break;
      case 'Drug Trade Dale': utterance.pitch = 1.8; utterance.rate = 1.1; break;
      default: utterance.pitch = 1.0; utterance.rate = 1.0;
    }
    utterance.volume = 1.0;
    window.speechSynthesis.speak(utterance);
    helpers.setBossVulgarity(text, BOSS_VULGARITY_DURATION);
  }
};

export const checkIsWeakness = (stageId: string | null, currentWeapon: WeaponType, p?: Partial<Projectile>) => {
  if (!p) {
    if (stageId === 'Artie Avalanche' && currentWeapon === 'FLAMETHROWER') return true;
    if (stageId === 'Victor Volcano' && currentWeapon === 'TSUNAMI') return true;
    if (stageId === 'Ernie Earthquake' && currentWeapon === 'SHOTGUN') return true;
    if (stageId === 'Hector Hurricane' && currentWeapon === 'BOULDER') return true;
    if (stageId === 'Drug Trade Dale' && currentWeapon === 'SLUDGE') return true;
    return false;
  }
  if (stageId === 'Hector Hurricane' && p.isBoulder) return true;
  if (stageId === 'Victor Volcano' && p.isTsunami) return true;
  if (stageId === 'Artie Avalanche' && (p.owner === 'player' && currentWeapon === 'FLAMETHROWER')) return true;
  if (stageId === 'Ernie Earthquake' && p.isIce) return true;
  if (stageId === 'Drug Trade Dale' && p.isSludge) return true;
  return false;
};

export const getBossDamage = (boss: Enemy, stageId: string | null, currentWeapon: WeaponType, p?: Partial<Projectile>) => {
  if (stageId === 'Victor Volcano' && (p?.isTsunami || (!p && currentWeapon === 'TSUNAMI'))) return 150;

  if (currentWeapon === 'SLUDGE' || (p && p.isSludge)) {
    if (stageId === 'Drug Trade Dale') return 100;
    return 25;
  }

  const isWeak = checkIsWeakness(stageId, currentWeapon, p);
  if (isWeak) return 100;
  if (currentWeapon === 'TASER') return Math.floor(BULLET_DAMAGE * TASER_BOSS_DAMAGE_REDUCTION);
  return BULLET_DAMAGE;
};

export const triggerBossDeath = (boss: Enemy, playerFacing: number, wasWeakness: boolean, stageId: string | null, currentWeapon: WeaponType, state: any, helpers: BossHelpers) => {
  if (state.bossExplosionTimer > 0) return;
  const pos = { x: boss.pos.x + boss.width / 2, y: boss.pos.y + boss.height / 2 };
  if (stageId && BOSS_DIALOGUE.THRESHOLDS[stageId]) speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][0], helpers);
  state.bossVolcanoes = []; state.bossVolcanoTelegraphs = []; state.bossPoopTelegraphs = []; state.bossSteamExplosions = []; state.ernieVibrationTimer = 0; state.projectiles = []; state.tsunamiActive = false; state.tsunamiX = -1;
  if (wasWeakness) { state.bossExplosionTimer = 180; state.bossExplosionPos = pos; helpers.spawnDeathShower(state.bossExplosionPos, playerFacing, 35, true, 120); } else { helpers.spawnDeathShower(pos, playerFacing, 6, true, 45); helpers.onBossDeath(); state.victoryString = "V"; state.postVictoryTimer = 0; }
  state.player.killSatisfactionTimer = 0; state.player.bossKillSatisfactionTimer = 240; state.arenaLocked = false;
  let cat: VulgarityType = 'gun_kill'; if (currentWeapon === 'BOULDER') cat = 'boulder_kill'; else if (currentWeapon === 'SHOTGUN') cat = 'shotgun_kill'; else if (currentWeapon === 'FLAMETHROWER') cat = 'flamethrower_kill'; else if (currentWeapon === 'TSUNAMI') cat = 'tsunami_kill'; else if (currentWeapon === 'SLUDGE') cat = 'sludge_kill'; helpers.speakVulgarity(cat);
};

export const updateBossHazards = (state: any, player: Player, invincibilityEnabled: boolean, helpers: BossHelpers) => {
  // Update Volcanoes
  state.bossVolcanoes = state.bossVolcanoes.filter((v: Volcano) => { 
    v.life--; 
    if (state.frame % 12 === 0) { 
      const magVelX = v.type === 'wall' ? (v.pos.x < 7600 ? 9 : -9) : (Math.random()-0.5)*4;
      const magVelY = v.type === 'ground' ? -9 : (Math.random()-0.5)*7; 
      helpers.addProjectile({ 
        id: `magma-${Date.now()}`, pos: { x: v.pos.x, y: v.pos.y }, vel: { x: magVelX, y: magVelY }, 
        width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 45, owner: 'enemy' 
      }); 
    } 
    return v.life > 0; 
  });

  // Update Steam Explosions
  state.bossSteamExplosions = state.bossSteamExplosions.filter((exp: SteamExplosion) => { 
    exp.life--; 
    const pMidX = player.pos.x + player.width/2, pMidY = player.pos.y + player.height/2;
    const dx = pMidX - exp.pos.x, dy = pMidY - exp.pos.y; 
    if (dx*dx + dy*dy < exp.radius * exp.radius && player.invincibilityTimer <= 0 && !invincibilityEnabled) { 
      player.health -= 12; 
      if (player.health > 0) { 
        player.invincibilityTimer = 45; player.pushbackTimer = 20; 
        player.vel.x = dx > 0 ? 18 : -18; player.vel.y = -6; helpers.speakVulgarity('hurt'); 
      } 
    } 
    if (state.frame % 3 === 0) helpers.spawnSteamExplosionParticles(exp.pos, 6); 
    return exp.life > 0; 
  });

  // Update Poop Telegraphs
  state.bossPoopTelegraphs = state.bossPoopTelegraphs.filter((t: any) => { 
    t.life--; 
    if (t.life <= 0) { 
      const spawnLeft = t.spawnX === BOSS_DOOR_X; 
      const velX = spawnLeft ? 12 : -12; 
      helpers.addProjectile({ 
        id: `poop-${Date.now()}`, pos: { x: t.spawnX, y: t.pos.y }, vel: { x: velX, y: (Math.random()-0.5)*3 }, 
        width: 45, height: 25, health: 1, maxHealth: 1, type: 'projectile', damage: 12, owner: 'enemy', isPoop: true, spawnX: t.spawnX 
      }); 
      return false; 
    } 
    return true; 
  });
};

export const updateBossAI = (boss: Enemy, stageId: string | null, player: Player, currentWeapon: WeaponType, invincibilityEnabled: boolean, state: any, helpers: BossHelpers) => {
  boss.stateTimer = (boss.stateTimer || 0) - 1;
  const dirToPlayer = player.pos.x + player.width/2 < boss.pos.x + boss.width/2 ? -1 : 1;
  const healthPct = (boss.health / boss.maxHealth) * 100;

  if (stageId && BOSS_DIALOGUE.THRESHOLDS[stageId]) { 
    if (healthPct <= 75 && !boss.said75) { boss.said75 = true; speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][75], helpers); } 
    if (healthPct <= 50 && !boss.said50) { boss.said50 = true; speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][50], helpers); } 
    if (healthPct <= 25 && !boss.said25) { boss.said25 = true; speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][25], helpers); } 
  }

  if (stageId === 'Drug Trade Dale') handleDaleAI(boss, player, invincibilityEnabled, state, helpers); 
  else if (stageId === 'Hector Hurricane') handleHectorAI(boss, player, invincibilityEnabled, state, helpers); 
  else if (stageId === 'Artie Avalanche') handleArtieAI(boss, player, state, helpers); 
  else if (stageId === 'Ernie Earthquake') handleErnieAI(boss, player, state, helpers); 
  else if (stageId === 'Victor Volcano') handleVictorAI(boss, player, healthPct, state, helpers);

  if (boss.bossState !== 'stunned_drop' && stageId !== 'Drug Trade Dale') { 
    const gravityMult = (stageId === 'Artie Avalanche' || (stageId === 'Ernie Earthquake' && !boss.isGroundedBoss)) ? 0.5 : 1.0; 
    boss.vel.y += GRAVITY * gravityMult; boss.pos.x += boss.vel.x; const prevY = boss.pos.y; boss.pos.y += boss.vel.y; 
    boss.pos.x = Math.max(BOSS_DOOR_X + 10, Math.min(8000 - boss.width - 10, boss.pos.x)); 
    if (boss.pos.y < 100) { boss.pos.y = 100; boss.vel.y = 0; } 

    let bossGroundedOnBlock = false; 
    if (boss.vel.y >= 0) { 
      for (const b of state.blocks) { 
        if (b.type === 'platform' || b.type === 'ground') { 
          if (boss.pos.x < b.x + b.w && boss.pos.x + boss.width > b.x && prevY + boss.height <= b.y && boss.pos.y + boss.height >= b.y) { 
            boss.pos.y = b.y - boss.height; 
            if (stageId === 'Ernie Earthquake' && prevY < b.y - boss.height) { helpers.setScreenShake(30); helpers.setErnieVibration(ERNIE_STOMP_VIBRATION_DURATION); } 
            boss.vel.y = 0; boss.vel.x = 0; boss.isGroundedBoss = true; bossGroundedOnBlock = true; 
            if (boss.bossState === 'jumping' && stageId !== 'Victor Volcano' && stageId !== 'Hector Hurricane') boss.bossState = 'idle'; 
            break; 
          } 
        } 
      } 
    } 
    if (!bossGroundedOnBlock) { 
      if (boss.pos.y > 470) { 
        boss.pos.y = 470; 
        if (prevY < 470 && boss.vel.y > 0 && stageId === 'Ernie Earthquake') { 
          helpers.setScreenShake(30); helpers.setErnieVibration(ERNIE_STOMP_VIBRATION_DURATION); 
          helpers.addProjectile({ 
            id: `b-ernie-land-${Date.now()}`, pos: { x: boss.pos.x + boss.width/2, y: boss.pos.y + 20 }, vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, 
            width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true 
          }); 
        } 
        boss.vel.y = 0; boss.vel.x = 0; boss.isGroundedBoss = true; 
        if (boss.bossState === 'jumping' && stageId !== 'Victor Volcano' && stageId !== 'Hector Hurricane') boss.bossState = 'idle'; 
      } else boss.isGroundedBoss = false; 
    } 
  } else if (boss.bossState === 'stunned_drop') { 
    boss.vel.y += GRAVITY * 1.5; boss.pos.y += boss.vel.y; 
    if (boss.pos.y > 470) { boss.pos.y = 470; boss.vel.y = 0; boss.isGroundedBoss = true; if (boss.stateTimer! > 30) boss.stateTimer = 30; } 
  }
};

const handleDaleAI = (boss: Enemy, player: Player, invincibilityEnabled: boolean, state: any, helpers: BossHelpers) => {
  if (boss.bossState === 'idle' && boss.stateTimer! <= 0) { 
    boss.bossState = 'truck_incoming'; boss.stateTimer = 120; boss.truckX = BOSS_DOOR_X - 600; boss.truckActive = false; helpers.playGunSound('horn'); 
  } else if (boss.bossState === 'truck_incoming') { 
    if (boss.stateTimer! < 40) { boss.truckActive = true; boss.truckX! += DALE_TRUCK_SPEED; } 
    const tx = boss.truckX!, ty = 400, tw = 350, th = 150; 
    if (boss.truckActive && player.pos.x < tx + tw && player.pos.x + player.width > tx && player.pos.y < ty + th && player.pos.y + player.height > ty && player.invincibilityTimer <= 0 && !invincibilityEnabled) { 
      player.health -= DALE_TRUCK_DAMAGE; player.invincibilityTimer = 60; player.pushbackTimer = 40; player.vel = DALE_PUSHBACK_VEL; helpers.speakVulgarity('hurt'); 
    } 
    state.projectiles.forEach((p: Projectile) => { 
      if (boss.truckActive && p.isMethBarrel && p.health > 0) { 
        if (p.pos.x < tx + tw && p.pos.x + p.width > tx && p.pos.y < ty + th && p.pos.y + p.height > ty) p.health = -1; 
      } 
    }); 
    if (boss.truckX! > 8200) { 
      boss.truckActive = false; boss.bossState = 'using_shipment'; 
      const drugs: ('cocaine' | 'speed' | 'meth')[] = ['cocaine', 'speed', 'meth']; 
      boss.shipmentType = drugs[Math.floor(Math.random() * drugs.length)]; 
      boss.shipmentCount = boss.shipmentType === 'cocaine' ? 10 : (boss.shipmentType === 'meth' ? 5 : 1); 
      boss.stateTimer = 30; 
    } 
  } else if (boss.bossState === 'using_shipment') { 
    if (boss.stateTimer! <= 0) { 
      if (boss.shipmentType === 'cocaine') { 
        const rangeRoll = Math.random(); 
        let vx, vy; 
        if (rangeRoll < 0.3) { vx = -2 - Math.random() * 3; vy = -18 - Math.random() * 6; } 
        else if (rangeRoll < 0.75) { vx = -10 - Math.random() * 5; vy = -14 - Math.random() * 5; } 
        else { vx = -20 - Math.random() * 8; vy = -8 - Math.random() * 4; } 
        helpers.addProjectile({ 
          id: `coke-${Date.now()}`, pos: { x: boss.pos.x, y: boss.pos.y + 20 }, vel: { x: vx, y: vy }, 
          width: 25, height: 25, health: 1, maxHealth: 1, type: 'projectile', damage: 30, owner: 'enemy', isCocaine: true 
        }); 
        boss.shipmentCount!--; boss.stateTimer = 20; 
        if (boss.shipmentCount! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 80; } 
      } else if (boss.shipmentType === 'meth') { 
        helpers.addProjectile({ 
          id: `meth-${Date.now()}`, pos: { x: boss.pos.x, y: boss.pos.y }, vel: { x: -4 - Math.random() * 3, y: -12 }, 
          width: 40, height: 50, health: 100, maxHealth: 100, type: 'projectile', damage: METH_BARREL_DAMAGE, owner: 'enemy', isMethBarrel: true, bounces: 15 
        }); 
        boss.shipmentCount!--; boss.stateTimer = 45; 
        if (boss.shipmentCount! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 100; } 
      } else if (boss.shipmentType === 'speed') { 
        boss.bossState = 'speed_dash'; boss.dashCount = 8; boss.vel.x = -25; boss.stateTimer = 0; helpers.playGunSound('ice'); 
      } 
    } 
  } else if (boss.bossState === 'speed_dash') { 
    boss.pos.x += boss.vel.x; 
    if (boss.pos.x < BOSS_DOOR_X + 20 || boss.pos.x + boss.width > 7980) { 
      boss.vel.x *= -1; boss.dashCount!--; helpers.setScreenShake(10); 
      if (boss.dashCount! <= 0) { boss.pos.x = 7840; boss.vel.x = 0; boss.bossState = 'idle'; boss.stateTimer = 150; } 
    } 
  }
};

const handleHectorAI = (boss: Enemy, player: Player, invincibilityEnabled: boolean, state: any, helpers: BossHelpers) => {
  if (boss.bossState === 'hurricane') { 
    const forceDir = (boss.pos.x + boss.width/2 - (player.pos.x + player.width/2)) > 0 ? 1 : -1; 
    state.totalPullForceX += forceDir * HECTOR_PULL_STRENGTH_ULT; 
    state.projectiles.forEach((p: Projectile) => { 
      if (p.owner === 'player' && p.isBoulder) { 
        const pullDir = (boss.pos.x + boss.width/2 - (p.pos.x + p.width/2)) > 0 ? 1 : -1; 
        p.vel.x += pullDir * 1.5; 
      } 
      if (p.isPoop) {
        p.vel.x += forceDir * HECTOR_PULL_STRENGTH; 
        const dx = (p.pos.x + p.width/2) - (boss.pos.x + boss.width/2);
        const dy = (p.pos.y + p.height/2) - (boss.pos.y + boss.height/2);
        if (Math.sqrt(dx*dx + dy*dy) < 180) { p.health = 0; helpers.spawnPoopExplosion(p.pos, 15); }
      }
    }); 
    if (state.frame % 90 === 0) { 
      const spawnLeft = forceDir > 0, spawnX = spawnLeft ? BOSS_DOOR_X : 8000; 
      const r = Math.random(); 
      let spawnY = r < 0.33 ? 510 : (r < 0.66 ? 498 : 440); 
      helpers.addPoopTelegraph({ pos: { x: spawnX, y: spawnY }, life: 60, spawnX: spawnX }); 
    } 
    if (Math.abs((boss.pos.x + boss.width/2) - (player.pos.x + player.width/2)) < 300 && player.invincibilityTimer <= 0 && !invincibilityEnabled) { 
      player.health -= 4; if (player.health > 0) { player.invincibilityTimer = 25; player.pushbackTimer = 2; helpers.speakVulgarity('hurt'); } 
    } 
    if (boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; helpers.clearPoopTelegraphs(); } 
  } else if (boss.bossState === 'jumping') { 
    if (boss.isGroundedBoss) { boss.bossState = 'hurricane'; boss.stateTimer = 300; boss.vel.x = 0; } 
  } else if (boss.stateTimer! <= 0) { 
    boss.bossState = 'jumping'; boss.vel.y = -22 - Math.random() * 4; 
    const targetX = boss.pos.x > 7600 ? 7300 : 7900; boss.vel.x = (targetX - boss.pos.x) * 0.035; 
  }
};

const handleArtieAI = (boss: Enemy, player: Player, state: any, helpers: BossHelpers) => {
  if (boss.shootTimer > 0) boss.shootTimer--; 
  if (boss.isGroundedBoss && Math.abs(boss.vel.x) < 0.5) boss.sideTimer = (boss.sideTimer || 0) + 1; else boss.sideTimer = 0; 
  if ((boss.stateTimer! <= 0 || (boss.sideTimer || 0) > 175) && boss.isGroundedBoss) { 
    const r = Math.random(); const mustMove = (boss.sideTimer || 0) > 120; 
    if (r < 0.35 || (mustMove && r < 0.6)) { 
      boss.vel.y = -13 - Math.random() * 3; boss.vel.x = (player.pos.x < boss.pos.x ? -1 : 1) * (4 + Math.random() * 2); 
      boss.stateTimer = 70; boss.bossState = 'jumping'; boss.sideTimer = 0; 
    } else if (r < 0.70 && boss.shootTimer <= 0 && !mustMove) { 
      const targetDir = player.pos.x < (boss.pos.x + boss.width/2) ? -1 : 1, projW = 60; 
      helpers.addProjectile({ 
        id: `ice-big-${Date.now()}`, pos: { x: targetDir === 1 ? boss.pos.x + boss.width + 5 : boss.pos.x - projW - 5, y: boss.pos.y + 10 }, vel: { x: targetDir * 11, y: 0 }, 
        width: projW, height: 60, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isIce: true 
      }); 
      boss.shootTimer = 60; boss.stateTimer = 80; boss.bossState = 'attacking'; 
    } else { 
      boss.vel.x = (player.pos.x + player.width/2 < boss.pos.x + boss.width/2 ? -1 : 1) * 7.5; 
      boss.stateTimer = 65; boss.bossState = 'attacking'; boss.sideTimer = 0; 
    } 
  } 
  if (boss.bossState === 'jumping' && !boss.isGroundedBoss && boss.shootTimer <= 0) { 
    if (Math.abs(boss.vel.y) < 2 && boss.stateTimer! > 20 && Math.random() < 0.08) { 
      const targetDir = player.pos.x < (boss.pos.x + boss.width/2) ? -1 : 1, projW = 60; 
      helpers.addProjectile({ 
        id: `ice-big-air-${Date.now()}`, pos: { x: targetDir === 1 ? boss.pos.x + boss.width + 5 : boss.pos.x - projW - 5, y: boss.pos.y + 10 }, vel: { x: targetDir * 11, y: 0 }, 
        width: projW, height: 60, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isIce: true 
      }); 
      boss.shootTimer = 60; boss.stateTimer = 50; 
    } 
  } 
  if (boss.isGroundedBoss) boss.vel.x *= 0.95;
};

export const handleErnieAI = (boss: Enemy, player: Player, state: any, helpers: BossHelpers) => {
  if (boss.bossState === 'stunned_drop') { 
    if (boss.isGroundedBoss && boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; boss.rotation = 0; } 
  } else if (boss.stateTimer! <= 0) { 
    const dirToPlayer = player.pos.x + player.width/2 < boss.pos.x + boss.width/2 ? -1 : 1; 
    boss.vel.y = -12; boss.vel.x = (player.pos.x - boss.pos.x) * 0.03; boss.stateTimer = 180; 
    helpers.addProjectile({ 
      id: `b-ernie-jump-${Date.now()}`, pos: { x: boss.pos.x + boss.width/2, y: boss.pos.y + 20 }, vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, 
      width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true 
    }); 
  }
};

const handleVictorAI = (boss: Enemy, player: Player, healthPct: number, state: any, helpers: BossHelpers) => {
  const victorMidX = boss.pos.x + boss.width / 2;
  if (boss.bossState === 'attacking') { 
    boss.vel.x = 0; 
    if (state.bossVolcanoes.length === 0 && boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; } 
  } else if (boss.bossState === 'telegraphing') { 
    boss.vel.x = 0; 
    if (boss.stateTimer! <= 0) { 
      boss.bossState = 'attacking'; boss.stateTimer = 180; 
      state.bossVolcanoTelegraphs.forEach((t: Volcano) => helpers.addVolcano({ pos: t.pos, life: 180, type: t.type })); 
      helpers.clearVolcanoTelegraphs(); 
    } 
  } else if (boss.bossState === 'jumping') { 
    if (boss.isGroundedBoss) { 
      boss.bossState = 'telegraphing'; boss.stateTimer = 60; helpers.clearVolcanoTelegraphs(); 
      const newSide = (state.victorWallSide + 1) % 2; helpers.setVictorWallSide(newSide); 
      helpers.addVolcanoTelegraph({ pos: { x: newSide === 0 ? BOSS_DOOR_X : 8000, y: 250 + Math.random() * 200 }, life: 60, type: 'wall' }); 
      const groundCount = healthPct > 50 ? 1 : 2; 
      for(let i=0; i<groundCount; i++) { 
        let tx = BOSS_DOOR_X + 150 + Math.random() * 500; 
        helpers.addVolcanoTelegraph({ pos: { x: Math.max(BOSS_DOOR_X + 50, Math.min(7900, tx)), y: 550 }, life: 60, type: 'ground' }); 
      } 
    } 
  } else if (boss.stateTimer! <= 0) { 
    boss.vel.y = -20 - Math.random() * 5; 
    const platforms = state.blocks.filter((b: any) => b.type === 'platform' && b.x > BOSS_DOOR_X); 
    if (platforms.length > 0) { 
      const targetPlate = platforms[Math.floor(Math.random() * platforms.length)]; 
      boss.vel.x = (targetPlate.x + targetPlate.w / 2 - victorMidX) * 0.04; 
    } else { boss.vel.x = (player.pos.x < boss.pos.x ? -1 : 1) * 4; } 
    boss.bossState = 'jumping'; boss.stateTimer = 60; 
  } 
  if (boss.isGroundedBoss) boss.vel.x *= 0.95;
};

export const drawBoss = (ctx: CanvasRenderingContext2D, e: Enemy, id: string | null, frame: number) => {
  const { pos, width, height } = e; ctx.save(); ctx.translate(pos.x, pos.y);
  const shouldSpin = e.rotation && !(id === 'Hector Hurricane' && e.bossState === 'hurricane');
  if (shouldSpin) { ctx.translate(width / 2, height / 2); ctx.rotate(e.rotation!); ctx.translate(-width / 2, -height / 2); }
  if (id === 'Drug Trade Dale' && e.bossState === 'speed_dash') ctx.filter = `hue-rotate(${frame * 10}deg) saturate(3)`;
  switch (id) {
    case 'Artie Avalanche': ctx.fillStyle = '#AED6F1'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.fillStyle = '#FF8A80'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); ctx.fillStyle = '#2E86C1'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, Math.PI, 0); ctx.fill(); ctx.stroke(); break;
    case 'Victor Volcano': ctx.fillStyle = '#BA4A00'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); const lOff = (e.bossState === 'attacking' || e.bossState === 'telegraphing') ? Math.sin(frame * 0.5) * 6 : 0; ctx.fillStyle = '#C62828'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3 + lOff, width * 0.3, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); ctx.fillStyle = '#FF4500'; ctx.fillRect(width * 0.2, height * 0.2 + lOff, width * 0.6, height * 0.1); break;
    case 'Ernie Earthquake': ctx.fillStyle = '#6E2C00'; ctx.fillRect(0, height * 0.3, width, height * 0.7); ctx.strokeRect(0, height * 0.3, width, height * 0.7); ctx.fillStyle = '#FF5252'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); break;
    case 'Hector Hurricane': 
      if (e.bossState === 'hurricane') {
         ctx.save(); ctx.lineWidth = 3; ctx.shadowBlur = 15; ctx.shadowColor = '#00E5FF';
         for(let i=0; i<3; i++) if ((frame + i * 20) % 30 < 5) {
             ctx.strokeStyle = i % 2 === 0 ? '#FFFFFF' : '#00E5FF'; ctx.beginPath(); ctx.moveTo(width/2, height/2); let curX = width/2, curY = height/2;
             for(let j=0; j<6; j++) { curX += (Math.random()-0.5) * 80; curY += (Math.random()-0.5) * 80; ctx.lineTo(curX, curY); }
             ctx.stroke();
         }
         ctx.globalAlpha = 0.5; ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
         for(let i=0; i<8; i++){
            const arcR = width * (1.2 + Math.sin(frame * 0.1 + i) * 0.3); const startA = frame * 0.15 + i * (Math.PI/4);
            ctx.beginPath(); ctx.arc(width/2, height/2, arcR, startA, startA + 0.6); ctx.stroke();
         }
         ctx.restore();
      }
      ctx.fillStyle = '#16A085'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.strokeRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.fillStyle = '#FF8A80'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); break;
    case 'Drug Trade Dale': ctx.fillStyle = '#2C3E50'; ctx.fillRect(0, 0, width, height); ctx.strokeRect(0, 0, width, height); ctx.fillStyle = '#8E44AD'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); ctx.fillStyle = 'gold'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.25, width * 0.2, 0, Math.PI * 2); ctx.fill(); if (e.bossState === 'using_shipment') { ctx.fillStyle = '#fff'; ctx.fillRect(width * 0.1, -20, width * 0.8, 20); } break;
    case 'Toxic Tommy': ctx.fillStyle = '#27AE60'; ctx.fillRect(0, 0, width, height); ctx.strokeRect(0, 0, width, height); ctx.fillStyle = '#ADFF2F'; ctx.fillRect(width * 0.1, height * 0.1, width * 0.8, height * 0.3); ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(width * 0.3, height * 0.25, 4, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(width * 0.7, height * 0.25, 4, 0, Math.PI * 2); ctx.fill(); break;
    default: ctx.fillStyle = 'yellow'; ctx.fillRect(0, 0, width, height); break;
  }
  ctx.restore();
};

export const drawDaleDrugs = (ctx: CanvasRenderingContext2D, e: Enemy) => {
  if (e.bossState === 'using_shipment' && e.shipmentCount! > 0) { const stackX = e.pos.x - 60, groundY = 550; ctx.save(); for (let i = 0; i < e.shipmentCount!; i++) { const row = Math.floor(i / 2), col = i % 2; if (e.shipmentType === 'cocaine') { ctx.fillStyle = '#fff'; ctx.strokeStyle = '#ccc'; ctx.lineWidth = 1; const bx = stackX + (col * 20) + (row * 3), by = groundY - (row * 15) - 20; ctx.fillRect(bx, by, 18, 18); ctx.strokeRect(bx, by, 18, 18); } else if (e.shipmentType === 'meth') { ctx.fillStyle = '#111'; ctx.strokeStyle = '#FFD700'; ctx.lineWidth = 2; const bx = stackX + (col * 30) - 10, by = groundY - (row * 35) - 40; ctx.fillRect(bx, by, 30, 40); ctx.strokeRect(bx, by, 30, 40); ctx.fillStyle = '#FFD700'; ctx.font = '8px "Press Start 2P"'; ctx.textAlign = 'center'; ctx.fillText("METH", bx + 15, by + 25); } else if (e.shipmentType === 'speed' && e.stateTimer! > 0) { const bx = stackX, by = groundY - 20; ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(bx + 5, by, 15, 4); ctx.fillStyle = 'red'; ctx.fillRect(bx, by - 2, 6, 8); } } ctx.restore(); }
};

