  BOULDER_SHRAPNEL_COUNT, HEALTH_PICKUP_SMALL, HEALTH_PICKUP_LARGE, BOULDER_SHRAPNEL_DAMAGE, 
  ENEMY_HIT_COOLDOWN, NEEDLE_DOT_TICK_RATE, NEEDLE_DOT_DAMAGE_PER_STACK, NEEDLE_OVERDOSE_THRESHOLD,
  PLAYER_PUSHBACK_VEL_X, PLAYER_PUSHBACK_VEL_Y, PLAYER_STUN_DURATION, FRICTION_DEFAULT, 
  FRICTION_ICE_STAGE, FRICTION_ICE_STOP, FILTH_SHIELD_CONTACT_DAMAGE
} from '../constants';
