interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, specialCharges: number, specialChargeTimer: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => void;
  onBossEncounter: () => void;
  onBossTransition: () => void;
  onBossDefeated: (stageId: string) => void;
  onBossDeath: () => void;
  onBossSelect: () => void;
  onGameOver: (victory: boolean) => void;
  onIntroComplete: () => void;
  onTogglePause: () => void;
  currentWeapon: WeaponType;
  initialAmmo: Record<WeaponType, number>;
  invincibilityEnabled: boolean;
  infiniteAmmoEnabled: boolean;
  infinitePowerEnabled: boolean;
  jumpToBossEnabled: boolean;
  bossTauntText: string;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, 
  onBossDefeated, onBossDeath, onBossSelect, onGameOver, onIntroComplete, onTogglePause, 
  currentWeapon, initialAmmo, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled,
  bossTauntText
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player', pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, width: 44, height: 64,
      health: INITIAL_PLAYER_HEALTH, maxHealth: INITIAL_PLAYER_HEALTH, type: 'player',
      isCharging: false, isUppercutting: false, isDucking: false,
      specialCharges: MAX_SPECIAL_CHARGES, specialChargeTimer: 0, chargeDuration: 0,
      isJumping: false, isGrounded: false, facing: 1, shootCooldown: 0,
      jumpPrepTimer: 0, landTimer: 0, invincibilityTimer: 0, pushbackTimer: 0,
      killSatisfactionTimer: 0, bossKillSatisfactionTimer: 0, hasUsedAirMove: false,
      jumpInputReleased: true, chargeInputReleased: true, currentWeapon: 'GUN',
      availableWeapons: ['GUN'], weaponAmmo: { ...initialAmmo }, isTasing: false,
      taserTargetId: null, taserTimer: 0, flameTimer: 0, flameAngle: 0, filthShieldTimer: 0, barfTimer: 0
    } as Player & { killSatisfactionTimer: number, bossKillSatisfactionTimer: number },
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as (Particle & { isWater?: boolean })[],
    damageNumbers: [] as DamageNumber[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    bossSpawned: false, arenaLocked: false, doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0, playerLastVulgarity: "", playerVulgarityTimer: 0,
    bossLastVulgarity: "", bossVulgarityTimer: 0, voiceLineCooldown: 0,
    victoryString: "", deathString: "", deathTimer: 0, postVictoryTimer: 0,
    introTimer: 0, bossExplosionTimer: 0, bossExplosionPos: { x: 0, y: 0 },
    tsunamiX: -1, tsunamiStartX: 0, tsunamiActive: false, tsunamiDir: 1,
    bossVolcanoes: [] as Volcano[], bossVolcanoTelegraphs: [] as Volcano[],
    bossPoopTelegraphs: [] as { pos: Vector2, life: number, spawnX: number }[],
    bossSteamExplosions: [] as SteamExplosion[], bossTsunamiSide: 0, bossTsunamiTimer: 0,
    victorWallSide: 0, ernieVibrationTimer: 0, playerStunTimer: 0, screenShakeTimer: 0,
    shouldSyncWeapon: false, totalPullForceX: 0, stageId: stageId
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  useEffect(() => { gameStateRef.current.player.currentWeapon = currentWeapon; }, [currentWeapon]);
  useEffect(() => { gameStateRef.current.stageId = stageId; }, [stageId]);
  useEffect(() => { if (gameStateRef.current.deathTimer <= 0) gameStateRef.current.player.weaponAmmo = { ...initialAmmo }; }, [initialAmmo]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { const k = e.key.toLowerCase(); keys.current[k] = true; keys.current[e.code.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { const k = e.key.toLowerCase(); keys.current[k] = false; keys.current[e.code.toLowerCase()] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', () => mouse.current.down = true); window.addEventListener('mouseup', () => mouse.current.down = false);
    return () => {
      window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp);
      if (audioCtxRef.current) audioCtxRef.current.close();
    };
  }, []);

  const spawnDamageNumber = useCallback((pos: Vector2, value: number, isCritical: boolean = false) => {
    gameStateRef.current.damageNumbers.push({ id: `dmg-${Date.now()}-${Math.random()}`, value: Math.floor(value), pos: { ...pos }, vel: { x: (Math.random()-0.5)*4, y: -4-Math.random()*2 }, life: 45, maxLife: 45, isCritical });
  }, []);

  const spawnExplosion = useCallback((pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15, isGlass: boolean = false, isBossGore: boolean = false) => {
    const s = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      if (s.particles.length > 2500) break;
      s.particles.push({ pos: { ...pos }, vel: { x: baseVelX+(Math.random()-0.5)*spread, y: (Math.random()-0.5)*spread }, life: isGlass ? 150+Math.random()*200 : (isBossGore ? 180+Math.random()*120 : 20+Math.random()*80), color, size: i%3===0 ? 1+Math.random()*4 : 2+Math.random()*12, isGlass, isBossGore });
    }
  }, []);

  const spawnDeathShower = useCallback((pos: Vector2, facing: number = 0, mult: number = 1, isBossDeath: boolean = false, spreadOverride?: number) => {
    const spread = spreadOverride ?? (isBossDeath ? 45 : 35);
    PARTICLE_PALETTES.FLESH.forEach(c => spawnExplosion(pos, c, Math.ceil(8*mult), facing*18, spread, false, isBossDeath));
    PARTICLE_PALETTES.GORE.forEach(c => spawnExplosion(pos, c, Math.ceil(12*mult), facing*22, spread+10, false, isBossDeath));
  }, [spawnExplosion]);

  const speakVulgarity = useCallback((category: VulgarityType) => {
    const state = gameStateRef.current; if (!('speechSynthesis' in window) || window.speechSynthesis.speaking || state.voiceLineCooldown > 0) return;
    let pool = VULGARITIES[category as keyof typeof VULGARITIES] || VULGARITIES.GUN_KILL;
    const text = pool[Math.floor(Math.random() * pool.length)];
    state.playerLastVulgarity = text; state.playerVulgarityTimer = VULGARITY_TEXT_DURATION;
    const utterance = new SpeechSynthesisUtterance(text); utterance.pitch = 0.1; utterance.rate = 1.2;
    utterance.onend = () => { state.voiceLineCooldown = VOICE_LINE_COOLDOWN_FRAMES; };
    window.speechSynthesis.speak(utterance);
  }, []);

  const playGunSound = useCallback((type: string = 'gun') => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current; if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator(); const gain = ctx.createGain();
      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(150, ctx.currentTime);
      gain.gain.setValueAtTime(0.05, ctx.currentTime); osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  }, []);

  const spawnPickup = useCallback((pos: Vector2) => {
    if (Math.random() > 0.6) return;
    const pr = Math.random(); const type: PickupType = pr < 0.25 ? 'small_health' : (pr < 0.35 ? 'large_health' : (pr < 0.8 ? 'small_ammo' : 'large_ammo'));
    gameStateRef.current.pickups.push({ id: `p-${Date.now()}`, pos: { ...pos }, vel: { x: (Math.random()-0.5)*4, y: -5 }, width: 20, height: 20, type, life: 600 });
  }, []);

  const createLevel = useCallback(() => {
    const s = gameStateRef.current; s.arenaLocked = false; s.doorState = 'closed'; s.doorOpenAmount = 0; s.enemies = []; s.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, { x: 8000, y: -1000, w: 100, h: 2000, type: 'wall' }, { x: 0, y: 550, w: 8000, h: 50, type: 'ground' }, { x: BOSS_DOOR_X, y: 400, w: DOOR_WIDTH, h: 150, type: 'door' }, { x: BOSS_DOOR_X, y: -1000, w: DOOR_WIDTH, h: 1400, type: 'wall' }
    ];
    if (!jumpToBossEnabled) for (let i = 1200; i < BOSS_DOOR_X - 300; i += 1000) s.enemies.push({ id: `e-${i}`, pos: { x: i, y: 480 }, vel: { x: 0, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 0, initialX: i, shootTimer: 0 });
    s.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 666, maxHealth: 666, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0, bossState: 'idle', stateTimer: 60 });
  }, [jumpToBossEnabled]);

  const bossHelpers: BossLogic.BossHelpers = {
    spawnDamageNumber, spawnDeathShower, onBossDeath, speakVulgarity, playGunSound, spawnExplosion,
    spawnSteamExplosionParticles: (p) => spawnExplosion(p, '#FFF', 20),
    spawnPoopExplosion: (p) => spawnExplosion(p, '#5D4037', 15),
    spawnPowderExplosion: (p) => spawnExplosion(p, '#FFF', 20),
    spawnMethExplosion: (p) => spawnExplosion(p, '#00E5FF', 30),
    spawnGlassShatter: (p) => spawnExplosion(p, '#ADD8E6', 10, 0, 15, true),
    setBossVulgarity: (t, d) => { gameStateRef.current.bossLastVulgarity = t; gameStateRef.current.bossVulgarityTimer = d; },
    setScreenShake: (d) => { gameStateRef.current.screenShakeTimer = d; },
    setErnieVibration: (d) => { gameStateRef.current.ernieVibrationTimer = d; },
    setPlayerStun: (d) => { gameStateRef.current.playerStunTimer = d; },
    addProjectile: (p) => gameStateRef.current.projectiles.push(p),
    addVolcano: (v) => gameStateRef.current.bossVolcanoes.push(v),
    clearVolcanoes: () => gameStateRef.current.bossVolcanoes = [],
    addVolcanoTelegraph: (v) => gameStateRef.current.bossVolcanoTelegraphs.push(v),
    clearVolcanoTelegraphs: () => gameStateRef.current.bossVolcanoTelegraphs = [],
    addPoopTelegraph: (t) => gameStateRef.current.bossPoopTelegraphs.push(t),
    clearPoopTelegraphs: () => gameStateRef.current.bossPoopTelegraphs = [],
    setVictorWallSide: (s) => gameStateRef.current.victorWallSide = s,
    setTsunamiActive: (a) => gameStateRef.current.tsunamiActive = a
  };

  const weaponHelpers: WeaponLogic.WeaponHelpers = {
    ...bossHelpers, addParticle: (p) => gameStateRef.current.particles.push(p),
    triggerBossDeath: (b, f, w) => BossLogic.triggerBossDeath(b, f, w, stageId, currentWeapon, gameStateRef.current, bossHelpers),
    spawnPickup,
  };

  const update = useCallback(() => {
    const s = gameStateRef.current; const { player, enemies, projectiles, blocks } = s;
    s.frame++;
    if (s.screenShakeTimer > 0) s.screenShakeTimer--;
    if (s.deathTimer > 0) { s.deathTimer--; if (s.deathTimer === 0) { player.health = 100; player.pos = { x: 150, y: 100 }; createLevel(); } return; }
    if (status !== GameStatus.PLAYING) return;

    // Process Inputs
    const km = keys.current;
    const moveLeft = km['a'] || km['arrowleft']; const moveRight = km['d'] || km['arrowright'];
    const moveUp = km['w'] || km['arrowup']; const moveDown = km['s'] || km['arrowdown'];
    const jumpRequested = km[' '] || km['z'] || km['j']; const chargeRequested = km['shift'] || km['c'];
    const shootRequested = mouse.current.down;

    // Movement Physics
    if (player.pushbackTimer > 0) player.pushbackTimer--;
    if (!player.isCharging && !player.isUppercutting && player.pushbackTimer <= 0) {
      const speed = player.isDucking ? 0 : PLAYER_SPEED;
      if (moveLeft) { player.vel.x = -speed; player.facing = -1; } 
      else if (moveRight) { player.vel.x = speed; player.facing = 1; } 
      else player.vel.x = 0;
    }

    // Weapons & Boss Hazards
    WeaponLogic.updateAllWeaponry(s, player, shootRequested, infiniteAmmoEnabled, weaponHelpers);
    BossLogic.updateBossHazards(s, player, invincibilityEnabled, bossHelpers);

    // Collision & Jump Logic
    player.vel.y += GRAVITY; player.pos.x += player.vel.x + s.totalPullForceX; player.pos.y += player.vel.y;
    s.totalPullForceX = 0;

    // Blocks
    player.isGrounded = false;
    blocks.forEach(b => {
      if (player.pos.x < b.x + b.w && player.pos.x + player.width > b.x && player.pos.y < b.y + b.h && player.pos.y + player.height > b.y) {
        const overlapY = Math.min(player.pos.y + player.height - b.y, b.y + b.h - player.pos.y);
        if (overlapY < 15) { player.pos.y = b.y - player.height; player.vel.y = 0; player.isGrounded = true; }
      }
    });

    if (jumpRequested && player.isGrounded) player.vel.y = PLAYER_JUMP_FORCE;

    // Special Moves
    if (chargeRequested && player.specialCharges > 0 && !player.isCharging) {
      player.specialCharges--;
      if (moveUp) { player.isUppercutting = true; player.vel.y = UPPERCUT_FORCE; player.chargeDuration = 30; }
      else { player.isCharging = true; player.chargeDuration = 30; }
    }
    if (player.chargeDuration > 0) { 
      player.chargeDuration--; 
      if (player.isCharging) player.vel.x = player.facing * CHARGE_SPEED;
      if (player.chargeDuration <= 0) { player.isCharging = false; player.isUppercutting = false; }
    }

    // Entities
    s.enemies = enemies.filter(e => {
      if (e.health <= 0) return false;
      if (e.type === 'boss' && s.arenaLocked) BossLogic.updateBossAI(e, stageId, player, currentWeapon, invincibilityEnabled, s, bossHelpers);
      else { e.shootTimer++; e.pos.x += e.vel.x; }
      return true;
    });

    s.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x; p.pos.y += p.vel.y;
      return p.pos.x > s.camera.x - 100 && p.pos.x < s.camera.x + 900;
    });

    if (player.health <= 0 && s.deathTimer <= 0) s.deathTimer = 180;
    onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer, player.weaponAmmo);
  }, [status, stageId, currentWeapon, infiniteAmmoEnabled, invincibilityEnabled, onPlayerUpdate, createLevel]);

  const draw = useCallback(() => {
    const ctx = canvasRef.current?.getContext('2d'); if (!ctx) return;
    const s = gameStateRef.current; ctx.fillStyle = '#111'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save(); ctx.translate(-s.camera.x, 0);
    s.blocks.forEach(b => { ctx.fillStyle = '#555'; ctx.fillRect(b.x, b.y, b.w, b.h); });
    s.enemies.forEach(e => { if (e.type === 'boss') BossLogic.drawBoss(ctx, e, stageId, s.frame); else { ctx.fillStyle = 'red'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); } });
    s.projectiles.forEach(p => { ctx.fillStyle = 'yellow'; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    s.particles.forEach(p => { ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    if (s.deathTimer <= 0) { ctx.fillStyle = 'orange'; ctx.fillRect(s.player.pos.x, s.player.pos.y, s.player.width, s.player.height); }
    ctx.restore();
  }, [stageId]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = requestAnimationFrame(loop); };
    if (status === GameStatus.PLAYING) frameId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(frameId);
  }, [status, update, draw]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

