} from './types';
import { 
  BULLET_DAMAGE, BOULDER_DAMAGE, BOULDER_SPEED, SHOTGUN_DAMAGE, 
  SHOTGUN_COOLDOWN, SHOTGUN_FREEZE_TIME, FLAMETHROWER_DAMAGE, 
  FLAMETHROWER_RANGE, FLAMETHROWER_MAX_RANGE, FLAMETHROWER_RAMP_FRAMES,
  TSUNAMI_COOLDOWN, COLORS, PARTICLE_PALETTES,
  MAX_AMMO, TASER_RANGE, CANVAS_WIDTH, GUN_COOLDOWN, GUN_VELOCITY,
  BOULDER_COOLDOWN, SHOTGUN_PELLET_COUNT, NEEDLE_DAMAGE, NEEDLE_COOLDOWN,
  SLUDGE_DAMAGE, SLUDGE_COOLDOWN, FILTH_SHIELD_DURATION, TSUNAMI_WAVE_SPEED,
  TASER_AMMO_CONSUMPTION_RATE, TASER_TICK_RATE, TASER_DOT_DAMAGE, TASER_FIRE_THRESHOLD,
  FIRE_TICK_RATE, FIRE_DOT_DAMAGE_HEAVY, SLUDGE_PROJ_SIZE_MIN, SLUDGE_PROJ_SIZE_RAND,
  TSUNAMI_DAMAGE_BOSS, TSUNAMI_DAMAGE_WEAKNESS, ENEMY_HIT_COOLDOWN, NEEDLE_DOT_TICK_RATE,
  NEEDLE_DOT_DAMAGE_PER_STACK, NEEDLE_OVERDOSE_THRESHOLD, BOULDER_BOUNCE_DAMPING,
  BOULDER_SHRAPNEL_COUNT, BOULDER_SHRAPNEL_DAMAGE, GRAVITY, SLUDGE_DOT_TICK,
  SLUDGE_LINGER_DURATION, SLUDGE_POOL_W_MIN, SLUDGE_POOL_W_RAND, SLUDGE_POOL_H_MIN,
  SLUDGE_POOL_H_RAND, SLUDGE_BUBBLE_SIZE_MIN, SLUDGE_BUBBLE_SIZE_RAND
} from './constants';
