export interface WeaponHelpers {
  addProjectile: (p: Projectile) => void;
  addParticle: (p: Particle) => void;
  playGunSound: (type: 'gun' | 'ice' | 'flame' | 'tsunami' | 'dart' | 'horn' | 'ignite' | 'barf') => void;
  spawnExplosion: (pos: Vec2, color: string, count: number, baseVelX?: number, spread?: number) => void;
  spawnDamageNumber: (pos: Vec2, value: number, isCritical?: boolean) => void;
  spawnGlassShatter: (pos: Vec2) => void;
  setScreenShake: (duration: number) => void;
  triggerBossDeath: (boss: Enemy, facing: number, wasWeakness: boolean) => void;
  speakVulgarity: (category: any) => void;
  spawnPickup: (pos: Vector2) => void;
  spawnDeathShower: (pos: Vector2, facing: number) => void;
}

export const updateAllWeaponry = (state: any, player: Player, shootRequested: boolean, infiniteAmmoEnabled: boolean, helpers: WeaponHelpers) => {
  const { currentWeapon, facing, pos, width, isDucking } = player;

  // Sludge Barf Timer
  if (player.barfTimer && player.barfTimer > 0) {
    player.barfTimer--;
    if (player.barfTimer % 2 === 0) { 
       const sX = player.pos.x + (player.facing === 1 ? player.width : -10);
       const sY = player.isDucking ? player.pos.y + 45 : player.pos.y + 25;
       helpers.addProjectile({ 
         id: `sludge-part-${Date.now()}-${player.barfTimer}`, pos: { x: sX, y: sY }, 
         vel: { x: player.facing * (11 + Math.random() * 8), y: -3 - Math.random() * 9 }, 
         width: SLUDGE_PROJ_SIZE_MIN + Math.random() * SLUDGE_PROJ_SIZE_RAND, 
         height: SLUDGE_PROJ_SIZE_MIN + Math.random() * SLUDGE_PROJ_SIZE_RAND, 
         health: 1, maxHealth: 1, type: 'projectile', damage: SLUDGE_DAMAGE, owner: 'player', isSludge: true, life: 150 
       });
    }
  }

  // Tsunami Update
  if (state.tsunamiActive) {
    state.tsunamiX += TSUNAMI_WAVE_SPEED * state.tsunamiDir;
    const dist = Math.abs(state.tsunamiX - state.tsunamiStartX), totalDist = CANVAS_WIDTH * 1.5, progress = dist / totalDist;
    const tsunamiTopY = Math.pow(Math.min(1.0, dist / (CANVAS_WIDTH * 1.25)), 0.6) * 560, waveHeight = 600 - tsunamiTopY, density = 35;

    for (let i = 0; i <= density; i++) {
      const yPct = i / density, yPos = tsunamiTopY + (yPct * waveHeight), normalizedY = (yPct - 0.5) * 2;
      const px = state.tsunamiX + (normalizedY * normalizedY) * 120 * state.tsunamiDir;
      helpers.addParticle({ 
        pos: { x: px + (Math.random()-0.5)*40, y: yPos + (Math.random()-0.5)*15 }, 
        vel: { x: (TSUNAMI_WAVE_SPEED * 0.4 + Math.random()*8) * state.tsunamiDir, y: (Math.random()-0.5)*4 }, 
        life: 12 + Math.random()*18, color: PARTICLE_PALETTES.WATER[Math.floor(PARTICLE_PALETTES.WATER.length * Math.random())], size: 8 + Math.random()*12, isWater: true 
      });
    }

    state.projectiles.forEach((p: Projectile) => { if (p.isMethBarrel && p.health > 0) { if (Math.abs(p.pos.x + p.width/2 - state.tsunamiX) < 120) { p.vel = { x: state.tsunamiDir * 20, y: -10 }; p.health -= TSUNAMI_DAMAGE_BOSS; helpers.spawnDamageNumber(p.pos, TSUNAMI_DAMAGE_BOSS); } } });
    state.enemies.forEach((e: Enemy) => { if (e.health > 0 && !e.isBlownAway) { const ebY = e.pos.y + e.height; if (Math.abs(e.pos.x + e.width/2 - state.tsunamiX) < 120 && ebY > tsunamiTopY) { if (e.type === 'boss') { if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) { const isW = BossLogic.checkIsWeakness(state.stageId, currentWeapon); const dmg = isW ? TSUNAMI_DAMAGE_WEAKNESS : TSUNAMI_DAMAGE_BOSS; e.health -= dmg; e.hitCooldown = ENEMY_HIT_COOLDOWN; helpers.spawnDamageNumber(e.pos, dmg, isW); if (e.health <= 0) helpers.triggerBossDeath(e, state.tsunamiDir, isW); } } else { e.health = 0; e.isBlownAway = true; e.vel = { x: state.tsunamiDir * 20, y: -10 }; helpers.spawnDeathShower(e.pos, state.tsunamiDir); helpers.spawnPickup(e.pos); helpers.speakVulgarity('tsunami_kill'); player.killSatisfactionTimer = 60; } } } });
    if (progress >= 1.0) state.tsunamiActive = false;
  }

  // Taser Logic
  // Fix: Removed redundant 'currentWeapon === "GUN"' comparison since currentWeapon is already checked to be "TASER" at the start of the branch.
  if (currentWeapon === 'TASER' && shootRequested && (player.weaponAmmo['TASER'] >= 1)) {
    if (!player.isTasing) fireWeapon(player, state, helpers, false, false, infiniteAmmoEnabled);
    if (player.isTasing) {
      player.taserTimer = (player.taserTimer || 0) + 1;
      if (!infiniteAmmoEnabled && state.frame % TASER_AMMO_CONSUMPTION_RATE === 0) player.weaponAmmo['TASER'] -= 1;
      player.vel.x = 0;
      const target = (state.enemies.find((e: any) => e.id === player.taserTargetId) || state.projectiles.find((p: any) => p.id === player.taserTargetId)) as (Enemy | Projectile | undefined);
      if (target && target.health > 0) {
        target.isTased = true;
        if (state.frame % TASER_TICK_RATE === 0) {
          target.health -= TASER_DOT_DAMAGE; helpers.spawnDamageNumber(target.pos, TASER_DOT_DAMAGE);
          if (target.health <= 0) { 
            // Fix: Assert target as Enemy to access isBlownAway property safely within the type check.
            if (target.type === 'enemy') { (target as Enemy).isBlownAway = true; target.vel = { x: (Math.random()-0.5)*10, y: -15 }; helpers.spawnDeathShower(target.pos, 0); helpers.spawnPickup(target.pos); helpers.speakVulgarity('taser_kill'); } 
            player.isTasing = false; player.taserTargetId = null;
          }
        }
        if (player.taserTimer! >= TASER_FIRE_THRESHOLD && !target.isOnFire) { target.isOnFire = true; helpers.playGunSound('ignite'); }
      } else { if (player.taserTimer! > 30) { player.isTasing = false; player.taserTargetId = null; } }
    }
  } else { player.isTasing = false; player.taserTargetId = null; player.taserTimer = 0; }
};

export const handleEnemyDamage = (enemy: Enemy, damage: number, isWeakness: boolean, state: any, player: Player, helpers: WeaponHelpers) => {
  enemy.health -= damage;
  enemy.hitCooldown = ENEMY_HIT_COOLDOWN;
  helpers.spawnDamageNumber(enemy.pos, damage, isWeakness);

  if (enemy.health <= 0) {
    if (enemy.type === 'boss') helpers.triggerBossDeath(enemy, player.facing, isWeakness);
    else {
      enemy.isBlownAway = true;
      enemy.vel = { x: player.facing * 30, y: -5 };
      helpers.spawnDeathShower(enemy.pos, player.facing);
      helpers.spawnPickup(enemy.pos);
      helpers.speakVulgarity(player.isUppercutting ? 'uppercut_kill' : 'charge_kill');
    }
    return false;
  }
  return true;
};

export const fireWeapon = (player: Player, state: any, helpers: WeaponHelpers, isMoveUp: boolean, isMoveDown: boolean, infiniteAmmo: boolean) => {
  const { currentWeapon, facing, pos, width, isDucking } = player;
  const shootX = pos.x + (facing === 1 ? width : -10);
  const shootY = isDucking ? pos.y + 45 : pos.y + 25;

  if (currentWeapon === 'GUN') {
    helpers.addProjectile({ id: `p-${Date.now()}`, pos: { x: shootX, y: shootY }, vel: { x: facing * GUN_VELOCITY, y: 0 }, width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'player' });
    player.shootCooldown = GUN_COOLDOWN; helpers.playGunSound('gun');
  } else if (currentWeapon === 'BOULDER') {
    if (!state.projectiles.some((p: Projectile) => p.owner === 'player' && p.isBoulder)) {
      const vy = isMoveUp ? -18 : 0; const vx = isMoveUp ? facing * (BOULDER_SPEED * 0.9) : facing * BOULDER_SPEED;
      helpers.addProjectile({ id: `b-${Date.now()}`, pos: { x: player.pos.x + (facing === 1 ? width : -40), y: pos.y + 20 }, vel: { x: vx, y: vy }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BOULDER_DAMAGE, owner: 'player', isBoulder: true });
      player.shootCooldown = BOULDER_COOLDOWN; if (!infiniteAmmo) player.weaponAmmo['BOULDER']--;
    }
  } else if (currentWeapon === 'SHOTGUN') {
    for (let i = 0; i < SHOTGUN_PELLET_COUNT; i++) {
      const angle = (i - Math.floor(SHOTGUN_PELLET_COUNT/2)) * 0.15; const speed = 11 + Math.random() * 6;
      helpers.addProjectile({ id: `pellet-${Date.now()}-${i}`, pos: { x: shootX, y: shootY }, vel: { x: Math.cos(angle) * facing * speed, y: Math.sin(angle) * speed }, width: 10, height: 10, health: 1, maxHealth: 1, type: 'projectile', damage: SHOTGUN_DAMAGE, owner: 'player', isIce: true });
    }
    player.shootCooldown = SHOTGUN_COOLDOWN; helpers.playGunSound('ice'); if (!infiniteAmmo) player.weaponAmmo['SHOTGUN']--;
  } else if (currentWeapon === 'NEEDLES') {
    helpers.addProjectile({ id: `dart-${Date.now()}`, pos: { x: shootX, y: shootY }, vel: { x: facing * 24, y: (Math.random() - 0.5) * 5 }, width: 20, height: 4, health: 1, maxHealth: 1, type: 'projectile', damage: NEEDLE_DAMAGE, owner: 'player', isDart: true });
    player.shootCooldown = NEEDLE_COOLDOWN; helpers.playGunSound('dart'); if (!infiniteAmmo) player.weaponAmmo['NEEDLES']--;
  } else if (currentWeapon === 'FLAMETHROWER') {
    let targetAngle = isMoveUp ? -Math.PI / 4 : (isMoveDown ? Math.PI / 4 : 0); player.flameAngle = targetAngle;
    player.flameTimer = (player.flameTimer || 0) + 1;
    const currentRange = FLAMETHROWER_RANGE + (FLAMETHROWER_MAX_RANGE - FLAMETHROWER_RANGE) * Math.min(1.0, player.flameTimer / FLAMETHROWER_RAMP_FRAMES);
    if (state.frame % 2 === 0) {
      if (!infiniteAmmo) player.weaponAmmo['FLAMETHROWER']--; helpers.playGunSound('flame');
      const sX = pos.x + (facing === 1 ? width - 5 : 5), sY = isDucking ? pos.y + 45 : pos.y + 30;
      for (let i = 0; i < 6; i++) {
        const finalAngle = targetAngle + (Math.random()-0.5)*0.4, speed = (8 + Math.random()*8) * (1 + (Math.min(1.0, player.flameTimer/180))*1.5);
        helpers.addParticle({ pos: { x: sX, y: sY }, vel: { x: Math.cos(finalAngle) * facing * speed + player.vel.x, y: Math.sin(finalAngle) * speed }, life: 15 + Math.random() * 20, color: PARTICLE_PALETTES.FIRE[Math.floor(PARTICLE_PALETTES.FIRE.length * Math.random())], size: 8 + Math.random() * 12 });
      }
      state.enemies.forEach((e: Enemy) => {
        if (e.health > 0 && !e.isBlownAway) {
          const dx = (e.pos.x + e.width/2) - sX, dy = (e.pos.y + e.height/2) - sY;
          if (dx*dx + dy*dy < currentRange*currentRange && Math.abs(Math.atan2(dy, dx*facing) - targetAngle) < 0.35) {
             if (e.type === 'boss') { if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) { const isW = BossLogic.checkIsWeakness(state.stageId, currentWeapon); const dmg = BossLogic.getBossDamage(e, state.stageId, currentWeapon); e.health -= dmg; e.hitCooldown = 60; helpers.spawnDamageNumber(e.pos, dmg, isW); if (e.health <= 0) helpers.triggerBossDeath(e, facing, isW); } }
             else if (!e.hitCooldown || e.hitCooldown <= 0) { e.health -= FLAMETHROWER_DAMAGE; helpers.spawnDamageNumber(e.pos, FLAMETHROWER_DAMAGE); e.hitCooldown = 12; if (e.health <= 0) { e.isBlownAway = true; e.vel = { x: 10 * facing, y: -5 }; player.killSatisfactionTimer = 60; } }
          }
        }
      });
    }
  } else if (currentWeapon === 'SLUDGE') { player.barfTimer = 24; player.shootCooldown = SLUDGE_COOLDOWN; player.filthShieldTimer = FILTH_SHIELD_DURATION; if (!infiniteAmmo) player.weaponAmmo['SLUDGE']--; helpers.playGunSound('barf'); } 
  else if (currentWeapon === 'TSUNAMI') { if (!state.tsunamiActive) { state.tsunamiActive = true; state.tsunamiDir = facing; state.tsunamiStartX = facing === 1 ? state.camera.x : state.camera.x + 800; state.tsunamiX = state.tsunamiStartX; player.shootCooldown = TSUNAMI_COOLDOWN; helpers.playGunSound('tsunami'); if (!infiniteAmmo) player.weaponAmmo['TSUNAMI']--; } } 
  else if (currentWeapon === 'TASER') { if (!player.isTasing) { let nearest: any = null, minDist = TASER_RANGE; state.enemies.forEach((e: Enemy) => { if (e.health > 0 && !e.isBlownAway) { const dist = Math.sqrt(Math.pow(e.pos.x+e.width/2 - (pos.x+width/2), 2) + Math.pow(e.pos.y+e.height/2 - (pos.y+25), 2)); if (dist < minDist && ((facing === 1 && e.pos.x > pos.x) || (facing === -1 && e.pos.x < pos.x))) { minDist = dist; nearest = e; } } }); player.isTasing = true; player.taserTargetId = nearest ? nearest.id : null; } }
};

