  spawnDeathShower: (pos: Vector2, facing: number) => void;
}

export const updateAllWeaponry = (state: any, player: Player, shootRequested: boolean, infiniteAmmoEnabled: boolean, helpers: WeaponHelpers) => {
  const { currentWeapon, facing, pos, width, isDucking } = player;

  if (player.barfTimer && player.barfTimer > 0) {
    player.barfTimer--;
    if (player.barfTimer % 2 === 0) { 
       const sX = player.pos.x + (player.facing === 1 ? player.width : -10);
       const sY = player.isDucking ? player.pos.y + 45 : player.pos.y + 25;
       helpers.addProjectile({ 
         id: `sludge-part-${Date.now()}-${player.barfTimer}`, pos: { x: sX, y: sY }, 
         vel: { x: player.facing * (11 + Math.random() * 8), y: -3 - Math.random() * 9 }, 
         width: SLUDGE_PROJ_SIZE_MIN + Math.random() * SLUDGE_PROJ_SIZE_RAND, 
         height: SLUDGE_PROJ_SIZE_MIN + Math.random() * SLUDGE_PROJ_SIZE_RAND, 
         health: 1, maxHealth: 1, type: 'projectile', damage: SLUDGE_DAMAGE, owner: 'player', isSludge: true, life: 150 
       });
    }
  }

  if (state.tsunamiActive) {
    state.tsunamiX += TSUNAMI_WAVE_SPEED * state.tsunamiDir;
    const dist = Math.abs(state.tsunamiX - state.tsunamiStartX), totalDist = CANVAS_WIDTH * 1.5, progress = dist / totalDist;
    const tsunamiTopY = Math.pow(Math.min(1.0, dist / (CANVAS_WIDTH * 1.25)), 0.6) * 560, waveHeight = 600 - tsunamiTopY, density = 35;
    for (let i = 0; i <= density; i++) {
      const yPct = i / density, yPos = tsunamiTopY + (yPct * waveHeight), normalizedY = (yPct - 0.5) * 2;
      const px = state.tsunamiX + (normalizedY * normalizedY) * 120 * state.tsunamiDir;
      helpers.addParticle({ pos: { x: px + (Math.random()-0.5)*40, y: yPos + (Math.random()-0.5)*15 }, vel: { x: (TSUNAMI_WAVE_SPEED * 0.4 + Math.random()*8) * state.tsunamiDir, y: (Math.random()-0.5)*4 }, life: 12 + Math.random()*18, color: PARTICLE_PALETTES.WATER[Math.floor(PARTICLE_PALETTES.WATER.length * Math.random())], size: 8 + Math.random()*12, isWater: true });
    }
    state.projectiles.forEach((p: Projectile) => { if (p.isMethBarrel && p.health > 0) { if (Math.abs(p.pos.x + p.width/2 - state.tsunamiX) < 120) { p.vel = { x: state.tsunamiDir * 20, y: -10 }; p.health -= TSUNAMI_DAMAGE_BOSS; helpers.spawnDamageNumber(p.pos, TSUNAMI_DAMAGE_BOSS); } } });
    state.enemies.forEach((e: Enemy) => { if (e.health > 0 && !e.isBlownAway) { const ebY = e.pos.y + e.height; if (Math.abs(e.pos.x + e.width/2 - state.tsunamiX) < 120 && ebY > tsunamiTopY) { if (e.type === 'boss') { if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) { const isW = BossLogic.checkIsWeakness(state.stageId, currentWeapon); const dmg = isW ? TSUNAMI_DAMAGE_WEAKNESS : TSUNAMI_DAMAGE_BOSS; e.health -= dmg; e.hitCooldown = ENEMY_HIT_COOLDOWN; helpers.spawnDamageNumber(e.pos, dmg, isW); if (e.health <= 0) helpers.triggerBossDeath(e, state.tsunamiDir, isW); } } else { e.health = 0; e.isBlownAway = true; e.vel = { x: state.tsunamiDir * 20, y: -10 }; helpers.spawnDeathShower(e.pos, state.tsunamiDir); helpers.spawnPickup(e.pos); helpers.speakVulgarity('tsunami_kill'); player.killSatisfactionTimer = 60; } } } });
    if (progress >= 1.0) state.tsunamiActive = false;
  }

  if (currentWeapon === 'TASER' && shootRequested && (player.weaponAmmo['TASER'] >= 1)) {
    if (!player.isTasing) fireWeapon(player, state, helpers, false, false, infiniteAmmoEnabled);
    if (player.isTasing) {
      player.taserTimer = (player.taserTimer || 0) + 1;
      if (!infiniteAmmoEnabled && state.frame % TASER_AMMO_CONSUMPTION_RATE === 0) player.weaponAmmo['TASER'] -= 1;
      player.vel.x = 0;
      const target = (state.enemies.find((e: any) => e.id === player.taserTargetId) || state.projectiles.find((p: any) => p.id === player.taserTargetId)) as (Enemy | Projectile | undefined);
      if (target && target.health > 0) {
        target.isTased = true;
        if (state.frame % TASER_TICK_RATE === 0) {
          target.health -= TASER_DOT_DAMAGE; helpers.spawnDamageNumber(target.pos, TASER_DOT_DAMAGE);
          if (target.health <= 0) { 
            if (target.type === 'enemy') { (target as Enemy).isBlownAway = true; target.vel = { x: (Math.random()-0.5)*10, y: -15 }; helpers.spawnDeathShower(target.pos, 0); helpers.spawnPickup(target.pos); helpers.speakVulgarity('taser_kill'); } 
            player.isTasing = false; player.taserTargetId = null;
          }
        }
        if (player.taserTimer! >= TASER_FIRE_THRESHOLD && !target.isOnFire) { target.isOnFire = true; helpers.playGunSound('ignite'); }
      } else { if (player.taserTimer! > 30) { player.isTasing = false; player.taserTargetId = null; } }
    }
  } else { player.isTasing = false; player.taserTargetId = null; player.taserTimer = 0; }
};

export const handleEnemyDamage = (enemy: Enemy, damage: number, isWeakness: boolean, state: any, player: Player, helpers: WeaponHelpers) => {
  enemy.health -= damage;
  enemy.hitCooldown = ENEMY_HIT_COOLDOWN;
  helpers.spawnDamageNumber(enemy.pos, damage, isWeakness);
  if (enemy.health <= 0) {
    if (enemy.type === 'boss') helpers.triggerBossDeath(enemy, player.facing, isWeakness);
    else {
      enemy.isBlownAway = true;
      enemy.vel = { x: player.facing * 30, y: -5 };
      helpers.spawnDeathShower(enemy.pos, player.facing);
      helpers.spawnPickup(enemy.pos);
      helpers.speakVulgarity(player.isUppercutting ? 'uppercut_kill' : 'charge_kill');
    }
    return false;
  }
  return true;
};

export const fireWeapon = (player: Player, state: any, helpers: WeaponHelpers, isMoveUp: boolean, isMoveDown: boolean, infiniteAmmo: boolean) => {
  const { currentWeapon, facing, pos, width, isDucking } = player;
  const shootX = pos.x + (facing === 1 ? width : -10);
  const shootY = isDucking ? pos.y + 45 : pos.y + 25;

  if (currentWeapon === 'GUN') {
    helpers.addProjectile({ id: `p-${Date.now()}`, pos: { x: shootX, y: shootY }, vel: { x: facing * GUN_VELOCITY, y: 0 }, width: 16, height: 6, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'player' });
    player.shootCooldown = GUN_COOLDOWN; helpers.playGunSound('gun');
  } else if (currentWeapon === 'BOULDER') {
    if (!state.projectiles.some((p: Projectile) => p.owner === 'player' && p.isBoulder)) {
      const vy = isMoveUp ? -18 : 0; const vx = isMoveUp ? facing * (BOULDER_SPEED * 0.9) : facing * BOULDER_SPEED;
      helpers.addProjectile({ id: `b-${Date.now()}`, pos: { x: player.pos.x + (facing === 1 ? width : -40), y: pos.y + 20 }, vel: { x: vx, y: vy }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BOULDER_DAMAGE, owner: 'player', isBoulder: true });
      player.shootCooldown = BOULDER_COOLDOWN; if (!infiniteAmmo) player.weaponAmmo['BOULDER']--;
    }
  } else if (currentWeapon === 'SHOTGUN') {
    for (let i = 0; i < SHOTGUN_PELLET_COUNT; i++) {
      const angle = (i - Math.floor(SHOTGUN_PELLET_COUNT/2)) * 0.15; const speed = 11 + Math.random() * 6;
      helpers.addProjectile({ id: `pellet-${Date.now()}-${i}`, pos: { x: shootX, y: shootY }, vel: { x: Math.cos(angle) * facing * speed, y: Math.sin(angle) * speed }, width: 10, height: 10, health: 1, maxHealth: 1, type: 'projectile', damage: SHOTGUN_DAMAGE, owner: 'player', isIce: true });
    }
    player.shootCooldown = SHOTGUN_COOLDOWN; helpers.playGunSound('ice'); if (!infiniteAmmo) player.weaponAmmo['SHOTGUN']--;
  } else if (currentWeapon === 'NEEDLES') {
    helpers.addProjectile({ id: `dart-${Date.now()}`, pos: { x: shootX, y: shootY }, vel: { x: facing * 24, y: (Math.random() - 0.5) * 5 }, width: 20, height: 4, health: 1, maxHealth: 1, type: 'projectile', damage: NEEDLE_DAMAGE, owner: 'player', isDart: true });
    player.shootCooldown = NEEDLE_COOLDOWN; helpers.playGunSound('dart'); if (!infiniteAmmo) player.weaponAmmo['NEEDLES']--;
  } else if (currentWeapon === 'FLAMETHROWER') {
    let targetAngle = isMoveUp ? -Math.PI / 4 : (isMoveDown ? Math.PI / 4 : 0); player.flameAngle = targetAngle;
    player.flameTimer = (player.flameTimer || 0) + 1;
    const currentRange = FLAMETHROWER_RANGE + (FLAMETHROWER_MAX_RANGE - FLAMETHROWER_RANGE) * Math.min(1.0, player.flameTimer / FLAMETHROWER_RAMP_FRAMES);
    if (state.frame % 2 === 0) {
      if (!infiniteAmmo) player.weaponAmmo['FLAMETHROWER']--; helpers.playGunSound('flame');
      const sX = pos.x + (facing === 1 ? width - 5 : 5), sY = isDucking ? pos.y + 45 : pos.y + 30;
      for (let i = 0; i < 6; i++) {
        const finalAngle = targetAngle + (Math.random()-0.4)*0.4, speed = (8 + Math.random()*8) * (1 + (Math.min(1.0, player.flameTimer/180))*1.5);
        helpers.addParticle({ pos: { x: sX, y: sY }, vel: { x: Math.cos(finalAngle) * facing * speed + player.vel.x, y: Math.sin(finalAngle) * speed }, life: 15 + Math.random() * 20, color: PARTICLE_PALETTES.FIRE[Math.floor(PARTICLE_PALETTES.FIRE.length * Math.random())], size: 8 + Math.random() * 12 });
      }
      state.enemies.forEach((e: Enemy) => {
        if (e.health > 0 && !e.isBlownAway) {
          const dx = (e.pos.x + e.width/2) - sX, dy = (e.pos.y + e.height/2) - sY;
          if (dx*dx + dy*dy < currentRange*currentRange && Math.abs(Math.atan2(dy, dx*facing) - targetAngle) < 0.35) {
             if (e.type === 'boss') { if (state.arenaLocked && (!e.hitCooldown || e.hitCooldown <= 0)) { const isW = BossLogic.checkIsWeakness(state.stageId, currentWeapon); const dmg = BossLogic.getBossDamage(e, state.stageId, currentWeapon); e.health -= dmg; e.hitCooldown = 60; helpers.spawnDamageNumber(e.pos, dmg, isW); if (e.health <= 0) helpers.triggerBossDeath(e, facing, isW); } }
             else if (!e.hitCooldown || e.hitCooldown <= 0) { e.health -= FLAMETHROWER_DAMAGE; helpers.spawnDamageNumber(e.pos, FLAMETHROWER_DAMAGE); e.hitCooldown = 12; if (e.health <= 0) { e.isBlownAway = true; e.vel = { x: 10 * facing, y: -5 }; player.killSatisfactionTimer = 60; } }
          }
        }
      });
    }
  } else if (currentWeapon === 'SLUDGE') { player.barfTimer = 24; player.shootCooldown = SLUDGE_COOLDOWN; player.filthShieldTimer = FILTH_SHIELD_DURATION; if (!infiniteAmmo) player.weaponAmmo['SLUDGE']--; helpers.playGunSound('barf'); } 
  else if (currentWeapon === 'TSUNAMI') { if (!state.tsunamiActive) { state.tsunamiActive = true; state.tsunamiDir = facing; state.tsunamiStartX = facing === 1 ? state.camera.x : state.camera.x + 800; state.tsunamiX = state.tsunamiStartX; player.shootCooldown = TSUNAMI_COOLDOWN; helpers.playGunSound('tsunami'); if (!infiniteAmmo) player.weaponAmmo['TSUNAMI']--; } } 
  else if (currentWeapon === 'TASER') { if (!player.isTasing) { let nearest: any = null, minDist = TASER_RANGE; state.enemies.forEach((e: Enemy) => { if (e.health > 0 && !e.isBlownAway) { const dist = Math.sqrt(Math.pow(e.pos.x+e.width/2 - (pos.x+width/2), 2) + Math.pow(e.pos.y+e.height/2 - (pos.y+25), 2)); if (dist < minDist && ((facing === 1 && e.pos.x > pos.x) || (facing === -1 && e.pos.x < pos.x))) { minDist = dist; nearest = e; } } }); player.isTasing = true; player.taserTargetId = nearest ? nearest.id : null; } }
};

import React, { useRef, useEffect, useCallback } from 'react';
import { 
  GameStatus, Player, Enemy, Projectile, Particle, Vector2, Pickup, PickupType, WeaponType, DamageNumber, Volcano, SteamExplosion, VulgarityType 
} from '../types';
import { 
  CANVAS_WIDTH, CANVAS_HEIGHT, COLORS, GRAVITY, 
  PLAYER_SPEED, PLAYER_JUMP_FORCE, CHARGE_SPEED, CHARGE_DURATION, 
  SPECIAL_CHARGE_REGEN_FRAMES, MAX_SPECIAL_CHARGES, INITIAL_PLAYER_HEALTH, JUMP_PREP_FRAMES,
  STAGE_COLORS, UPPERCUT_FORCE, BULLET_DAMAGE, BOULDER_SPEED, BOULDER_BOUNCE_DAMPING,
  SHOTGUN_FREEZE_TIME, FLAMETHROWER_SPEED_MULT, MAX_AMMO, AMMO_PICKUP_PCT,
  BOSS_DOOR_X, DOOR_WIDTH, VULGARITIES, BOSS_DIALOGUE, PARTICLE_PALETTES, STAGES_SET_0, STAGES_SET_1,
  DOOR_OPEN_SPEED, VULGARITY_TEXT_DURATION, VOICE_LINE_COOLDOWN_FRAMES, PLAYER_INVINCIBILITY_FRAMES, 
  PLAYER_STUN_INVINCIBILITY, PLAYER_PUSHBACK_DURATION, UPPERCUT_AIR_SPEED, UPPERCUT_AIR_ACCEL, 
  BOULDER_SHRAPNEL_COUNT, HEALTH_PICKUP_SMALL, HEALTH_PICKUP_LARGE, BOULDER_SHRAPNEL_DAMAGE, 
  ENEMY_HIT_COOLDOWN, NEEDLE_DOT_TICK_RATE, NEEDLE_DOT_DAMAGE_PER_STACK, NEEDLE_OVERDOSE_THRESHOLD,
  PLAYER_PUSHBACK_VEL_X, PLAYER_PUSHBACK_VEL_Y, PLAYER_STUN_DURATION, FRICTION_DEFAULT, 
  FRICTION_ICE_STAGE, FRICTION_ICE_STOP, FILTH_SHIELD_CONTACT_DAMAGE
} from '../constants';
import * as BossLogic from '../boss';
import * as WeaponLogic from '../weapons';

interface GameCanvasProps {
  status: GameStatus;
  stageId: string | null;
  onPlayerUpdate: (health: number, specialCharges: number, specialChargeTimer: number, ammo?: Record<WeaponType, number>, forcedWeapon?: WeaponType) => void;
  onBossEncounter: () => void;
  onBossTransition: () => void;
  onBossDefeated: (stageId: string) => void;
  onBossDeath: () => void;
  onBossSelect: () => void;
  onGameOver: (victory: boolean) => void;
  onIntroComplete: () => void;
  onTogglePause: () => void;
  currentWeapon: WeaponType;
  initialAmmo: Record<WeaponType, number>;
  invincibilityEnabled: boolean;
  infiniteAmmoEnabled: boolean;
  infinitePowerEnabled: boolean;
  jumpToBossEnabled: boolean;
  bossTauntText: string;
}

const GameCanvas: React.FC<GameCanvasProps> = ({ 
  status, stageId, onPlayerUpdate, onBossEncounter, onBossTransition, 
  onBossDefeated, onBossDeath, onBossSelect, onGameOver, onIntroComplete, onTogglePause, 
  currentWeapon, initialAmmo, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled,
  bossTauntText
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);

  const gameStateRef = useRef({
    player: {
      id: 'player', pos: { x: 150, y: 100 }, vel: { x: 0, y: 0 }, width: 44, height: 64,
      health: INITIAL_PLAYER_HEALTH, maxHealth: INITIAL_PLAYER_HEALTH, type: 'player',
      isCharging: false, isUppercutting: false, isDucking: false,
      specialCharges: MAX_SPECIAL_CHARGES, specialChargeTimer: 0, chargeDuration: 0,
      isJumping: false, isGrounded: false, facing: 1, shootCooldown: 0,
      jumpPrepTimer: 0, landTimer: 0, invincibilityTimer: 0, pushbackTimer: 0,
      killSatisfactionTimer: 0, bossKillSatisfactionTimer: 0, hasUsedAirMove: false,
      jumpInputReleased: true, chargeInputReleased: true, currentWeapon: 'GUN',
      availableWeapons: ['GUN'], weaponAmmo: { ...initialAmmo }, isTasing: false,
      taserTargetId: null, taserTimer: 0, flameTimer: 0, flameAngle: 0, filthShieldTimer: 0, barfTimer: 0
    } as Player & { killSatisfactionTimer: number, bossKillSatisfactionTimer: number },
    enemies: [] as Enemy[],
    projectiles: [] as Projectile[],
    pickups: [] as Pickup[],
    particles: [] as (Particle & { isWater?: boolean })[],
    damageNumbers: [] as DamageNumber[],
    blocks: [] as { x: number, y: number, w: number, h: number, type: string }[],
    camera: { x: 0, y: 0 },
    bossSpawned: false, arenaLocked: false, doorOpenAmount: 0,
    doorState: 'closed' as 'closed' | 'opening' | 'open' | 'closing' | 'done',
    frame: 0, playerLastVulgarity: "", playerVulgarityTimer: 0,
    bossLastVulgarity: "", bossVulgarityTimer: 0, voiceLineCooldown: 0,
    victoryString: "", deathString: "", deathTimer: 0, postVictoryTimer: 0,
    introTimer: 0, bossExplosionTimer: 0, bossExplosionPos: { x: 0, y: 0 },
    tsunamiX: -1, tsunamiStartX: 0, tsunamiActive: false, tsunamiDir: 1,
    bossVolcanoes: [] as Volcano[], bossVolcanoTelegraphs: [] as Volcano[],
    bossPoopTelegraphs: [] as { pos: Vector2, life: number, spawnX: number }[],
    bossSteamExplosions: [] as SteamExplosion[], bossTsunamiSide: 0, bossTsunamiTimer: 0,
    victorWallSide: 0, ernieVibrationTimer: 0, playerStunTimer: 0, screenShakeTimer: 0,
    shouldSyncWeapon: false, totalPullForceX: 0, stageId: stageId
  });

  const keys = useRef<{ [key: string]: boolean }>({});
  const mouse = useRef({ down: false });

  useEffect(() => { gameStateRef.current.player.currentWeapon = currentWeapon; }, [currentWeapon]);
  useEffect(() => { gameStateRef.current.stageId = stageId; }, [stageId]);
  useEffect(() => { if (gameStateRef.current.deathTimer <= 0) gameStateRef.current.player.weaponAmmo = { ...initialAmmo }; }, [initialAmmo]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => { const k = e.key.toLowerCase(); keys.current[k] = true; keys.current[e.code.toLowerCase()] = true; };
    const handleKeyUp = (e: KeyboardEvent) => { const k = e.key.toLowerCase(); keys.current[k] = false; keys.current[e.code.toLowerCase()] = false; };
    window.addEventListener('keydown', handleKeyDown); window.addEventListener('keyup', handleKeyUp);
    window.addEventListener('mousedown', () => mouse.current.down = true); window.addEventListener('mouseup', () => mouse.current.down = false);
    return () => {
      window.removeEventListener('keydown', handleKeyDown); window.removeEventListener('keyup', handleKeyUp);
      if (audioCtxRef.current) audioCtxRef.current.close();
    };
  }, []);

  const spawnDamageNumber = useCallback((pos: Vector2, value: number, isCritical: boolean = false) => {
    gameStateRef.current.damageNumbers.push({ id: `dmg-${Date.now()}-${Math.random()}`, value: Math.floor(value), pos: { ...pos }, vel: { x: (Math.random()-0.5)*4, y: -4-Math.random()*2 }, life: 45, maxLife: 45, isCritical });
  }, []);

  const spawnExplosion = useCallback((pos: Vector2, color: string, count: number, baseVelX: number = 0, spread: number = 15, isGlass: boolean = false, isBossGore: boolean = false) => {
    const s = gameStateRef.current;
    for (let i = 0; i < count; i++) {
      if (s.particles.length > 2500) break;
      s.particles.push({ pos: { ...pos }, vel: { x: baseVelX+(Math.random()-0.5)*spread, y: (Math.random()-0.5)*spread }, life: isGlass ? 150+Math.random()*200 : (isBossGore ? 180+Math.random()*120 : 20+Math.random()*80), color, size: i%3===0 ? 1+Math.random()*4 : 2+Math.random()*12, isGlass, isBossGore });
    }
  }, []);

  const spawnDeathShower = useCallback((pos: Vector2, facing: number = 0, mult: number = 1, isBossDeath: boolean = false, spreadOverride?: number) => {
    const spread = spreadOverride ?? (isBossDeath ? 45 : 35);
    PARTICLE_PALETTES.FLESH.forEach(c => spawnExplosion(pos, c, Math.ceil(8*mult), facing*18, spread, false, isBossDeath));
    PARTICLE_PALETTES.GORE.forEach(c => spawnExplosion(pos, c, Math.ceil(12*mult), facing*22, spread+10, false, isBossDeath));
  }, [spawnExplosion]);

  const speakVulgarity = useCallback((category: VulgarityType) => {
    const state = gameStateRef.current; if (!('speechSynthesis' in window) || window.speechSynthesis.speaking || state.voiceLineCooldown > 0) return;
    let pool = VULGARITIES[category as keyof typeof VULGARITIES] || VULGARITIES.GUN_KILL;
    const text = pool[Math.floor(Math.random() * pool.length)];
    state.playerLastVulgarity = text; state.playerVulgarityTimer = VULGARITY_TEXT_DURATION;
    const utterance = new SpeechSynthesisUtterance(text); utterance.pitch = 0.1; utterance.rate = 1.2;
    utterance.onend = () => { state.voiceLineCooldown = VOICE_LINE_COOLDOWN_FRAMES; };
    window.speechSynthesis.speak(utterance);
  }, []);

  const playGunSound = useCallback((type: string = 'gun') => {
    try {
      if (!audioCtxRef.current) audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      const ctx = audioCtxRef.current; if (ctx.state === 'suspended') ctx.resume();
      const osc = ctx.createOscillator(); const gain = ctx.createGain();
      osc.type = 'sawtooth'; osc.frequency.setValueAtTime(150, ctx.currentTime);
      gain.gain.setValueAtTime(0.05, ctx.currentTime); osc.connect(gain); gain.connect(ctx.destination);
      osc.start(); osc.stop(ctx.currentTime + 0.1);
    } catch (e) {}
  }, []);

  const spawnPickup = useCallback((pos: Vector2) => {
    if (Math.random() > 0.6) return;
    const pr = Math.random(); const type: PickupType = pr < 0.25 ? 'small_health' : (pr < 0.35 ? 'large_health' : (pr < 0.8 ? 'small_ammo' : 'large_ammo'));
    gameStateRef.current.pickups.push({ id: `p-${Date.now()}`, pos: { ...pos }, vel: { x: (Math.random()-0.5)*4, y: -5 }, width: 20, height: 20, type, life: 600 });
  }, []);

  const createLevel = useCallback(() => {
    const s = gameStateRef.current; s.arenaLocked = false; s.doorState = 'closed'; s.doorOpenAmount = 0; s.enemies = []; s.blocks = [
      { x: -100, y: -1000, w: 100, h: 2000, type: 'wall' }, { x: 8000, y: -1000, w: 100, h: 2000, type: 'wall' }, { x: 0, y: 550, w: 8000, h: 50, type: 'ground' }, { x: BOSS_DOOR_X, y: 400, w: DOOR_WIDTH, h: 150, type: 'door' }, { x: BOSS_DOOR_X, y: -1000, w: DOOR_WIDTH, h: 1400, type: 'wall' }
    ];
    if (!jumpToBossEnabled) for (let i = 1200; i < BOSS_DOOR_X - 300; i += 1000) s.enemies.push({ id: `e-${i}`, pos: { x: i, y: 480 }, vel: { x: 0, y: 0 }, width: 50, height: 70, health: 120, maxHealth: 120, type: 'enemy', enemyType: 'shield', behavior: 'shoot', patrolRange: 0, initialX: i, shootTimer: 0 });
    s.enemies.push({ id: 'boss', pos: { x: 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 666, maxHealth: 666, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: 7700, shootTimer: 0, bossState: 'idle', stateTimer: 60 });
  }, [jumpToBossEnabled]);

  const bossHelpers: BossLogic.BossHelpers = {
    spawnDamageNumber, spawnDeathShower, onBossDeath, speakVulgarity, playGunSound, spawnExplosion,
    spawnSteamExplosionParticles: (p) => spawnExplosion(p, '#FFF', 20),
    spawnPoopExplosion: (p) => spawnExplosion(p, '#5D4037', 15),
    spawnPowderExplosion: (p) => spawnExplosion(p, '#FFF', 20),
    spawnMethExplosion: (p) => spawnExplosion(p, '#00E5FF', 30),
    spawnGlassShatter: (p) => spawnExplosion(p, '#ADD8E6', 10, 0, 15, true),
    setBossVulgarity: (t, d) => { gameStateRef.current.bossLastVulgarity = t; gameStateRef.current.bossVulgarityTimer = d; },
    setScreenShake: (d) => { gameStateRef.current.screenShakeTimer = d; },
    setErnieVibration: (d) => { gameStateRef.current.ernieVibrationTimer = d; },
    setPlayerStun: (d) => { gameStateRef.current.playerStunTimer = d; },
    addProjectile: (p) => gameStateRef.current.projectiles.push(p),
    addVolcano: (v) => gameStateRef.current.bossVolcanoes.push(v),
    clearVolcanoes: () => gameStateRef.current.bossVolcanoes = [],
    addVolcanoTelegraph: (v) => gameStateRef.current.bossVolcanoTelegraphs.push(v),
    clearVolcanoTelegraphs: () => gameStateRef.current.bossVolcanoTelegraphs = [],
    addPoopTelegraph: (t) => gameStateRef.current.bossPoopTelegraphs.push(t),
    clearPoopTelegraphs: () => gameStateRef.current.bossPoopTelegraphs = [],
    setVictorWallSide: (s) => gameStateRef.current.victorWallSide = s,
    setTsunamiActive: (a) => gameStateRef.current.tsunamiActive = a
  };

  const weaponHelpers: WeaponLogic.WeaponHelpers = {
    ...bossHelpers, addParticle: (p) => gameStateRef.current.particles.push(p),
    triggerBossDeath: (b, f, w) => BossLogic.triggerBossDeath(b, f, w, stageId, currentWeapon, gameStateRef.current, bossHelpers),
    spawnPickup,
  };

  const update = useCallback(() => {
    const s = gameStateRef.current; const { player, enemies, projectiles, blocks } = s;
    s.frame++;
    if (s.screenShakeTimer > 0) s.screenShakeTimer--;
    if (s.deathTimer > 0) { s.deathTimer--; if (s.deathTimer === 0) { player.health = 100; player.pos = { x: 150, y: 100 }; createLevel(); } return; }
    if (status !== GameStatus.PLAYING) return;

    const km = keys.current;
    const moveLeft = km['a'] || km['arrowleft']; const moveRight = km['d'] || km['arrowright'];
    const moveUp = km['w'] || km['arrowup']; const moveDown = km['s'] || km['arrowdown'];
    const jumpRequested = km[' '] || km['z'] || km['j']; const chargeRequested = km['shift'] || km['c'];
    const shootRequested = mouse.current.down;

    if (player.pushbackTimer > 0) player.pushbackTimer--;
    if (!player.isCharging && !player.isUppercutting && player.pushbackTimer <= 0) {
      const speed = player.isDucking ? 0 : PLAYER_SPEED;
      if (moveLeft) { player.vel.x = -speed; player.facing = -1; } 
      else if (moveRight) { player.vel.x = speed; player.facing = 1; } 
      else player.vel.x = 0;
    }

    WeaponLogic.updateAllWeaponry(s, player, shootRequested, infiniteAmmoEnabled, weaponHelpers);
    BossLogic.updateBossHazards(s, player, invincibilityEnabled, bossHelpers);

    player.vel.y += GRAVITY; player.pos.x += player.vel.x + s.totalPullForceX; player.pos.y += player.vel.y;
    s.totalPullForceX = 0;

    player.isGrounded = false;
    blocks.forEach(b => {
      if (player.pos.x < b.x + b.w && player.pos.x + player.width > b.x && player.pos.y < b.y + b.h && player.pos.y + player.height > b.y) {
        const overlapY = Math.min(player.pos.y + player.height - b.y, b.y + b.h - player.pos.y);
        if (overlapY < 15) { player.pos.y = b.y - player.height; player.vel.y = 0; player.isGrounded = true; }
      }
    });

    if (jumpRequested && player.isGrounded) player.vel.y = PLAYER_JUMP_FORCE;

    if (chargeRequested && player.specialCharges > 0 && !player.isCharging) {
      player.specialCharges--;
      if (moveUp) { player.isUppercutting = true; player.vel.y = UPPERCUT_FORCE; player.chargeDuration = 30; }
      else { player.isCharging = true; player.chargeDuration = 30; }
    }
    if (player.chargeDuration > 0) { 
      player.chargeDuration--; 
      if (player.isCharging) player.vel.x = player.facing * CHARGE_SPEED;
      if (player.chargeDuration <= 0) { player.isCharging = false; player.isUppercutting = false; }
    }

    s.enemies = enemies.filter(e => {
      if (e.health <= 0) return false;
      const onScreen = e.pos.x + e.width > s.camera.x - 50 && e.pos.x < s.camera.x + CANVAS_WIDTH + 50;

      if (e.type === 'boss' && s.arenaLocked) {
        BossLogic.updateBossAI(e, stageId, player, currentWeapon, invincibilityEnabled, s, bossHelpers);
      } else if (onScreen) {
        // Strict behavior gating: Only shoot and move if on screen
        e.shootTimer++; 
        e.pos.x += e.vel.x;
        if (e.behavior === 'shoot' && e.shootTimer > 90) {
           s.projectiles.push({ id: `e-p-${Date.now()}`, pos: { x: e.pos.x, y: e.pos.y + 20 }, vel: { x: player.pos.x < e.pos.x ? -6 : 6, y: 0 }, width: 14, height: 14, health: 1, maxHealth: 1, type: 'projectile', damage: 10, owner: 'enemy' });
           e.shootTimer = 0;
        }
      }
      return true;
    });

    s.projectiles = projectiles.filter(p => {
      p.pos.x += p.vel.x; p.pos.y += p.vel.y;
      return p.pos.x > s.camera.x - 200 && p.pos.x < s.camera.x + CANVAS_WIDTH + 200;
    });

    if (player.health <= 0 && s.deathTimer <= 0) s.deathTimer = 180;
    onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer, player.weaponAmmo);
  }, [status, stageId, currentWeapon, infiniteAmmoEnabled, invincibilityEnabled, onPlayerUpdate, createLevel]);

  const draw = useCallback(() => {
    const ctx = canvasRef.current?.getContext('2d'); if (!ctx) return;
    const s = gameStateRef.current; ctx.fillStyle = '#050505'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save(); ctx.translate(-s.camera.x, 0);
    s.blocks.forEach(b => { ctx.fillStyle = '#333'; ctx.fillRect(b.x, b.y, b.w, b.h); });
    s.enemies.forEach(e => { if (e.type === 'boss') BossLogic.drawBoss(ctx, e, stageId, s.frame); else { ctx.fillStyle = 'red'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); } });
    s.projectiles.forEach(p => { ctx.fillStyle = p.owner === 'player' ? 'yellow' : 'red'; ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    s.particles.forEach(p => { ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); });
    if (s.deathTimer <= 0) { ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(s.player.pos.x, s.player.pos.y, s.player.width, s.player.height); }
    ctx.restore();
  }, [stageId]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = requestAnimationFrame(loop); };
    frameId = requestAnimationFrame(loop);
    return () => cancelAnimationFrame(frameId);
  }, [update, draw]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

export default GameCanvas;

import { 
  Enemy, Projectile, Vector2, WeaponType, Player, Volcano, SteamExplosion, VulgarityType 
} from './types';
import { 
  BOSS_DIALOGUE, BULLET_DAMAGE, BOULDER_SPEED, BOSS_DOOR_X, 
  HECTOR_PULL_STRENGTH, GRAVITY, COLORS, PARTICLE_PALETTES, 
  BOSS_CHARGE_DAMAGE, BOSS_UPPERCUT_DAMAGE, ENEMY_UPPERCUT_DAMAGE,
  DALE_TRUCK_SPEED, METH_BARREL_DAMAGE, HECTOR_PULL_STRENGTH_ULT,
  TASER_BOSS_DAMAGE_REDUCTION, DALE_TRUCK_DAMAGE, DALE_PUSHBACK_VEL,
  BOSS_VULGARITY_DURATION, ERNIE_STOMP_VIBRATION_DURATION, ENEMY_HIT_COOLDOWN,
  CANVAS_WIDTH
} from './constants';

export interface BossHelpers {
  spawnDamageNumber: (pos: Vector2, value: number, isCritical?: boolean) => void;
  spawnDeathShower: (pos: Vector2, facing: number, multiplier?: number, isBossDeath?: boolean, spreadOverride?: number) => void;
  onBossDeath: () => void;
  speakVulgarity: (category: VulgarityType) => void;
  playGunSound: (type?: 'gun' | 'ice' | 'flame' | 'tsunami' | 'dart' | 'horn' | 'ignite' | 'barf') => void;
  spawnExplosion: (pos: Vector2, color: string, count: number, baseVelX?: number, spread?: number, isGlass?: boolean, isBossGore?: boolean) => void;
  spawnSteamExplosionParticles: (pos: Vector2, count?: number) => void;
  spawnPoopExplosion: (pos: Vector2, count?: number) => void;
  spawnPowderExplosion: (pos: Vector2, count?: number) => void;
  spawnMethExplosion: (pos: Vector2, count?: number) => void;
  spawnGlassShatter: (pos: Vector2) => void;
  setBossVulgarity: (text: string, duration: number) => void;
  setScreenShake: (duration: number) => void;
  setErnieVibration: (duration: number) => void;
  setPlayerStun: (duration: number) => void;
  addProjectile: (p: Projectile) => void;
  addVolcano: (v: Volcano) => void;
  clearVolcanoes: () => void;
  addVolcanoTelegraph: (v: Volcano) => void;
  clearVolcanoTelegraphs: () => void;
  addPoopTelegraph: (t: { pos: Vector2, life: number, spawnX: number }) => void;
  clearPoopTelegraphs: () => void;
  setVictorWallSide: (side: number) => void;
  setTsunamiActive: (active: boolean) => void;
}

export const speakAsBoss = (bossId: string, text: string, helpers: BossHelpers) => {
  if ('speechSynthesis' in window) {
    window.speechSynthesis.cancel();
    const utterance = new SpeechSynthesisUtterance(text);
    switch (bossId) {
      case 'Artie Avalanche': utterance.pitch = 1.6; utterance.rate = 0.85; break;
      case 'Victor Volcano': utterance.pitch = 0.7; utterance.rate = 0.85; break;
      case 'Ernie Earthquake': utterance.pitch = 0.1; utterance.rate = 0.55; break;
      case 'Hector Hurricane': utterance.pitch = 1.2; utterance.rate = 1.5; break;
      case 'Drug Trade Dale': utterance.pitch = 1.8; utterance.rate = 1.1; break;
      default: utterance.pitch = 1.0; utterance.rate = 1.0;
    }
    utterance.volume = 1.0;
    window.speechSynthesis.speak(utterance);
    helpers.setBossVulgarity(text, BOSS_VULGARITY_DURATION);
  }
};

export const checkIsWeakness = (stageId: string | null, currentWeapon: WeaponType, p?: Partial<Projectile>) => {
  if (!p) {
    if (stageId === 'Artie Avalanche' && currentWeapon === 'FLAMETHROWER') return true;
    if (stageId === 'Victor Volcano' && currentWeapon === 'TSUNAMI') return true;
    if (stageId === 'Ernie Earthquake' && currentWeapon === 'SHOTGUN') return true;
    if (stageId === 'Hector Hurricane' && currentWeapon === 'BOULDER') return true;
    if (stageId === 'Drug Trade Dale' && currentWeapon === 'SLUDGE') return true;
    return false;
  }
  if (stageId === 'Hector Hurricane' && p.isBoulder) return true;
  if (stageId === 'Victor Volcano' && p.isTsunami) return true;
  if (stageId === 'Artie Avalanche' && (p.owner === 'player' && currentWeapon === 'FLAMETHROWER')) return true;
  if (stageId === 'Ernie Earthquake' && p.isIce) return true;
  if (stageId === 'Drug Trade Dale' && p.isSludge) return true;
  return false;
};

export const getBossDamage = (boss: Enemy, stageId: string | null, currentWeapon: WeaponType, p?: Partial<Projectile>) => {
  if (stageId === 'Victor Volcano' && (p?.isTsunami || (!p && currentWeapon === 'TSUNAMI'))) return 150;

  if (currentWeapon === 'SLUDGE' || (p && p.isSludge)) {
    if (stageId === 'Drug Trade Dale') return 100;
    return 25;
  }

  const isWeak = checkIsWeakness(stageId, currentWeapon, p);
  if (isWeak) return 100;
  if (currentWeapon === 'TASER') return Math.floor(BULLET_DAMAGE * TASER_BOSS_DAMAGE_REDUCTION);
  return BULLET_DAMAGE;
};

export const triggerBossDeath = (boss: Enemy, playerFacing: number, wasWeakness: boolean, stageId: string | null, currentWeapon: WeaponType, state: any, helpers: BossHelpers) => {
  if (state.bossExplosionTimer > 0) return;
  const pos = { x: boss.pos.x + boss.width / 2, y: boss.pos.y + boss.height / 2 };
  if (stageId && BOSS_DIALOGUE.THRESHOLDS[stageId]) speakAsBoss(stageId, (BOSS_DIALOGUE.THRESHOLDS[stageId] as any)[0], helpers);
  state.bossVolcanoes = []; state.bossVolcanoTelegraphs = []; state.bossPoopTelegraphs = []; state.bossSteamExplosions = []; state.ernieVibrationTimer = 0; state.projectiles = []; state.tsunamiActive = false; state.tsunamiX = -1;
  if (wasWeakness) { state.bossExplosionTimer = 180; state.bossExplosionPos = pos; helpers.spawnDeathShower(state.bossExplosionPos, playerFacing, 35, true, 120); } else { helpers.spawnDeathShower(pos, playerFacing, 6, true, 45); helpers.onBossDeath(); state.victoryString = "V"; state.postVictoryTimer = 0; }
  state.player.killSatisfactionTimer = 0; state.player.bossKillSatisfactionTimer = 240; state.arenaLocked = false;
  let cat: VulgarityType = 'gun_kill'; if (currentWeapon === 'BOULDER') cat = 'boulder_kill'; else if (currentWeapon === 'SHOTGUN') cat = 'shotgun_kill'; else if (currentWeapon === 'FLAMETHROWER') cat = 'flamethrower_kill'; else if (currentWeapon === 'TSUNAMI') cat = 'tsunami_kill'; else if (currentWeapon === 'SLUDGE') cat = 'sludge_kill'; helpers.speakVulgarity(cat);
};

// Fixed error: Added missing updateBossHazards function
export const updateBossHazards = (state: any, player: Player, invincibilityEnabled: boolean, helpers: BossHelpers) => {
  // Update active volcanoes
  state.bossVolcanoes = state.bossVolcanoes.filter((v: Volcano) => {
    v.life--;
    if (v.life > 0) {
      const vWidth = v.type === 'wall' ? 60 : 100;
      const vHeight = v.type === 'wall' ? 400 : 60;
      const vX = v.pos.x - vWidth / 2;
      const vY = v.type === 'wall' ? v.pos.y - vHeight / 2 : v.pos.y - vHeight;

      if (!invincibilityEnabled && player.invincibilityTimer <= 0) {
        if (player.pos.x < vX + vWidth && player.pos.x + player.width > vX &&
            player.pos.y < vY + vHeight && player.pos.y + player.height > vY) {
          player.health -= 15;
          player.invincibilityTimer = 60;
          player.pushbackTimer = 20;
          player.vel.x = (player.pos.x + player.width / 2 < v.pos.x ? -1 : 1) * 12;
          player.vel.y = -8;
          helpers.speakVulgarity('hurt');
        }
      }
      if (state.frame % 4 === 0) {
        helpers.spawnExplosion(v.pos, PARTICLE_PALETTES.FIRE[Math.floor(Math.random() * PARTICLE_PALETTES.FIRE.length)], 2, 0, 8);
      }
    }
    return v.life > 0;
  });

  // Update volcano telegraphs
  state.bossVolcanoTelegraphs = state.bossVolcanoTelegraphs.filter((v: Volcano) => {
    v.life--;
    return v.life > 0;
  });

  // Update poop/hazard telegraphs (Dale/Hector)
  state.bossPoopTelegraphs = state.bossPoopTelegraphs.filter((t: any) => {
    t.life--;
    if (t.life <= 0) {
      helpers.addProjectile({
        id: `poop-${Date.now()}-${Math.random()}`,
        pos: { x: t.spawnX, y: t.pos.y },
        vel: { x: t.spawnX > 7500 ? -12 : 12, y: 0 },
        width: 32, height: 32, health: 1, maxHealth: 1,
        type: 'projectile', damage: 15, owner: 'enemy', isPoop: true
      });
      return false;
    }
    return true;
  });

  // Update steam explosions (Hector)
  state.bossSteamExplosions = state.bossSteamExplosions.filter((s: SteamExplosion) => {
    s.life--;
    if (s.life > 0) {
      if (!invincibilityEnabled && player.invincibilityTimer <= 0) {
        const dx = player.pos.x + player.width / 2 - s.pos.x;
        const dy = player.pos.y + player.height / 2 - s.pos.y;
        if (dx * dx + dy * dy < s.radius * s.radius) {
          player.health -= 10;
          player.invincibilityTimer = 40;
          player.pushbackTimer = 15;
          player.vel.x = (dx > 0 ? 1 : -1) * 8;
          player.vel.y = -6;
          helpers.speakVulgarity('hurt');
        }
      }
      if (state.frame % 2 === 0) helpers.spawnSteamExplosionParticles(s.pos);
    }
    return s.life > 0;
  });
};

export const updateBossAI = (boss: Enemy, stageId: string | null, player: Player, currentWeapon: WeaponType, invincibilityEnabled: boolean, state: any, helpers: BossHelpers) => {
  boss.stateTimer = (boss.stateTimer || 0) - 1;
  const dirToPlayer = player.pos.x + player.width/2 < boss.pos.x + boss.width/2 ? -1 : 1;
  const healthPct = (boss.health / boss.maxHealth) * 100;
  if (stageId && BOSS_DIALOGUE.THRESHOLDS[stageId]) { if (healthPct <= 75 && !boss.said75) { boss.said75 = true; speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][75], helpers); } if (healthPct <= 50 && !boss.said50) { boss.said50 = true; speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][50], helpers); } if (healthPct <= 25 && !boss.said25) { boss.said25 = true; speakAsBoss(stageId, BOSS_DIALOGUE.THRESHOLDS[stageId][25], helpers); } }
  if (stageId === 'Drug Trade Dale') handleDaleAI(boss, player, invincibilityEnabled, state, helpers); else if (stageId === 'Hector Hurricane') handleHectorAI(boss, player, invincibilityEnabled, state, helpers); else if (stageId === 'Artie Avalanche') handleArtieAI(boss, player, state, helpers); else if (stageId === 'Ernie Earthquake') handleErnieAI(boss, player, state, helpers); else if (stageId === 'Victor Volcano') handleVictorAI(boss, player, healthPct, state, helpers);
  if (boss.bossState !== 'stunned_drop' && stageId !== 'Drug Trade Dale') { const gravityMult = (stageId === 'Artie Avalanche' || (stageId === 'Ernie Earthquake' && !boss.isGroundedBoss)) ? 0.5 : 1.0; boss.vel.y += GRAVITY * gravityMult; boss.pos.x += boss.vel.x; const prevY = boss.pos.y; boss.pos.y += boss.vel.y; boss.pos.x = Math.max(BOSS_DOOR_X + 10, Math.min(8000 - boss.width - 10, boss.pos.x)); if (boss.pos.y < 100) { boss.pos.y = 100; boss.vel.y = 0; } let bossGroundedOnBlock = false; if (boss.vel.y >= 0) { for (const b of state.blocks) { if (b.type === 'platform' || b.type === 'ground') { if (boss.pos.x < b.x + b.w && boss.pos.x + boss.width > b.x && prevY + boss.height <= b.y && boss.pos.y + boss.height >= b.y) { boss.pos.y = b.y - boss.height; if (stageId === 'Ernie Earthquake' && prevY < b.y - boss.height) { helpers.setScreenShake(30); helpers.setErnieVibration(ERNIE_STOMP_VIBRATION_DURATION); } boss.vel.y = 0; boss.vel.x = 0; boss.isGroundedBoss = true; bossGroundedOnBlock = true; if (boss.bossState === 'jumping' && stageId !== 'Victor Volcano' && stageId !== 'Hector Hurricane') boss.bossState = 'idle'; break; } } } } if (!bossGroundedOnBlock) { if (boss.pos.y > 470) { boss.pos.y = 470; if (prevY < 470 && boss.vel.y > 0 && stageId === 'Ernie Earthquake') { helpers.setScreenShake(30); helpers.setErnieVibration(ERNIE_STOMP_VIBRATION_DURATION); helpers.addProjectile({ id: `b-ernie-land-${Date.now()}`, pos: { x: boss.pos.x + boss.width/2, y: boss.pos.y + 20 }, vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true }); } boss.vel.y = 0; boss.vel.x = 0; boss.isGroundedBoss = true; if (boss.bossState === 'jumping' && stageId !== 'Victor Volcano' && stageId !== 'Hector Hurricane') boss.bossState = 'idle'; } else boss.isGroundedBoss = false; } } else if (boss.bossState === 'stunned_drop') { boss.vel.y += GRAVITY * 1.5; boss.pos.y += boss.vel.y; if (boss.pos.y > 470) { boss.pos.y = 470; boss.vel.y = 0; boss.isGroundedBoss = true; if (boss.stateTimer! > 30) boss.stateTimer = 30; } }
};

const handleDaleAI = (boss: Enemy, player: Player, invincibilityEnabled: boolean, state: any, helpers: BossHelpers) => {
  if (boss.bossState === 'idle' && boss.stateTimer! <= 0) { boss.bossState = 'truck_incoming'; boss.stateTimer = 120; boss.truckX = BOSS_DOOR_X - 600; boss.truckActive = false; helpers.playGunSound('horn'); } else if (boss.bossState === 'truck_incoming') { if (boss.stateTimer! < 40) { boss.truckActive = true; boss.truckX! += DALE_TRUCK_SPEED; } const tx = boss.truckX!, ty = 400, tw = 350, th = 150; if (boss.truckActive && player.pos.x < tx + tw && player.pos.x + player.width > tx && player.pos.y < ty + th && player.pos.y + player.height > ty && player.invincibilityTimer <= 0 && !invincibilityEnabled) { player.health -= DALE_TRUCK_DAMAGE; player.invincibilityTimer = 60; player.pushbackTimer = 40; player.vel = DALE_PUSHBACK_VEL; helpers.speakVulgarity('hurt'); } state.projectiles.forEach((p: Projectile) => { if (boss.truckActive && p.isMethBarrel && p.health > 0) { if (p.pos.x < tx + tw && p.pos.x + p.width > tx && p.pos.y < ty + th && p.pos.y + p.height > ty) p.health = -1; } }); if (boss.truckX! > 8200) { boss.truckActive = false; boss.bossState = 'using_shipment'; const drugs: ('cocaine' | 'speed' | 'meth')[] = ['cocaine', 'speed', 'meth']; boss.shipmentType = drugs[Math.floor(Math.random() * drugs.length)]; boss.shipmentCount = boss.shipmentType === 'cocaine' ? 10 : (boss.shipmentType === 'meth' ? 5 : 1); boss.stateTimer = 30; } } else if (boss.bossState === 'using_shipment') { if (boss.stateTimer! <= 0) { if (boss.shipmentType === 'cocaine') { const rangeRoll = Math.random(); let vx, vy; if (rangeRoll < 0.3) { vx = -2 - Math.random() * 3; vy = -18 - Math.random() * 6; } else if (rangeRoll < 0.75) { vx = -10 - Math.random() * 5; vy = -14 - Math.random() * 5; } else { vx = -20 - Math.random() * 8; vy = -8 - Math.random() * 4; } helpers.addProjectile({ id: `coke-${Date.now()}`, pos: { x: boss.pos.x, y: boss.pos.y + 20 }, vel: { x: vx, y: vy }, width: 25, height: 25, health: 1, maxHealth: 1, type: 'projectile', damage: 30, owner: 'enemy', isCocaine: true }); boss.shipmentCount!--; boss.stateTimer = 20; if (boss.shipmentCount! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 80; } } else if (boss.shipmentType === 'meth') { helpers.addProjectile({ id: `meth-${Date.now()}`, pos: { x: boss.pos.x, y: boss.pos.y }, vel: { x: -4 - Math.random() * 3, y: -12 }, width: 40, height: 50, health: 100, maxHealth: 100, type: 'projectile', damage: METH_BARREL_DAMAGE, owner: 'enemy', isMethBarrel: true, bounces: 15 }); boss.shipmentCount!--; boss.stateTimer = 45; if (boss.shipmentCount! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 100; } } else if (boss.shipmentType === 'speed') { boss.bossState = 'speed_dash'; boss.dashCount = 8; boss.vel.x = -25; boss.stateTimer = 0; helpers.playGunSound('ice'); } } } else if (boss.bossState === 'speed_dash') { boss.pos.x += boss.vel.x; if (boss.pos.x < BOSS_DOOR_X + 20 || boss.pos.x + boss.width > 7980) { boss.vel.x *= -1; boss.dashCount!--; helpers.setScreenShake(10); if (boss.dashCount! <= 0) { boss.pos.x = 7840; boss.vel.x = 0; boss.bossState = 'idle'; boss.stateTimer = 150; } } }
};

const handleHectorAI = (boss: Enemy, player: Player, invincibilityEnabled: boolean, state: any, helpers: BossHelpers) => {
  if (boss.bossState === 'hurricane') { 
    const forceDir = (boss.pos.x + boss.width/2 - (player.pos.x + player.width/2)) > 0 ? 1 : -1; 
    state.totalPullForceX += forceDir * HECTOR_PULL_STRENGTH_ULT; 
    state.projectiles.forEach((p: Projectile) => { 
      if (p.owner === 'player' && p.isBoulder) { 
        const pullDir = (boss.pos.x + boss.width/2 - (p.pos.x + p.width/2)) > 0 ? 1 : -1; 
        p.vel.x += pullDir * 1.5; 
      } 
      if (p.isPoop) {
        p.vel.x += forceDir * HECTOR_PULL_STRENGTH; 
        const dx = (p.pos.x + p.width/2) - (boss.pos.x + boss.width/2);
        const dy = (p.pos.y + p.height/2) - (boss.pos.y + boss.height/2);
        if (Math.sqrt(dx*dx + dy*dy) < 180) { p.health = 0; helpers.spawnPoopExplosion(p.pos, 15); }
      }
    }); 
    if (state.frame % 90 === 0) { 
      const spawnLeft = forceDir > 0, spawnX = spawnLeft ? BOSS_DOOR_X : 8000; 
      const r = Math.random(); 
      let spawnY = r < 0.33 ? 510 : (r < 0.66 ? 498 : 440); 
      helpers.addPoopTelegraph({ pos: { x: spawnX, y: spawnY }, life: 60, spawnX: spawnX }); 
    } 
    if (Math.abs((boss.pos.x + boss.width/2) - (player.pos.x + player.width/2)) < 300 && player.invincibilityTimer <= 0 && !invincibilityEnabled) { 
      player.health -= 4; if (player.health > 0) { player.invincibilityTimer = 25; player.pushbackTimer = 2; helpers.speakVulgarity('hurt'); } 
    } 
    if (boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; helpers.clearPoopTelegraphs(); } 
  } else if (boss.bossState === 'jumping') { 
    if (boss.isGroundedBoss) { boss.bossState = 'hurricane'; boss.stateTimer = 300; boss.vel.x = 0; } 
  } else if (boss.stateTimer! <= 0) { boss.bossState = 'jumping'; boss.vel.y = -22 - Math.random() * 4; const targetX = boss.pos.x > 7600 ? 7300 : 7900; boss.vel.x = (targetX - boss.pos.x) * 0.035; }
};

const handleArtieAI = (boss: Enemy, player: Player, state: any, helpers: BossHelpers) => {
  if (boss.shootTimer > 0) boss.shootTimer--; if (boss.isGroundedBoss && Math.abs(boss.vel.x) < 0.5) boss.sideTimer = (boss.sideTimer || 0) + 1; else boss.sideTimer = 0; if ((boss.stateTimer! <= 0 || (boss.sideTimer || 0) > 175) && boss.isGroundedBoss) { const r = Math.random(); const mustMove = (boss.sideTimer || 0) > 120; if (r < 0.35 || (mustMove && r < 0.6)) { boss.vel.y = -13 - Math.random() * 3; boss.vel.x = (player.pos.x < boss.pos.x ? -1 : 1) * (4 + Math.random() * 2); boss.stateTimer = 70; boss.bossState = 'jumping'; boss.sideTimer = 0; } else if (r < 0.70 && boss.shootTimer <= 0 && !mustMove) { const targetDir = player.pos.x < (boss.pos.x + boss.width/2) ? -1 : 1, projW = 60; helpers.addProjectile({ id: `ice-big-${Date.now()}`, pos: { x: targetDir === 1 ? boss.pos.x + boss.width + 5 : boss.pos.x - projW - 5, y: boss.pos.y + 10 }, vel: { x: targetDir * 11, y: 0 }, width: projW, height: 60, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isIce: true }); boss.shootTimer = 60; boss.stateTimer = 80; boss.bossState = 'attacking'; } else { boss.vel.x = (player.pos.x + player.width/2 < boss.pos.x + boss.width/2 ? -1 : 1) * 7.5; boss.stateTimer = 65; boss.bossState = 'attacking'; boss.sideTimer = 0; } } if (boss.bossState === 'jumping' && !boss.isGroundedBoss && boss.shootTimer <= 0) { if (Math.abs(boss.vel.y) < 2 && boss.stateTimer! > 20 && Math.random() < 0.08) { const targetDir = player.pos.x < (boss.pos.x + boss.width/2) ? -1 : 1, projW = 60; helpers.addProjectile({ id: `ice-big-air-${Date.now()}`, pos: { x: targetDir === 1 ? boss.pos.x + boss.width + 5 : boss.pos.x - projW - 5, y: boss.pos.y + 10 }, vel: { x: targetDir * 11, y: 0 }, width: projW, height: 60, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isIce: true }); boss.shootTimer = 60; boss.stateTimer = 50; } } if (boss.isGroundedBoss) boss.vel.x *= 0.95;
};

export const handleErnieAI = (boss: Enemy, player: Player, state: any, helpers: BossHelpers) => {
  if (boss.bossState === 'stunned_drop') { if (boss.isGroundedBoss && boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; boss.rotation = 0; } } else if (boss.stateTimer! <= 0) { const dirToPlayer = player.pos.x + player.width/2 < boss.pos.x + boss.width/2 ? -1 : 1; boss.vel.y = -12; boss.vel.x = (player.pos.x - boss.pos.x) * 0.03; boss.stateTimer = 180; helpers.addProjectile({ id: `b-ernie-jump-${Date.now()}`, pos: { x: boss.pos.x + boss.width/2, y: boss.pos.y + 20 }, vel: { x: dirToPlayer * (BOULDER_SPEED + 1), y: 0 }, width: 48, height: 48, health: 1, maxHealth: 1, type: 'projectile', damage: BULLET_DAMAGE, owner: 'enemy', isBoulder: true }); }
};

const handleVictorAI = (boss: Enemy, player: Player, healthPct: number, state: any, helpers: BossHelpers) => {
  const victorMidX = boss.pos.x + boss.width / 2;
  if (boss.bossState === 'attacking') { boss.vel.x = 0; if (state.bossVolcanoes.length === 0 && boss.stateTimer! <= 0) { boss.bossState = 'idle'; boss.stateTimer = 40; } } else if (boss.bossState === 'telegraphing') { boss.vel.x = 0; if (boss.stateTimer! <= 0) { boss.bossState = 'attacking'; boss.stateTimer = 180; state.bossVolcanoTelegraphs.forEach((t: Volcano) => helpers.addVolcano({ pos: t.pos, life: 180, type: t.type })); helpers.clearVolcanoTelegraphs(); } } else if (boss.bossState === 'jumping') { if (boss.isGroundedBoss) { boss.bossState = 'telegraphing'; boss.stateTimer = 60; helpers.clearVolcanoTelegraphs(); const newSide = (state.victorWallSide + 1) % 2; helpers.setVictorWallSide(newSide); helpers.addVolcanoTelegraph({ pos: { x: newSide === 0 ? BOSS_DOOR_X : 8000, y: 250 + Math.random() * 200 }, life: 60, type: 'wall' }); const groundCount = healthPct > 50 ? 1 : 2; for(let i=0; i<groundCount; i++) { let tx = BOSS_DOOR_X + 150 + Math.random() * 500; helpers.addVolcanoTelegraph({ pos: { x: Math.max(BOSS_DOOR_X + 50, Math.min(7900, tx)), y: 550 }, life: 60, type: 'ground' }); } } } else if (boss.stateTimer! <= 0) { boss.vel.y = -20 - Math.random() * 5; const platforms = state.blocks.filter((b: any) => b.type === 'platform' && b.x > BOSS_DOOR_X); if (platforms.length > 0) { const targetPlate = platforms[Math.floor(Math.random() * platforms.length)]; boss.vel.x = (targetPlate.x + targetPlate.w / 2 - victorMidX) * 0.04; } else { boss.vel.x = (player.pos.x < boss.pos.x ? -1 : 1) * 4; } boss.bossState = 'jumping'; boss.stateTimer = 60; } if (boss.isGroundedBoss) boss.vel.x *= 0.95;
};

export const drawBoss = (ctx: CanvasRenderingContext2D, e: Enemy, id: string | null, frame: number) => {
  const { pos, width, height } = e; ctx.save(); ctx.translate(pos.x, pos.y);
  const shouldSpin = e.rotation && !(id === 'Hector Hurricane' && e.bossState === 'hurricane');
  if (shouldSpin) { ctx.translate(width / 2, height / 2); ctx.rotate(e.rotation!); ctx.translate(-width / 2, -height / 2); }
  if (id === 'Drug Trade Dale' && e.bossState === 'speed_dash') ctx.filter = `hue-rotate(${frame * 10}deg) saturate(3)`;
  switch (id) {
    case 'Artie Avalanche': ctx.fillStyle = '#AED6F1'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.fillStyle = '#FF8A80'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); ctx.fillStyle = '#2E86C1'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, Math.PI, 0); ctx.fill(); ctx.stroke(); break;
    case 'Victor Volcano': ctx.fillStyle = '#BA4A00'; ctx.fillRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); ctx.strokeRect(width * 0.1, height * 0.3, width * 0.8, height * 0.7); const lOff = (e.bossState === 'attacking' || e.bossState === 'telegraphing') ? Math.sin(frame * 0.5) * 6 : 0; ctx.fillStyle = '#C62828'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3 + lOff, width * 0.3, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); ctx.fillStyle = '#FF4500'; ctx.fillRect(width * 0.2, height * 0.2 + lOff, width * 0.6, height * 0.1); break;
    case 'Ernie Earthquake': ctx.fillStyle = '#6E2C00'; ctx.fillRect(0, height * 0.3, width, height * 0.7); ctx.strokeRect(0, height * 0.3, width, height * 0.7); ctx.fillStyle = '#FF5252'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); break;
    case 'Hector Hurricane': 
      if (e.bossState === 'hurricane') {
         ctx.save(); ctx.lineWidth = 3; ctx.shadowBlur = 15; ctx.shadowColor = '#00E5FF';
         for(let i=0; i<3; i++) if ((frame + i * 20) % 30 < 5) {
             ctx.strokeStyle = i % 2 === 0 ? '#FFFFFF' : '#00E5FF'; ctx.beginPath(); ctx.moveTo(width/2, height/2); let curX = width/2, curY = height/2;
             for(let j=0; j<6; j++) { curX += (Math.random()-0.5) * 80; curY += (Math.random()-0.5) * 80; ctx.lineTo(curX, curY); }
             ctx.stroke();
         }
         ctx.globalAlpha = 0.5; ctx.strokeStyle = '#fff'; ctx.lineWidth = 2;
         for(let i=0; i<8; i++){
            const arcR = width * (1.2 + Math.sin(frame * 0.1 + i) * 0.3); const startA = frame * 0.15 + i * (Math.PI/4);
            ctx.beginPath(); ctx.arc(width/2, height/2, arcR, startA, startA + 0.6); ctx.stroke();
         }
         ctx.restore();
      }
      ctx.fillStyle = '#16A085'; ctx.fillRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.strokeRect(width * 0.2, height * 0.3, width * 0.6, height * 0.7); ctx.fillStyle = '#FF8A80'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.3, width * 0.25, 0, Math.PI * 2); ctx.fill(); ctx.stroke(); break;
    case 'Drug Trade Dale': ctx.fillStyle = '#2C3E50'; ctx.fillRect(0, 0, width, height); ctx.strokeRect(0, 0, width, height); ctx.fillStyle = '#8E44AD'; ctx.fillRect(width * 0.2, 0, width * 0.6, height * 0.4); ctx.fillStyle = 'gold'; ctx.beginPath(); ctx.arc(width * 0.5, height * 0.25, width * 0.2, 0, Math.PI * 2); ctx.fill(); if (e.bossState === 'using_shipment') { ctx.fillStyle = '#fff'; ctx.fillRect(width * 0.1, -20, width * 0.8, 20); } break;
    case 'Toxic Tommy': ctx.fillStyle = '#27AE60'; ctx.fillRect(0, 0, width, height); ctx.strokeRect(0, 0, width, height); ctx.fillStyle = '#ADFF2F'; ctx.fillRect(width * 0.1, height * 0.1, width * 0.8, height * 0.3); ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(width * 0.3, height * 0.25, 4, 0, Math.PI * 2); ctx.fill(); ctx.beginPath(); ctx.arc(width * 0.7, height * 0.25, 4, 0, Math.PI * 2); ctx.fill(); break;
    default: ctx.fillStyle = 'yellow'; ctx.fillRect(0, 0, width, height); break;
  }
  ctx.restore();
};

export const drawDaleDrugs = (ctx: CanvasRenderingContext2D, e: Enemy) => {
  if (e.bossState === 'using_shipment' && e.shipmentCount! > 0) { const stackX = e.pos.x - 60, groundY = 550; ctx.save(); for (let i = 0; i < e.shipmentCount!; i++) { const row = Math.floor(i / 2), col = i % 2; if (e.shipmentType === 'cocaine') { ctx.fillStyle = '#fff'; ctx.strokeStyle = '#ccc'; ctx.lineWidth = 1; const bx = stackX + (col * 20) + (row * 3), by = groundY - (row * 15) - 20; ctx.fillRect(bx, by, 18, 18); ctx.strokeRect(bx, by, 18, 18); } else if (e.shipmentType === 'meth') { ctx.fillStyle = '#111'; ctx.strokeStyle = '#FFD700'; ctx.lineWidth = 2; const bx = stackX + (col * 30) - 10, by = groundY - (row * 35) - 40; ctx.fillRect(bx, by, 30, 40); ctx.strokeRect(bx, by, 30, 40); ctx.fillStyle = '#FFD700'; ctx.font = '8px "Press Start 2P"'; ctx.textAlign = 'center'; ctx.fillText("METH", bx + 15, by + 25); } else if (e.shipmentType === 'speed' && e.stateTimer! > 0) { const bx = stackX, by = groundY - 20; ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(bx + 5, by, 15, 4); ctx.fillStyle = 'red'; ctx.fillRect(bx, by - 2, 6, 8); } } ctx.restore(); }
};

export enum GameStatus {
  START = 'START',
  STAGE_SELECT = 'STAGE_SELECT',
  LEVEL_INTRO = 'LEVEL_INTRO',
  PLAYING = 'PLAYING',
  BOSS_TRANSITION = 'BOSS_TRANSITION',
  BOSS_INTRO = 'BOSS_INTRO',
  BOSS_VICTORY_SPEECH = 'BOSS_VICTORY_SPEECH',
