  // Boss fields
  bossState?: 'idle' | 'jumping' | 'attacking' | 'hurricane' | 'telegraphing' | 'stunned_drop' | 'truck_incoming' | 'using_shipment' | 'speed_dash';
  stateTimer?: number;
  jumpCount?: number;
  pauseTimer?: number;
  isGroundedBoss?: boolean;
  sideTimer?: number;
  said75?: boolean;
  said50?: boolean;
  said25?: boolean;
  // Dale Specifics
  shipmentType?: 'cocaine' | 'speed' | 'meth';
  shipmentCount?: number;
  dashCount?: number;
  truckX?: number;
  truckActive?: boolean;
