      case 'OIL_ROCKET':
        return (
          <svg viewBox="0 0 10 10" className="w-10 h-10" fill="#1A110F">
            <rect x="1" y="4" width="7" height="2" />
            <path d="M8 3 L10 5 L8 7 Z" fill="#FF4500" />
            <rect x="0" y="3" width="1" height="4" fill="#333" />
          </svg>
        );
      case 'FLAMETHROWER':
