// Main Overlay component that handles menus, stage selection, and game-over/victory screens
const Overlay: React.FC<OverlayProps> = ({ 
  status, onStart, onResume, onBossSelect, onQuitToMenu, onSelectStage, onIconClick, onCheatAllWeapons, onToggleInvincibility, onToggleInfiniteAmmo, onToggleInfinitePower, onToggleJumpToBoss,
  onIncrementRank, onDecrementRank, progressionRank = 0,
  cheatEnabled, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled, showCheats = false, bossTaunt, victorySpeech, briefing, defeatedStages = [], selectedIndex, overlayActiveTime, stageId,
  availableWeapons = [], currentWeapon
}) => {
  const isInputLocked = overlayActiveTime < 2000;
  const currentStages = STAGES(progressionRank);

  if (status === GameStatus.PLAYING || status === GameStatus.LEVEL_INTRO || status === GameStatus.BOSS_TRANSITION) return null;

  const getWeaponDescription = (w: WeaponType) => {
    if (w === 'GUN') return "STANDARD PUMP ACTION";
    if (w === 'SHOTGUN') return WEAPON_DESCRIPTIONS["Artie Avalanche"];
    if (w === 'FLAMETHROWER') return WEAPON_DESCRIPTIONS["Victor Volcano"];
    if (w === 'OIL_ROCKET') return WEAPON_DESCRIPTIONS["Oily Oscar"];
    if (w === 'BOULDER') return WEAPON_DESCRIPTIONS["Ernie Earthquake"];
    if (w === 'TSUNAMI') return WEAPON_DESCRIPTIONS["Hector Hurricane"];
    if (w === 'TASER') return WEAPON_DESCRIPTIONS["Blackout Barry"];
    if (w === 'NEEDLES') return WEAPON_DESCRIPTIONS["Drug Trade Dale"];
    if (w === 'SLUDGE') return WEAPON_DESCRIPTIONS["Toxic Tommy"];
    return "HEAVY DEVASTATION";
  };

  const getDisplayName = (w: WeaponType) => w === 'OIL_ROCKET' ? 'ROCKET' : w;

  return (
    <div className="absolute inset-0 bg-black/95 flex flex-col items-center justify-center z-50 p-6 text-center overflow-hidden">
      {status === GameStatus.START && (
        <>
          {showCheats && (
            <div className="absolute top-2 right-2 z-[60] flex flex-col gap-1 items-end max-w-[150px]">
                <div className="flex w-full border-2 border-gray-600 bg-gray-900 shadow-[2px_2px_0px_white] items-center overflow-hidden">
                   <button onClick={onDecrementRank} className="px-2 py-1 bg-gray-800 hover:bg-gray-700 text-white font-black text-[10px]">-</button>
                   <div className="flex-1 text-[7px] font-black text-yellow-400 uppercase tracking-tighter">SKP SET: {progressionRank}</div>
                   <button onClick={onIncrementRank} className="px-2 py-1 bg-gray-800 hover:bg-gray-700 text-white font-black text-[10px]">+</button>
                </div>
                <button onClick={onToggleJumpToBoss} className={`w-full px-2 py-1 border-2 transition-all font-black text-[7px] uppercase shadow-[2px_2px_0px_white] ${jumpToBossEnabled ? 'bg-red-500 border-white text-black' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>SKIP LEVEL: {jumpToBossEnabled ? 'ON' : 'OFF'}</button>
                <div className="h-2 w-full" />
                <button onClick={onToggleInvincibility} className={`w-full px-2 py-1 border-2 transition-all font-black text-[7px] uppercase shadow-[2px_2px_0px_white] ${invincibilityEnabled ? 'bg-green-500 border-white text-black' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>GOD MODE: {invincibilityEnabled ? 'ON' : 'OFF'}</button>
                <button onClick={onCheatAllWeapons} className={`w-full px-2 py-1 border-2 transition-all font-black text-[7px] uppercase shadow-[2px_2px_0px_white] ${cheatEnabled ? 'bg-yellow-500 border-white text-black' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>ALL WEAPONS: {cheatEnabled ? 'ON' : 'OFF'}</button>
                <button onClick={onToggleInfiniteAmmo} className={`w-full px-2 py-1 border-2 transition-all font-black text-[7px] uppercase shadow-[2px_2px_0px_white] ${infiniteAmmoEnabled ? 'bg-blue-500 border-white text-black' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>INF AMMO: {infiniteAmmoEnabled ? 'ON' : 'OFF'}</button>
                <button onClick={onToggleInfinitePower} className={`w-full px-2 py-1 border-2 transition-all font-black text-[7px] uppercase shadow-[2px_2px_0px_white] ${infinitePowerEnabled ? 'bg-purple-500 border-white text-black' : 'bg-gray-800 border-gray-600 text-gray-400'}`}>INF POWER: {infinitePowerEnabled ? 'ON' : 'OFF'}</button>
            </div>
          )}
          <div className="animate-in fade-in zoom-in duration-700 max-w-lg relative w-full h-full flex flex-col items-center justify-center pt-8">
            <MeatheadCaricature />
            <h1 className="text-4xl md:text-5xl text-red-600 mb-2 font-black tracking-tighter drop-shadow-[4px_4px_0px_white]">MEATHEAD</h1>
            <div className="text-white text-[9px] mb-6 border-y border-red-900 py-3 px-4 italic uppercase tracking-tight leading-relaxed max-w-sm mx-auto">MISSION: {briefing}</div>
            <button 
              disabled={isInputLocked} 
              onClick={onStart} 
              className={`px-10 py-4 text-white text-xl border-b-[8px] transition-all font-black uppercase ring-4 ring-white/10 ${isInputLocked ? 'bg-gray-700 border-gray-900 opacity-50 cursor-not-allowed' : 'bg-red-700 hover:bg-red-500 border-red-900 active:translate-y-1 active:border-b-[2px]'}`}
            >
              {isInputLocked ? 'LOADING MISSION...' : 'PRESS START'}
            </button>
            <ControlsGuide />
          </div>
        </>
      )}

      {status === GameStatus.STAGE_SELECT && (
        <div className="flex flex-col items-center w-full max-w-4xl">
          <h2 className="text-2xl text-white font-black italic mb-8 tracking-widest bg-red-900 px-6 py-2 border-2 border-white shadow-[4px_4px_0px_white]">SELECT YOUR TARGET</h2>
          <div className="grid grid-cols-2 gap-8 w-full max-w-2xl px-4">
            {currentStages.map((stage, i) => {
              const isDefeated = defeatedStages.includes(stage.id);
              const isSelected = selectedIndex === i;
              return (
                <div 
                  key={stage.id} 
                  onClick={() => onSelectStage?.(stage.id)}
                  className={`relative cursor-pointer transition-all duration-200 group border-4 ${isSelected ? 'border-yellow-400 scale-105 shadow-[0_0_30px_rgba(255,255,0,0.4)]' : 'border-white/20'}`}
                >
                  <div className={`aspect-video overflow-hidden ${isDefeated ? 'grayscale brightness-50' : ''}`}>
                    <BossPortrait id={stage.id} />
                  </div>
                  <div className={`absolute bottom-0 left-0 right-0 p-2 font-black italic text-[10px] uppercase text-center border-t-2 ${isSelected ? 'bg-yellow-400 text-black border-white' : 'bg-black text-white border-white/20'}`}>
                    {stage.id}
                  </div>
                  {isDefeated && (
                    <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                      <div className="bg-red-600 text-white font-black text-4xl -rotate-12 border-4 border-white px-4 py-2 shadow-2xl">DELETED</div>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        </div>
      )}

      {status === GameStatus.PAUSED && (
        <div className="flex flex-col items-center w-full max-w-2xl p-8 bg-black/80 border-4 border-red-900 shadow-[0_0_50px_rgba(255,0,0,0.2)]">
          <h2 className="text-4xl text-red-600 font-black italic mb-10 tracking-tighter drop-shadow-[2px_2px_0px_white]">PUMP BREAK</h2>

          <div className="w-full mb-10">
             <div className="text-gray-400 text-[10px] font-black uppercase mb-4 text-left border-b border-gray-800 pb-2">WEAPON INVENTORY</div>
             <div className="flex flex-wrap gap-4 justify-center">
               {availableWeapons.map((w, i) => (
                 <div key={w} className="flex flex-col items-center gap-2">
                   <WeaponIcon 
                    type={w} 
                    isEquipped={currentWeapon === w} 
                    isSelected={selectedIndex === i}
                    onClick={() => onIconClick?.(i)}
                   />
                   <div className={`text-[8px] font-black ${selectedIndex === i ? 'text-yellow-400' : 'text-white/40'}`}>
                     {getDisplayName(w)}
                   </div>
                 </div>
               ))}
             </div>

             {selectedIndex >= 0 && selectedIndex < availableWeapons.length && (
               <div className="mt-6 p-4 bg-gray-900 border-2 border-gray-700 min-h-[80px] flex flex-col justify-center">
                 <div className="text-yellow-400 font-black text-[10px] italic mb-1 uppercase underline decoration-2">{WEAPON_NAMES[Object.keys(WEAPON_NAMES).find(k => BOSS_WEAPON_MAP[k] === availableWeapons[selectedIndex]) || ''] || 'STANDARD ISSUE'}</div>
                 <div className="text-white text-[9px] font-bold uppercase leading-tight italic">{getWeaponDescription(availableWeapons[selectedIndex])}</div>
               </div>
             )}
          </div>

          <div className="flex flex-col gap-3 w-full max-w-xs">
            <button onClick={onResume} className={`w-full py-3 font-black italic uppercase border-2 shadow-[4px_4px_0px_red] transition-all ${selectedIndex === availableWeapons.length ? 'bg-white text-black border-white' : 'bg-red-900 text-white border-red-700 hover:bg-red-700'}`}>BACK TO THE GAINS</button>
            <button onClick={onBossSelect} className={`w-full py-3 font-black italic uppercase border-2 shadow-[4px_4px_0px_red] transition-all ${selectedIndex === availableWeapons.length + 1 ? 'bg-white text-black border-white' : 'bg-red-900 text-white border-red-700 hover:bg-red-700'}`}>ABANDON REP</button>
            <button onClick={onQuitToMenu} className={`w-full py-3 font-black italic uppercase border-2 shadow-[4px_4px_0px_red] transition-all ${selectedIndex === availableWeapons.length + 2 ? 'bg-white text-black border-white' : 'bg-red-900 text-white border-red-700 hover:bg-red-700'}`}>QUIT GYM</button>
          </div>
        </div>
      )}

      {status === GameStatus.BOSS_INTRO && (
        <div className="flex flex-col items-center w-full">
           <div className="text-red-600 text-6xl font-black italic mb-4 animate-bounce tracking-tighter drop-shadow-[4px_4px_0px_white]">WARNING!</div>
           <div className="text-white text-xl font-black italic bg-red-900 px-10 py-4 border-4 border-white shadow-[10px_10px_0px_black] uppercase max-w-lg mb-8">
             {stageId && `${stageId.toUpperCase()} INCOMING!`}
           </div>
           <div className="text-yellow-400 text-sm font-black italic animate-pulse">"{bossTaunt}"</div>
           <div className="mt-12 text-white/30 text-[10px] font-black italic uppercase">PRESS START TO BEGIN THE ASSAULT</div>
        </div>
      )}

      {status === GameStatus.BOSS_VICTORY_SPEECH && (
        <div className="flex flex-col items-center w-full">
           <h2 className="text-green-500 text-5xl font-black italic mb-6 tracking-tighter drop-shadow-[4px_4px_0px_white]">TARGET DELETED</h2>
           <div className="text-white text-[11px] font-black italic bg-gray-900 border-y-4 border-green-600 py-8 px-12 max-w-xl leading-relaxed uppercase tracking-wide">
             {victorySpeech}
           </div>
           <div className="mt-10 flex gap-4">
              <div className="p-4 bg-green-900 border-2 border-white">
                <div className="text-[8px] text-white/50 mb-2">NEW WEAPON ACQUIRED:</div>
                <div className="text-white font-black italic text-lg">{stageId && WEAPON_NAMES[stageId]}</div>
              </div>
           </div>
           <div className="mt-12 text-white/40 text-[10px] font-black italic uppercase animate-pulse">PRESS START TO CONTINUE THE MASSACRE</div>
        </div>
      )}

      {status === GameStatus.GAME_OVER && (
        <div className="flex flex-col items-center">
           <h2 className="text-8xl text-red-600 font-black italic mb-4 tracking-tighter drop-shadow-[8px_8px_0px_white] animate-pulse">TOTAL FAILURE</h2>
           <div className="text-white text-[10px] font-black italic mb-12 uppercase tracking-[0.3em]">YOU SKIPPED TOO MANY LEG DAYS</div>
           <button onClick={onStart} className="px-12 py-5 bg-red-800 text-white text-2xl font-black italic border-b-[10px] border-red-950 hover:bg-red-600 hover:scale-110 active:translate-y-2 active:border-b-0 transition-all uppercase ring-4 ring-white/10">TRY AGAIN, NANCY</button>
        </div>
      )}

      {status === GameStatus.VICTORY && (
        <div className="flex flex-col items-center max-w-2xl">
           <h2 className="text-6xl text-yellow-400 font-black italic mb-2 tracking-tighter drop-shadow-[6px_6px_0px_red]">ULTIMATE PUMP</h2>
           <div className="text-white text-[10px] font-black italic mb-10 uppercase tracking-[0.5em] border-b border-white/20 pb-4">ALL WEAKNESS ELIMINATED</div>
           <div className="aspect-video w-96 bg-gray-900 border-4 border-yellow-400 p-4 mb-8 overflow-hidden relative">
              <MeatheadCaricature />
              <div className="absolute inset-x-0 bottom-0 bg-yellow-400 text-black font-black italic py-1 text-center text-[10px]">SUPREME MEATHEAD</div>
           </div>
           <button onClick={onStart} className="px-12 py-5 bg-yellow-600 text-black text-2xl font-black italic border-b-[10px] border-yellow-900 hover:bg-yellow-400 hover:scale-110 active:translate-y-2 active:border-b-0 transition-all uppercase">RESTART BULK PHASE</button>
        </div>
      )}
    </div>
  );
};

