        state.enemies.push({ id: `tank-${i}`, pos: { x: i + 600, y: 490 }, vel: { x: 0, y: 0 }, width: 60, height: 60, health: 200, maxHealth: 200, type: 'enemy', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: i + 600, shootTimer: 0 });
        state.enemies.push({ id: `rusher-${i}`, pos: { x: i + 800, y: 480 }, vel: { x: 0, y: 0 }, width: 50, height: 70, health: 300, maxHealth: 300, type: 'enemy', enemyType: 'tank', behavior: 'patrol', patrolRange: 0, initialX: i + 800, shootTimer: 0, pauseTimer: 0 });
      }
    }
    const isSet0 = STAGES_SET_0.some(s => s.id === stageId);
    if (isSet0 || stageId === 'Drug Trade Dale' || stageId === 'Blackout Barry' || stageId === 'Toxic Tommy' || stageId === 'Oily Oscar') state.enemies.push({ id: 'boss', pos: { x: (stageId === 'Drug Trade Dale' || stageId === 'Blackout Barry' || stageId === 'Toxic Tommy' || stageId === 'Oily Oscar') ? 7840 : 7700, y: 470 }, vel: { x: 0, y: 0 }, width: 80, height: 80, health: 666, maxHealth: 666, type: 'boss', enemyType: 'tank', behavior: 'shoot', patrolRange: 0, initialX: (stageId === 'Drug Trade Dale' || stageId === 'Blackout Barry' || stageId === 'Toxic Tommy' || stageId === 'Oily Oscar') ? 7840 : 7700, shootTimer: 0, bossState: 'idle', stateTimer: 60, truckX: 0, truckActive: false });

    state.player.killSatisfactionTimer = 0;
    state.player.bossKillSatisfactionTimer = 0;
    state.player.filthShieldTimer = 0;
    state.player.barfTimer = 0;
    state.player.isTasing = false;
