        ctx.beginPath(); ctx.moveTo(-p.width/2, p.height/2); ctx.lineTo(-p.width/2 - 10, p.height/2 + 5); ctx.lineTo(-p.width/2 + 5, p.height/2); ctx.fill();
        // Body (Oily)
        const grd = ctx.createLinearGradient(-p.width/2, 0, p.width/2, 0); grd.addColorStop(0, '#1A110F'); grd.addColorStop(0.5, '#000000'); grd.addColorStop(1, '#1A110F'); ctx.fillStyle = grd; ctx.fillRect(-p.width/2, -p.height/2, p.width * 0.8, p.height); 
        // Nose cone
        ctx.fillStyle = '#FF4500'; ctx.beginPath(); ctx.moveTo(p.width * 0.3, -p.height/2); ctx.lineTo(p.width/2, 0); ctx.lineTo(p.width * 0.3, p.height/2); ctx.fill();
        // Rocket thrust
        if (state.frame % 2 === 0) { ctx.fillStyle = '#FFD700'; ctx.beginPath(); ctx.arc(-p.width/2 - 5, 0, 8, 0, Math.PI * 2); ctx.fill(); }
        // Oil dripping off rocket
        if (state.frame % 4 === 0) { state.particles.push({ pos: { x: p.pos.x, y: p.pos.y + 5 }, vel: { x: -p.vel.x * 0.5, y: 2 }, life: 20, color: '#1A110F', size: 4 }); }
        ctx.restore();
      } else if (p.isOilSplash) {
        ctx.fillStyle = '#1A110F'; ctx.beginPath(); ctx.arc(p.pos.x, p.pos.y, p.width/2, 0, Math.PI * 2); ctx.fill();
      } else if (p.isCocaine) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(state.frame * 0.1); ctx.fillStyle = '#fff'; ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height); ctx.strokeStyle = '#ccc'; ctx.strokeRect(-p.width/2, -p.height/2, p.width, p.height); ctx.restore(); } else if (p.isMethBarrel) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(p.rotation || 0); ctx.fillStyle = '#111'; ctx.strokeStyle = '#FFD700'; ctx.lineWidth = 2; ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height); ctx.strokeRect(-p.width/2, -p.height/2, p.width, p.height); ctx.fillStyle = '#FFD700'; ctx.font = 'bold 8px "Press Start 2P"'; ctx.textAlign = 'center'; ctx.fillText("METH", 0, 5); ctx.restore(); } else if (p.isDart) { ctx.save(); ctx.translate(p.pos.x + p.width/2, p.pos.y + p.height/2); ctx.rotate(Math.atan2(p.vel.y, p.vel.x)); ctx.fillStyle = COLORS.PROJECTILE_DART; ctx.fillRect(-p.width/2, -p.height/2, p.width, p.height); ctx.fillStyle = 'red'; ctx.fillRect(p.width/2 - 6, -p.height/2 - 1, 6, p.height + 2); ctx.restore(); } else { ctx.fillStyle = (p.isIce) ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); } ctx.restore(); });
    particles.forEach(p => { ctx.save(); if (!p.isStuck) ctx.globalAlpha = p.life < 100 ? p.life / 100 : 1; else ctx.globalAlpha = 0.85; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); ctx.restore(); });
    damageNumbers.forEach(d => { ctx.save(); ctx.globalAlpha = d.life / d.maxLife; ctx.font = `bold ${d.value === 'OVERDOSE' ? '24px' : '16px'} "Press Start 2P"`; ctx.fillStyle = d.value === 'OVERDOSE' ? '#FFD700' : (d.isCritical ? '#FFD700' : (typeof d.value === 'number' && d.value > 50 ? '#FF4500' : '#FFFFFF')); ctx.textAlign = 'center'; ctx.fillText(d.value.toString(), d.pos.x, d.pos.y); ctx.restore(); });
    ctx.restore();
    if (state.victoryString && (status === GameStatus.PLAYING || status === GameStatus.VICTORY)) { ctx.save(); ctx.font = 'bold 50px "Press Start 2P"'; ctx.fillStyle = 'yellow'; ctx.textAlign = 'center'; ctx.strokeStyle = 'black'; ctx.lineWidth = 4; ctx.strokeText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.fillText(state.victoryString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore(); }
    if (state.deathTimer > 0) { ctx.save(); ctx.font = 'bold 60px "Press Start 2P"'; ctx.fillStyle = '#FF0000'; ctx.textAlign = 'center'; ctx.fillText(state.deathString, CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2); ctx.restore(); }
  }, [status, stageId, onBossDefeated, currentWeapon, respawn, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled, bossTauntText, onPlayerUpdate, spawnDamageNumber, spawnDeathShower, speakVulgarity, playGunSound, spawnExplosion, spawnSteamExplosionParticles, spawnPoopExplosion, spawnPowderExplosion, spawnMethExplosion, spawnGlassShatter, onBossDeath, onIntroComplete, onBossEncounter, onBossTransition, drawPlayer]);

  useEffect(() => {
    let frameId: number; 
    const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    const state = gameStateRef.current;
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) { 
      if (state.frame === 0 && status === GameStatus.LEVEL_INTRO) { 
        state.frame = 1;
        createLevel(); 
      }
      frameId = window.requestAnimationFrame(loop); 
    } else { 
      state.victoryString = ""; state.postVictoryTimer = 0; state.bossExplosionTimer = 0; state.introTimer = 0; state.enemies = []; state.particles = []; state.projectiles = []; state.blocks = []; state.camera = { x: 0, y: 0 }; state.frame = 0; draw(); 
    }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

