          <div className="grid grid-cols-2 gap-8 w-full max-w-2xl px-4">
            {currentStages.map((stage, i) => {
              const isDefeated = defeatedStages.includes(stage.id);
              const isSelected = selectedIndex === i;
              return (
                <div 
                  key={stage.id} 
                  onClick={() => onSelectStage?.(stage.id)}
                  className={`relative cursor-pointer transition-all duration-200 group border-4 ${isSelected ? 'border-yellow-400 scale-105 shadow-[0_0_30px_rgba(255,255,0,0.4)]' : 'border-white/20'}`}
