              );
            })}
          </div>
        </div>
      )}

      {status === GameStatus.PAUSED && (
        <div className="flex flex-col items-center w-full max-w-2xl p-8 bg-black/80 border-4 border-red-900 shadow-[0_0_50px_rgba(255,0,0,0.2)]">
          <h2 className="text-4xl text-red-600 font-black italic mb-10 tracking-tighter drop-shadow-[2px_2px_0px_white]">PUMP BREAK</h2>

          <div className="w-full mb-10">
