          <rect width="100" height="100" fill="#1A110F" />
          <ellipse cx="50" cy="60" rx="35" ry="30" fill="#3E2723" stroke="black" strokeWidth="2" />
          <rect x="42" y="30" width="16" height="20" fill="#FF4500" stroke="black" />
        </svg>
      );
    case 'Drug Trade Dale':
      return (
        <svg viewBox="0 0 100 100" className="w-full h-full">
          <rect width="100" height="100" fill="#1D0C24" />
          <path d="M30 30 L70 30 L70 80 L30 80 Z" fill="#8E44AD" stroke="black" strokeWidth="2" />
