    ];
    if (stageId === 'Artie Avalanche') { for (let i = 500; i < doorX; i += 700) { const p1 = { x: i, y: 450, w: 150, h: 20, type: 'platform' }; const p2 = { x: i + 200, y: 320, w: 150, h: 20, type: 'platform' }; const p3 = { x: i + 400, y: 190, w: 150, h: 20, type: 'platform' }; state.blocks.push(p1, p2, p3); if (Math.random() > 0.4) addPickupOnPlatform(p2); if (Math.random() > 0.6) addPickupOnPlatform(p3); } } 
