      let iW = player.width, iH = player.height, iX = player.pos.x, iY = player.pos.y;
      if (player.isCharging) { iW += 10; iH -= 10; } else if (player.isUppercutting) { iW -= 15; iH += 40; iY -= 30; iX += 7.5; }
      const hasS = player.filthShieldTimer && player.filthShieldTimer > 0;
      const cHit = (player.isCharging || player.isUppercutting || hasS) && iX < e.pos.x + e.width && iX + iW > e.pos.x && iY < e.pos.y + e.height && iY + iH > e.pos.y;

      if (cHit && onScrn && (!e.hitCooldown || e.hitCooldown <= 0)) {
        if (e.type === 'boss' && !state.arenaLocked) { player.vel = { x: (player.pos.x + player.width/2 < e.pos.x + e.width/2 ? -1 : 1) * 18, y: -4 }; player.pushbackTimer = PLAYER_PUSHBACK_DURATION; return true; }
        let dmg = player.isCharging ? BOSS_CHARGE_DAMAGE : (e.type === 'boss' ? BOSS_UPPERCUT_DAMAGE : ENEMY_UPPERCUT_DAMAGE);
        if (hasS) { dmg = (e.type === 'boss' && stageId === 'Drug Trade Dale') ? 100 : (e.type === 'boss' ? 50 : dmg + FILTH_SHIELD_CONTACT_DAMAGE); player.filthShieldTimer = 0; spawnExplosion({ x: player.pos.x + player.width/2, y: player.pos.y + player.height/2 }, '#43A047', 15, 0, 15); }
        const frozen = (e.frozenTimer && e.frozenTimer > 0); if (frozen) dmg *= 2;
        e.health -= dmg; e.hitCooldown = ENEMY_HIT_COOLDOWN; spawnDamageNumber(e.pos, dmg, player.isUppercutting || frozen || hasS);
        if (e.health > 0) {
          if (frozen) e.frozenTimer = 0;
          if (player.isCharging && e.isOiled && e.enemyType !== 'flyer') {
              // BILLIARD TRIGGER
              e.isKnockedBack = true;
              e.vel.x = player.facing * OILED_KNOCKBACK_SPEED;
              e.pauseTimer = 120;
          } else if (e.id.startsWith('rusher')) { e.vel.x = player.facing * 15; e.pauseTimer = 120; } 
          else if (e.type !== 'boss') e.pauseTimer = 60;
          player.vel = { x: (player.pos.x + player.width/2 < e.pos.x + e.width/2 ? -1 : 1) * PLAYER_PUSHBACK_VEL_X, y: PLAYER_PUSHBACK_VEL_Y }; player.pushbackTimer = PLAYER_PUSHBACK_DURATION; player.isCharging = false; player.isUppercutting = false; player.invincibilityTimer = PLAYER_STUN_INVINCIBILITY;
        } else {
          if (e.type === 'boss') BossLogic.triggerBossDeath(e, player.facing, false, stageId, currentWeapon, state, bh);
          else { e.isBlownAway = true; e.vel = { x: player.isUppercutting ? 0 : player.facing * 30, y: player.isUppercutting ? -30 : -5 }; if (frozen) spawnGlassShatter(e.pos); else spawnDeathShower(e.pos, player.facing); spawnPickup(e.pos); speakVulgarity(hasS ? 'sludge_kill' : (player.isUppercutting ? 'uppercut_kill' : 'charge_kill')); player.killSatisfactionTimer = 60; }
          return false;
        }
      }
      return true;
    });

    const isFireFlame = currentWeapon === 'FLAMETHROWER' && sReq && hAmmo('FLAMETHROWER');
    player.isDucking = mD && player.isGrounded && !player.isCharging && !player.isUppercutting && !isFireFlame && !player.isTasing;

    if (player.jumpPrepTimer > 0) { player.jumpPrepTimer--; if (player.jumpPrepTimer === 0) { player.vel.y = PLAYER_JUMP_FORCE; player.isGrounded = false; } } 
    else { 
      if (jReq && player.isGrounded && player.jumpInputReleased && !player.isCharging && player.pushbackTimer <= 0 && !pStunned && !player.isTasing) { player.jumpPrepTimer = JUMP_PREP_FRAMES; player.jumpInputReleased = false; } 
      if (!player.isCharging && !player.isUppercutting && player.pushbackTimer <= 0 && !pStunned && !player.isTasing) { 
        const sLimit = isFireFlame ? PLAYER_SPEED * FLAMETHROWER_SPEED_MULT : PLAYER_SPEED; 
        if (!player.isDucking) { const acc = (stageId === 'Artie Avalanche' || stageId === 'Blackout Barry') ? 0.55 : 1.5; if (mL) { player.facing = -1; if (player.isGrounded || Math.abs(player.vel.x) <= sLimit) player.vel.x = Math.max(-sLimit, player.vel.x - acc); } else if (mR) { player.facing = 1; if (player.isGrounded || Math.abs(player.vel.x) <= sLimit) player.vel.x = Math.min(sLimit, player.vel.x + acc); } else if (player.isGrounded) { if (stageId === 'Artie Avalanche' || stageId === 'Blackout Barry') { player.vel.x *= FRICTION_ICE_STAGE; if (Math.abs(player.vel.x) < 0.1) player.vel.x = 0; } else player.vel.x = 0; } } 
        else if (player.isGrounded) { if (stageId === 'Artie Avalanche' || stageId === 'Blackout Barry') player.vel.x *= FRICTION_ICE_STOP; else player.vel.x = 0; } 
        if (!player.isGrounded && Math.abs(player.vel.x) <= sLimit) player.vel.x *= FRICTION_DEFAULT; 
      } else if (player.isCharging) { player.chargeDuration--; player.vel.x = player.facing * CHARGE_SPEED; if (player.chargeDuration <= 0) { player.isCharging = false; if (player.isGrounded) player.vel.x = player.facing * PLAYER_SPEED; } } 
      else if (player.isUppercutting) { player.chargeDuration--; if (mL) player.vel.x = Math.max(-UPPERCUT_AIR_SPEED, player.vel.x - UPPERCUT_AIR_ACCEL); else if (mR) player.vel.x = Math.min(UPPERCUT_AIR_SPEED, player.vel.x + UPPERCUT_AIR_ACCEL); else player.vel.x *= 0.95; if (player.chargeDuration <= 0) player.isUppercutting = false; } 
      if (cReq && player.chargeInputReleased && !player.isCharging && !player.isUppercutting && !player.isDucking && (player.specialCharges > 0 || infinitePowerEnabled) && !isFireFlame && !pStunned && !player.isTasing) { player.chargeInputReleased = false; if (!infinitePowerEnabled) player.specialCharges--; player.chargeDuration = CHARGE_DURATION; if (mU) { player.isUppercutting = true; player.vel.y = UPPERCUT_FORCE; player.isGrounded = false; player.vel.x *= 0.5; } else { player.isCharging = true; player.vel.x = player.facing * CHARGE_SPEED; } } 
      if (sReq && player.shootCooldown <= 0 && hAmmo(currentWeapon) && currentWeapon !== 'TASER') WeaponLogic.fireWeapon(player, state, wh, mU, mD, infiniteAmmoEnabled); 
    } 

    if (player.shootCooldown > 0) player.shootCooldown--; player.vel.y += GRAVITY; 
    if (!jReq && player.vel.y < 0 && !player.isGrounded && !player.isCharging && !player.isUppercutting) player.vel.y *= 0.5; 
    if (pStunned) player.pos.y += (state.frame % 2 === 0 ? -2 : 2); player.pos.x += player.vel.x; player.pos.y += player.vel.y; 
    if (player.pos.x < 50) player.pos.x = 50; if (state.arenaLocked && player.pos.y < 100) { player.pos.y = 100; player.vel.y = 0; }
    player.isGrounded = false;
    blocks.forEach(b => { if (b.type === 'door' && (state.doorState === 'opening' || state.doorState === 'open' || state.doorState === 'closing')) return; if (b.type === 'pit' || b.type === 'wall' || b.type === 'ground' || b.type === 'platform' || b.type === 'door') { if (player.pos.x < b.x + b.w && player.pos.x + player.width > b.x && player.pos.y < b.y + b.h && player.pos.y + player.height > b.y) { if (b.type === 'door' && state.doorState === 'closed') { const isS1 = STAGES_SET_1.some(s => s.id === stageId); if (isS1 && stageId !== 'Drug Trade Dale' && stageId !== 'Blackout Barry' && stageId !== 'Toxic Tommy' && stageId !== 'Oily Oscar') { onBossDefeated(stageId || ""); return; } state.doorState = 'opening'; player.vel.x = 0; player.vel.y = 0; state.projectiles = []; state.enemies.forEach(e => { if (e.type !== 'boss' && e.health > 0) { e.health = 0; spawnDeathShower(e.pos, 0, 1); spawnPickup(e.pos); } }); onBossTransition(); return; } if (b.type === 'pit') return; const oX = Math.min(player.pos.x + player.width - b.x, b.x + b.w - player.pos.x), oY = Math.min(player.pos.y + player.height - b.y, b.y + b.h - player.pos.y); if (oX < oY) { player.pos.x = (player.pos.x + player.width / 2 < b.x + b.w / 2) ? b.x - player.width : b.x + b.w; player.vel.x = 0; if (player.isCharging) player.isCharging = false; } else { if (player.pos.y + player.height / 2 < b.y + b.h / 2) { player.pos.y = b.y - player.height; player.isGrounded = true; player.hasUsedAirMove = false; player.vel.y = 0; const sLimit = isFireFlame ? PLAYER_SPEED * FLAMETHROWER_SPEED_MULT : PLAYER_SPEED; if (Math.abs(player.vel.x) > sLimit) player.vel.x = Math.sign(player.vel.x) * sLimit; } else { player.pos.y = b.y + b.h; player.vel.y = 0; } } } } });

    state.projectiles = projectiles.filter(p => { 
      if (p.health <= 0) return false; 
      if (p.isOilSplash) { for (const e of state.enemies) if (e.health > 0 && !e.isBlownAway) { if (p.pos.x < e.pos.x + e.width && p.pos.x + p.width > e.pos.x && p.pos.y < e.pos.y + e.height && p.pos.y + p.height > e.pos.y) { e.isOiled = true; e.oiledTimer = OILED_DURATION; return false; } } }
      p.pos.x += p.vel.x; p.pos.y += p.vel.y; if (p.life !== undefined && --p.life <= 0) return false; return p.pos.x > state.camera.x - 400 && p.pos.x < state.camera.x + CANVAS_WIDTH + 400; 
    });

    state.damageNumbers = damageNumbers.filter(d => { d.pos.x += d.vel.x; d.pos.y += d.vel.y; d.vel.y += 0.15; d.life--; return d.life > 0; });
    state.particles = state.particles.filter(p => { if (!p.isStuck) { p.pos.x += p.vel.x; p.pos.y += p.vel.y; p.life--; } return p.life > 0; });
    if (!state.arenaLocked && state.victoryString === "" && state.bossExplosionTimer <= 0) state.camera.x = Math.max(0, Math.min(state.doorState === 'closed' ? BOSS_DOOR_X + DOOR_WIDTH - CANVAS_WIDTH : 8000 - CANVAS_WIDTH, player.pos.x - CANVAS_WIDTH / 2 + player.width / 2));
    if (player.health <= 0 || player.pos.y > 1000) if (state.deathTimer <= 0) { state.deathTimer = 180; state.deathString = "YOU DIED"; spawnDeathShower(player.pos, player.facing, 3); speakVulgarity('death'); }
    onPlayerUpdate(player.health, player.specialCharges, player.specialChargeTimer, player.weaponAmmo, state.shouldSyncWeapon ? 'GUN' : undefined);
    if (state.shouldSyncWeapon) state.shouldSyncWeapon = false;
  }, [status, stageId, currentWeapon, respawn, invincibilityEnabled, infiniteAmmoEnabled, infinitePowerEnabled, jumpToBossEnabled, onPlayerUpdate, spawnDamageNumber, spawnDeathShower, speakVulgarity, playGunSound, spawnExplosion, spawnSteamExplosionParticles, spawnPoopExplosion, spawnGlassShatter, onBossDeath, onIntroComplete, onBossEncounter, onBossTransition]);

  const drawPlayer = useCallback((ctx: CanvasRenderingContext2D, p: Player & { killSatisfactionTimer: number, bossKillSatisfactionTimer: number }) => {
    const state = gameStateRef.current; if (state.deathTimer > 0) return;
    ctx.save(); let dX = p.pos.x, dY = p.pos.y, dW = p.width, dH = p.height;
    if (p.isDucking) { dY += 28; dH -= 28; } else if (p.jumpPrepTimer > 0) { dY += 15; dH -= 15; }
    if (p.isUppercutting) { dH += 30; dW -= 10; dY -= 30; dX += 5; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(dX - 5, dY - 5, dW + 10, dH + 10); ctx.globalAlpha = 1.0; } 
    else if (p.isCharging) { dW += 20; ctx.fillStyle = COLORS.MEATHEAD_GLOW; ctx.globalAlpha = 0.3; ctx.fillRect(dX - 10, dY - 5, dW + 20, dH + 10); ctx.globalAlpha = 1.0; }
    if (p.filthShieldTimer && p.filthShieldTimer > 0) { ctx.save(); ctx.globalAlpha = 0.5 + Math.sin(state.frame * 0.15) * 0.2; ctx.fillStyle = '#ADFF2F'; ctx.beginPath(); ctx.arc(dX + dW/2, dY + dH/2, Math.max(dW, dH) * 0.9, 0, Math.PI * 2); ctx.fill(); ctx.restore(); }
    if (!(p.invincibilityTimer > 0 && Math.floor(state.frame / 5) % 2 === 0)) { ctx.fillStyle = COLORS.MEATHEAD_SKIN; ctx.fillRect(dX, dY, dW, dH * 0.6); ctx.fillStyle = COLORS.MEATHEAD_PANTS; ctx.fillRect(dX, dY + dH * 0.6, dW, dH * 0.4); }
    const eY = dY + (p.isDucking ? 5 : 10), eSp = 12, eSz = 6, cX = dX + dW / 2, lX = cX - (p.facing === 1 ? eSp / 2 : eSp / 2 + 5), rX = cX + (p.facing === 1 ? eSp / 2 + 5 : eSp / 2), mY = p.isDucking ? 7 : 22;
    ctx.fillStyle = 'black'; ctx.beginPath(); ctx.arc(lX, eY, eSz, 0, Math.PI*2); ctx.fill(); ctx.beginPath(); ctx.arc(rX, eY, eSz, 0, Math.PI*2); ctx.fill();
    ctx.strokeStyle = 'black'; ctx.lineWidth = 3; ctx.beginPath(); ctx.moveTo(cX - 8, eY + mY); ctx.lineTo(cX + 8, eY + mY); ctx.stroke();
    ctx.restore();
  }, []);

  const draw = useCallback(() => {
    const canvas = canvasRef.current; if (!canvas) return; const ctx = canvas.getContext('2d'); if (!ctx) return; const state = gameStateRef.current;
    if (status === GameStatus.STAGE_SELECT || status === GameStatus.START) { ctx.fillStyle = 'black'; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT); return; }
    const colors = STAGE_COLORS[stageId || ""] || { ground: COLORS.GROUND, bg: COLORS.BG_DARK, accent: '#fff' };
    ctx.fillStyle = colors.bg; ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.save(); if (state.screenShakeTimer > 0) ctx.translate((Math.random()-0.5)*15, (Math.random()-0.5)*15);
    ctx.translate(-state.camera.x, -state.camera.y);
    state.blocks.forEach(b => { ctx.fillStyle = b.type === 'door' ? '#555' : (b.type === 'pit' ? '#f00' : colors.ground); ctx.fillRect(b.x, b.type === 'door' ? b.y - state.doorOpenAmount : b.y, b.w, b.h); });
    state.enemies.forEach(e => { if (e.health <= 0 && !e.isBlownAway) return; ctx.save(); if (e.isBlownAway) { ctx.translate(e.pos.x + e.width/2, e.pos.y + e.height/2); ctx.rotate(e.rotation || 0); ctx.translate(-e.pos.x - e.width/2, -e.pos.y - e.height/2); } if (e.type === 'boss') BossLogic.drawBoss(ctx, e, stageId, state.frame); else { ctx.fillStyle = e.enemyType === 'shield' ? '#444' : (e.id.startsWith('rusher') ? '#9B59B6' : COLORS.ENEMY_TANK); ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); } if (e.isOiled) { ctx.fillStyle = 'rgba(0, 0, 0, 0.4)'; ctx.fillRect(e.pos.x, e.pos.y, e.width, e.height); } ctx.restore(); });
    drawPlayer(ctx, state.player);

    // TASER VISUALS (LOCKED AND UNLOCKED)
    if (state.player.isTasing) {
       const startX = state.player.pos.x + (state.player.facing === 1 ? state.player.width : 0), startY = state.player.pos.y + 25;
       const target = (state.enemies.find(en => en.id === state.player.taserTargetId) || state.projectiles.find(pr => pr.id === state.player.taserTargetId)) as any; 
       let endX, endY;
       if (target) { endX = target.pos.x + target.width/2; endY = target.pos.y + target.height/2; }
       else { endX = startX + state.player.facing * 350; endY = startY + (Math.random()-0.5)*40; }
       ctx.save(); ctx.strokeStyle = COLORS.TASER_BOLT; ctx.lineWidth = 3; ctx.shadowBlur = 10; ctx.shadowColor = COLORS.TASER_BOLT;
       ctx.beginPath(); ctx.moveTo(startX, startY); const segs = 8;
       for (let i = 1; i < segs; i++) { const t = i / segs, px = startX + (endX - startX) * t + (Math.random() - 0.5) * 40, py = startY + (endY - startY) * t + (Math.random() - 0.5) * 40; ctx.lineTo(px, py); }
       ctx.lineTo(endX, endY); ctx.stroke(); ctx.restore();
    }

    state.projectiles.forEach(p => { ctx.fillStyle = p.isIce ? COLORS.PROJECTILE_ICE : (p.owner === 'player' ? COLORS.PROJECTILE_PLAYER : COLORS.PROJECTILE_ENEMY); ctx.fillRect(p.pos.x, p.pos.y, p.width, p.height); });
    state.particles.forEach(p => { ctx.globalAlpha = p.life < 50 ? p.life / 50 : 1; ctx.fillStyle = p.color; ctx.fillRect(p.pos.x, p.pos.y, p.size, p.size); ctx.globalAlpha = 1.0; });
    state.damageNumbers.forEach(d => { ctx.save(); ctx.globalAlpha = d.life / d.maxLife; ctx.font = 'bold 16px "Press Start 2P"'; ctx.fillStyle = d.isCritical ? '#FFD700' : 'white'; ctx.textAlign = 'center'; ctx.fillText(d.value.toString(), d.pos.x, d.pos.y); ctx.restore(); });
    ctx.restore();
  }, [status, stageId, drawPlayer]);

  useEffect(() => {
    let frameId: number; const loop = () => { update(); draw(); frameId = window.requestAnimationFrame(loop); };
    if (status !== GameStatus.START && status !== GameStatus.STAGE_SELECT) { if (gameStateRef.current.frame === 0) createLevel(); frameId = window.requestAnimationFrame(loop); }
    return () => window.cancelAnimationFrame(frameId);
  }, [status, update, draw, createLevel]);

  return <canvas ref={canvasRef} width={CANVAS_WIDTH} height={CANVAS_HEIGHT} className="bg-black border-4 border-gray-800" />;
};

